  -- Angmar / El camino de la guerra
  [1879085026] = {
      [1] = {
      ["NAME"] = "Skathmúr"; 
      ["LORE"] = "El campamento armado de Skathmúr es responsable de patrullar los cañones de Ram Dúath, asegurándose de que estén despejados y el camino bien mantenido para que los ejércitos de Angmar puedan moverse sin ser molestados a lo largo de su extensión."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "4.92S"; 
          ["LONG"] = "36.67W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Bail Róva"; 
      ["LORE"] = "La fortaleza de Bail Róva domina la salida del Ram Dúath hacia Angmar. Para los ejércitos de Angmar, esta es la última gran fortaleza que atravesarán antes de embarcarse en sus campañas hacia el sur."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "0.22S"; 
          ["LONG"] = "34.97W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Bail Boglakh"; 
      ["LORE"] = "Bail Boglakh es un importante campamento de preparación para los ejércitos de Angmar, ya que se reúnen desde las tierras circundantes y avanzan hacia el sur.\n\nSin embargo, incluso los habitantes de este vasto campamento evitan el valle al norte, y aquellos que cuestionan las órdenes de sus superiores son arrojados por los acantilados allí hacia el inquietante silencio y la niebla de abajo, donde sus gritos pronto son silenciados por un silencio espantoso."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "3.03N"; 
          ["LONG"] = "30.44W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Mor Maudhúl"; 
      ["LORE"] = "Esta torre de vigilancia domina el gran lago de azufre de Duvuinen al sur. Desde aquí, los exploradores y comandantes pueden vigilar las hogueras de los ejércitos reunidos y observar sus movimientos mientras trazan sus planes."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "3.13N"; 
          ["LONG"] = "27.73W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Bail Dílas"; 
      ["LORE"] = "Este pequeño campamento actúa como un punto de control por el que deben pasar los viajeros y mensajeros que se dirigen a Carn Dûm antes de acercarse a las grandes puertas de la ciudad."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "10.05N"; 
          ["LONG"] = "28.06W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Puerta de las Sombras"; 
      ["LORE"] = "La Puerta de las Sombras es la gran puerta exterior de la ciudad fortaleza de Carn Dûm.\n\nAbundan las historias sobre los horrores que se encuentran dentro, pero aquí, lejos de la guerra, la pequeña ciudad asentada alrededor de la puerta podría parecer casi común si no fuera por los símbolos del poder de Angmar en cada calle y torre.\n\nEl rostro severo de los guardias sugiere que no toleran ningún indicio de rebelión o expresión por parte de los ciudadanos que vaya en contra de los deseos del Falso Rey."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "12.08N"; 
          ["LONG"] = "29.50W"; 
        }; 
      }; 
      };
  };
