  -- Montañas Nubladas / Las Alturas Aterradoras
  [1879099039] = {
      [1] = {
      ["NAME"] = "Cirith Daur"; 
      ["LORE"] = "Cirith Daur fue en tiempos uno de los pasos principales que usaban los viajeros para entrar al Paso Alto. Incluso en los mejores días, está azotado por vientos y tormentas y es traicionero de cruzar. A menudo se vuelve completamente intransitable en las últimas estaciones del año, bloqueando todo acceso entre las comunidades en los lados oriental y occidental de las Montañas Nubladas."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "23.28S"; 
          ["LONG"] = "3.47E"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "La Grieta Negra"; 
      ["LORE"] = "Esta pequeña cueva en las rocas del Paso Alto ofrece un aparente refugio para los viajeros en tiempos de tormenta, pero hace mucho se descubrió que es una entrada oculta a las madrigueras de la Ciudad de los Trasgos, desde donde los trasgos emergían en la oscuridad de la noche para raptar a quienes fueran lo bastante insensatos como para acampar aquí.\n\nHoy en día, la grieta se usa poco, pues casi nadie intenta ya cruzar el paso, y los trasgos emergen con mayor frecuencia por la puerta principal más abajo, mientras hacen ominosos preparativos de guerra."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "20.31S"; 
          ["LONG"] = "5.35E"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Dómstoll"; 
      ["LORE"] = "Dómstoll —llamado con mayor frecuencia el Trono del Gigante en oestron— es un enorme asiento de piedras masivas que se alza sobre las ruinas abandonadas de Starkhath y ofrece una vista dominante de la región circundante cuando no está oculto por nieve o niebla.\n\nLa mayoría de los gigantes abandonaron este lugar hace mucho, pero los rumores dicen que al menos uno permanece vigilando este dominio solitario."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "21.95S"; 
          ["LONG"] = "8.63E"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Fisura de Erforgh"; 
      ["LORE"] = "La Fisura de Erforgh es un enorme caos de rocas y arroyos congelados, dejado atrás por una gran masa de hielo en eras pasadas. Ahora ofrece algo de refugio contra los vientos montañosos más brutales a una tribu nómada de Gauredain que ha hecho aquí su hogar.\n\nNo está claro si los Gauredain llegaron por voluntad propia o fueron enviados aquí por el Enemigo, pero su presencia es inquietante de cualquier modo."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "29.60S"; 
          ["LONG"] = "9.15E"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Serpentinos"; 
      ["LORE"] = "Este complejo de cavernas llamado los Serpentinos parece estar formado por una gran masa de peñascos, demasiado grandes incluso para que los gigantes pudieran levantarlos. Cómo llegaron a estar así es un misterio: quizá por la caída de un pico entero sobre la ladera o por algún otro evento igualmente catastrófico.\n\nLas cavernas son curiosamente más cálidas que las laderas desoladas de afuera, posiblemente calentadas por una fuente termal que brota desde lo profundo de la montaña. Sin embargo, cualquier viajero que espere refugiarse aquí debería buscar otro sitio, pues ese mismo calor ha atraído a una enorme y letal cría de sierpes, y aventurarse dentro sin cuidado es una muerte segura."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "26.71S"; 
          ["LONG"] = "8.84E"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Starkhath"; 
      ["LORE"] = "Un grupo de viajeros que pasó por aquí hace muchos años describió un lugar donde los gigantes arrojaban peñascos a través del paso por diversión.\n\nLos gigantes parecen haber desaparecido ahora —algunos dicen que fueron expulsados cuando un nuevo Gran Trasgo tomó el trono de la Ciudad de los Trasgos y las relaciones entre ambas razas se volvieron intolerables. Con el tiempo, cansados de los tormentos de sus diminutos enemigos, los gigantes abandonaron este lugar y se dirigieron hacia Iorbar, al suroeste.\n\nSolo quedan las enormes losas de piedra que usaban como refugio, resonando ahora con los aullidos de los huargos que merodean entre ellas."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "20.95S"; 
          ["LONG"] = "8.02E"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Hrimbarg"; 
      ["LORE"] = "Fundado antes que la ciudad de Helegrod, Hrimbarg fue llamado en su día “La Corona de las Montañas Nubladas” por los enanos que vivían allí, y era considerado la morada más elevada de su pueblo en todo el mundo de aquella época.\n\nLamentablemente, no cayó ante trasgos, gigantes, dragones ni otra maldad alguna —los relatos dicen que cayó ante una gran tormenta que descendió sobre el Paso Alto y no cedió durante cinco largos años, bloqueando los pasos con gigantescas montañas de hielo y enterrando incluso a Hrimbarg bajo un profundo y uniforme manto de nieve.\n\nCuando al fin la tormenta cedió y sus parientes de Moria llegaron desde el norte para socorrer a sus hermanos, no hallaron a un solo enano con vida: todos habían muerto de frío o hambre durante los largos años de aislamiento. Se decidió entonces que Hrimbarg no debía ser repoblado, y ha permanecido vacío desde tiempos inmemoriales."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "24.45S"; 
          ["LONG"] = "6.95E"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Akûltot"; 
      ["LORE"] = "Construido recientemente desde la ascensión del nuevo Gran Trasgo de la Ciudad de los Trasgos, el campamento de Akûltot se sitúa entre repisas y agujas de roca que dominan la aproximación a las puertas principales de la Ciudad de los Trasgos. Históricamente, los trasgos de las Montañas Nubladas han evitado construir campamentos en los ventisqueros inhóspitos y la luz implacable del Paso Alto, por lo que resulta inquietante que lo hagan ahora.\n\nLa única explicación probable es que se están preparando para extender su dominio más allá de las montañas de algún modo, lo cual sin duda es una mala noticia para quienes viven en las colinas y bosques más abajo."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "21.50S"; 
          ["LONG"] = "4.51E"; 
        }; 
      }; 
      };
  };
  -- Montañas Nubladas / Ciudad de los Trasgos
  [1879099040] = {
      [1] = {
      ["NAME"] = "Fortines de Guerra"; 
      ["LORE"] = "El Fortín de Guerra sirve como un enorme cuartel para la Ciudad de los Trasgos, donde sus soldados y hostigadores se reúnen y preparan incursiones contra las aldeas a ambos lados de las Montañas. En su mayoría descienden por los pasajes hacia el este para atacar los asentamientos de Hombres más pequeños y débilmente defendidos que lindan con el Bosque Negro, pero en ocasiones, cuando sus fuerzas crecen, se han atrevido incluso a asaltar comunidades élficas en los límites del dominio de Rivendel... aunque estos ataques temerarios suelen terminar mal para los trasgos, y pocos regresan."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "64.03S"; 
          ["LONG"] = "54.54E"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Retrueno"; 
      ["LORE"] = "Retrueno recibe su nombre por los enormes retumbos que resuenan en las cuevas y pasadizos cercanos. Este “trueno” lo producen los inmensos tambores cargados por los trolls de las cavernas criados y esclavizados por los trasgos, utilizados cuando atacan asentamientos más grandes bajo el amparo de la noche."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "66.43S"; 
          ["LONG"] = "54.90E"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Cercados de Esclavos"; 
      ["LORE"] = "El hedor y el horror de los Cercados de Esclavos de la Ciudad de los Trasgos son tema de sombríos rumores entre los viajeros que se atreven a cruzar el Paso Alto, pues es bien sabido que los trasgos disfrutan capturando a tales desdichados para arrastrarlos a las profundidades de las Montañas, donde los obligan a realizar labores crueles en la oscuridad... y pocos vuelven a ver la luz del día."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "64.92S"; 
          ["LONG"] = "54.84E"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Cueva de Gollum"; 
      ["LORE"] = "La Cueva de Gollum es un lago oscuro y silencioso, anidado cerca de las raíces de las Montañas Nubladas, y se dice que incluso los trasgos le temen y rara vez se acercan.\n\nEl célebre hobbit saqueador Bilbo Bolsón llegó a esta cueva por accidente hace mucho tiempo y allí conoció a la criatura miserable llamada Gollum. Se dice que ganó su libertad en un juego de acertijos, aunque algunos rumores afirman que no jugó con total justicia."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "63.58S"; 
          ["LONG"] = "55.68E"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "La Guarida del Gran Trasgo"; 
      ["LORE"] = "La sala del trono de la Ciudad de los Trasgos, la Guarida del Gran Trasgo, no es un lugar donde la mayoría de los viajeros desearían encontrarse. Con un extraño y retorcido sentido de la justicia, los trasgos suelen llevar a sus prisioneros ante el Gran Trasgo para enfrentar su juicio en lugar de simplemente encarcelarlos o matarlos. Sus juicios suelen versar sobre espionaje o entrada indebida en su dominio.\n\nPor desgracia para los pobres cautivos, el resultado está decidido de antemano, y el castigo por tales faltas es siempre desagradable... y finalmente fatal."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "64.41S"; 
          ["LONG"] = "54.79E"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "los Fuegos Profundos"; 
      ["LORE"] = "Esta sofocante cueva alberga las fraguas de la Ciudad de los Trasgos, donde crueles instrumentos de guerra y tortura son forjados por herreros demasiado ingeniosos, cuyo conocimiento proviene de eras antiguas cuando el Señor Oscuro les enseñó los secretos de la metalurgia."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "69.18S"; 
          ["LONG"] = "56.27E"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Eglanúr"; 
      ["LORE"] = "El verdadero origen de las ruinas que se encuentran dispersas por estas cavernas es desconocido. Está claro que en tiempos antiguos los enanos excavaron aquí y construyeron túneles y minas, pero este lugar fue perdido y abandonado a los trasgos hace tanto tiempo que incluso entre el Pueblo de Durin pocos recuerdan el nombre de quienes lo edificaron o cómo llegó su historia a su fin."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "66.93S"; 
          ["LONG"] = "55.47E"; 
        }; 
      }; 
      };
  };
  -- Bosque de los Trolls / Las Tierras Salvajes de Tâl Bruinen
  [1879099041] = {
      [1] = {
      ["NAME"] = "Cirith Ulunn"; 
      ["LORE"] = "Aunque pueden encontrarse sierpes dispersos en otras zonas del Bosque de los Trolls, la estirpe que vive aquí se ha vuelto especialmente numerosa y mortal. En verdad, los instintos de caza agresivos de estas bestias feroces disuaden en gran medida a los pocos exploradores y colonos que, de otro modo, intentarían ganarse la vida en las Tierras Salvajes de Tâl Bruinen."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "37.63S"; 
          ["LONG"] = "11.25W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Echad Candelleth"; 
      ["LORE"] = "Se cree entre los eruditos que la ruina de Echad Candelleth fue en tiempos un centro de arte y aprendizaje en el antiguo reino de Rhudaur, antes de caer bajo la influencia corrupta de Angmar y ser destruida en guerras con sus vecinos, tras lo cual incluso su nombre original se perdió.\n\nAhora simplemente sirve como un campamento improvisado para aquellas almas resistentes lo bastante valientes como para explorar las tierras salvajes circundantes."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "37.20S"; 
          ["LONG"] = "13.97W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Eryn Singor"; 
      ["LORE"] = "Aunque es un espectáculo digno de contemplar, los viajeros que se dejan seducir por la belleza natural de Eryn Singor rara vez emergen de sus traicioneros barrancos.\n\nUna hueste de trolls silvanos ha tomado residencia allí y se deleita en abalanzarse sobre cazadores y exploradores incautos para despedazarlos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "35.31S"; 
          ["LONG"] = "16.51W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Echad Gauradan"; 
      ["LORE"] = "Aunque los hombres civilizados abandonaron estas colinas hace mucho tiempo, una tribu de hombres salvajes se ha asentado aquí recientemente, y parecen sentirse en casa entre las bestias peligrosas y los riesgos naturales de la región.\n\nLamentablemente, tienen un talante feroz y muestran un odio evidente hacia quienes irrumpen en su territorio desde tierras más civilizadas."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "38.23S"; 
          ["LONG"] = "16.16W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Torech Ullug"; 
      ["LORE"] = "Se dice que existe un área de anidación para los numerosos sierpes que infestan Tâl Bruinen, y parece que has tropezado con ella aquí, en Torech Ullug.\n\n¡Ten cuidado! Las madres de los gusanos anidadores son conocidas por su disposición especialmente feroz, así como por su apetito voraz de carne fresca para alimentar a sus crías."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "39.71S"; 
          ["LONG"] = "14.62W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Delossad"; 
      ["LORE"] = "¿Qué son estas extrañas ruinas? Parecen de antiguas raíces cardolanas, pero los Elfos de Rivendel se muestran reacios a hablar de ellas. Algún extraño misterio las rodea, y puede que las únicas respuestas se encuentren en su interior..."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "38.20S"; 
          ["LONG"] = "13.00W"; 
        }; 
      }; 
      };
  };
  -- Montañas Nubladas / Los Botones de Bilbo
  [1879099095] = {
      [1] = {
      ["NAME"] = "Montón de escombros"; 
      ["PROGRESS"] = "Encuentra el botón manchado"; 
      ["LORE"] = "Un botón de latón manchado con algo... ¿sangre, quizá?\n\nEn cualquier caso, sin duda no es una reliquia trasga —se parece más a algo que encontrarías en el chaleco de un hobbit..."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "71.28S"; 
          ["LONG"] = "55.57E"; 
        }; 
      }; 
      };
      [2] = {
        "Encuentra el botón deslustrado - Este curioso botón de latón está muy deslustrado y desgastado... pero en algún momento debió lucir en un abrigo o chaqueta bastante fina. ¿Cómo habrán conseguido esto los trasgos?";
      };
      [3] = {
      ["NAME"] = "Montón de desechos"; 
      ["PROGRESS"] = "Encuentra el botón pulido"; 
      ["LORE"] = "Este botón de latón es viejo y está gastado, pero parece que algún trasgo curioso lo pulió recientemente. Debió llevarlo como una especie de recuerdo."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "66.30S"; 
          ["LONG"] = "54.83E"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Cofre maltrecho"; 
      ["PROGRESS"] = "Encuentra el botón arañado"; 
      ["LORE"] = "Qué extraño —¿un botón de chaleco de latón en las profundidades de la Ciudad de los Trasgos? El frente del botón parece muy arañado, quizá contra la roca en algún momento remoto."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "63.93S"; 
          ["LONG"] = "54.21E"; 
        }; 
      }; 
      };
      [5] = {
        "Encuentra el botón doblado - Este adorno de latón parece fuera de lugar en los oscuros túneles de la Ciudad de los Trasgos. También parece haber sido doblado, quizá en el incidente que lo separó del chaleco al que una vez perteneció.";
      };
      [6] = {
      ["NAME"] = "Bolsa descartada"; 
      ["PROGRESS"] = "Encuentra el botón brillante"; 
      ["LORE"] = "Este botón de latón está sorprendentemente bien conservado, y aún puede verse débilmente el diseño grabado que lo identifica como obra de la Comarca... ¡pero qué hobbit en su sano juicio se aventuraría en las profundidades de la Ciudad de los Trasgos llevando un chaleco!?"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "63.60S"; 
          ["LONG"] = "54.70E"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Saco arruinado"; 
      ["PROGRESS"] = "Encuentra el gemelo roto"; 
      ["LORE"] = "Interesante —esto parece un gemelo que antaño pudo haber estado de moda entre los hobbits de la Comarca, pero la varilla está rota y ahora tiene poco valor."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "67.55S"; 
          ["LONG"] = "55.53E"; 
        }; 
      }; 
      };
      [8] = {
        "Encuentra el gemelo ennegrecido - Este gemelo parece que en su día pudo ser una pieza de joyería bastante fina —probablemente de manufactura hobbit—, pero ahora está ennegrecido y deteriorado, quizá porque algún torpe trasgo lo dejó caer en un brasero hace mucho tiempo.";
      };
  };
