  -- Moria / Baluartes del Enemigo
  [1879146846] = {
      [1] = {
      ["NAME"] = "Menem-berej"; 
      ["LORE"] = "La gran fosa de Menem-berej albergaba una de las vetas de mithril más ricas jamás descubierta en Khazad-dûm, y esta enorme plataforma fue construida para ayudar a los enanos en sus esfuerzos por extraer el precioso metal. Aunque se creía que esta mina ya estaba agotada para el momento de la caída de Khazad-dûm, los enanos de la expedición esperan encontrar algunas vetas restantes para demostrar el valor de esta peligrosa incursión, y atraer a más de sus hermanos del extranjero para ayudarlos a reclamar su antiguo hogar."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "11.04S"; 
          ["LONG"] = "112.75W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Harâzgund"; 
      ["LORE"] = "La puerta de Harâzgund conduce a la fuente de uno de los mayores canales de Khazad-dûm. En su momento, suministraba agua a casi la mitad de todos los enanos que vivían bajo estas montañas, pero fue destruida por alguna calamidad desconocida durante los largos años oscuros tras la caída de Durin. Ahora el agua yace aquí inmóvil, inundando las profundidades en grandes charcos estancados."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "17.60S"; 
          ["LONG"] = "116.93W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Las Forjas de Khazad-dûm"; 
      ["LORE"] = "Las Forjas de Khazad-dûm eran incomparables, las más grandes de todas las forjas en la Tercera Edad de la Tierra Media. Los enanos no descansarán hasta que sean reclamadas, ya que gran parte del arte invaluable nacido en esa sala se ha perdido durante los largos años de abandono de Moria."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "16.98S"; 
          ["LONG"] = "109.75W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Fil Gashan"; 
      ["LORE"] = "Los orcos de Fil Ghashan son sospechosamente vigilantes, siempre meditando sobre su esperanzado asalto contra Lothlórien. No muestran piedad a ninguno que se atreva a amenazar sus planes."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "17.07S"; 
          ["LONG"] = "109.58W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "La Puerta en Ruinas"; 
      ["LORE"] = "La Puerta de la Ruina se abre a la Escalera Interminable de Khazad-dûm, pero como su nombre sugiere, esta entrada a las escaleras ha sido destrozada y yace en ruinas."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "10.20S"; 
          ["LONG"] = "103.88W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Skûmfil"; 
      ["LORE"] = "Las tumbas de orcos en Skûmfil han criado muchas criaturas repugnantes, todas fortalecidas por la carne de los muertos y consumidas por pensamientos malvados."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "13.21S"; 
          ["LONG"] = "100.41W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Excavaciones Tenebrosas"; 
      ["LORE"] = "Las Excavaciones Tenebrosas deberían haber sido olvidadas, ya que están habitadas por criaturas antiguas y malvadas que no tienen lugar en la Tierra Media."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "15.85S"; 
          ["LONG"] = "97.28W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "La Decimosexta Sala"; 
      ["LORE"] = "La Sala Decimosexta es ahora el hogar de la enfermedad fúngica que envenena a muchos orcos y los convierte en Globsnaga corruptos. Un gran mal se está gestando en esta sala, amenazando con cubrir Moria de enfermedad y miedo."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "11.07S"; 
          ["LONG"] = "101.00W"; 
        }; 
      }; 
      };
  };
  -- Moria / Sigue el camino de la Comunidad a través de Moria.
  [1879146847] = {
      [1] = {
      ["NAME"] = "Umbral de Durin"; 
      ["LORE"] = "El umbral de la puerta occidental de Khazad-dûm, fue aquí donde Durin completó su legendario viaje a través del corazón de las montañas y volvió a la luz del sol, habiendo descubierto el lugar que se convertiría en el hogar de su pueblo por generaciones."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "8.00S"; 
          ["LONG"] = "115.84W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Cámara de la Encrucijada"; 
      ["LORE"] = "Esta antigua sala de guardia controla los pasajes que conducen al Camino de Durin, así como los que se dirigen al este, hacia la Sala Vigesimoprimera. Ahora está ocupada por parte de la expedición de enanos para reclamar Moria de los orcos y trasgos que ahora la dominan."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "5.09S"; 
          ["LONG"] = "112.08W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "La Sala Vigesimoprimera"; 
      ["LORE"] = "La Sala Vigesimoprimera es una de las más grandes de toda Khazad-dûm, y a menudo se la considera la más famosa. En tiempos antiguos, un gran mercado se encontraba aquí, donde los enanos de Moria y los viajeros del extranjero comerciaban con productos finos de toda la Tierra Media. Maderas finas, vinos y alimentos se intercambiaban por oro, gemas invaluables y piezas de herrería finamente trabajadas. En verdad, casi cualquier cosa se podía comprar o vender en esta sala, aunque ahora es difícil imaginarlo."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "21.79N"; 
          ["LONG"] = "119.16W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Cámara de Mazarbul"; 
      ["LORE"] = "Es probable que la Cámara de Mazarbul sirviera a algún gran propósito ceremonial en los viejos días de Moria; ahora sigue siendo la tumba de Balin, hijo de Fundin y amigo del viejo Bilbo, quien, no hace tantos años, lideró una expedición muy parecida a la actual para retomar Moria y restaurarla a las glorias del pasado."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "22.85N"; 
          ["LONG"] = "119.25W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "El Puente de Khazad-dûm"; 
      ["PROGRESS"] = "Encuentra el puente de Khazad-dûm (arco oeste)"; 
      ["LORE"] = "El puente de Khazad-dûm fue concebido como una antigua defensa diseñada para disuadir a cualquiera que pudiera buscar invadir la ciudad. El abismo que cruza es uno de los más grandes de Moria, y ha estado aquí desde que la ciudad fue fundada hace miles de años. Ahora el puente yace en ruinas, su tramo occidental sobresaliendo tristemente sobre las profundidades del abismo, la piedra misma destrozada y chamuscada por fuerzas desconocidas."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "8.00S"; 
          ["LONG"] = "99.19W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "El Puente de Khazad-dûm"; 
      ["PROGRESS"] = "Encuentra el puente de Khazad-dûm (arco este)"; 
      ["LORE"] = "El puente de Khazad-dûm ha estado sobre este gran abismo durante muchas edades, pero ya no es así. La parte oriental ahora se extiende como un dedo apuntando hacia la oscuridad más allá. Parece que lo que destruyó el puente ocurrió no hace mucho, ya que todavía se pueden ver ocasionalmente fragmentos de roca desprendiéndose de la punta destrozada para caer en el abismo, y flechas frescas salpican la mampostería allí."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "8.00S"; 
          ["LONG"] = "98.55W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "La Primera Sala"; 
      ["LORE"] = "La Primera Sala era la entrada original a Khazad-dûm, donde Durin puso por primera vez los pies en las cavernas que algún día se convertirían en la ciudad más grande de los enanos, y de hecho, en la ciudad más duradera de cualquier pueblo en la larga historia de la Tierra Media, hasta que finalmente cayó en ruinas."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "8.00S"; 
          ["LONG"] = "96.08W"; 
        }; 
      }; 
      };
  };
