  -- Minas de Moria / Cartas a Igash
  [1879147153] = {
      [1] = {
        "Encuentra objetos valiosos en el Tesoro Olvidado.";
      };
      [2] = {
        "Encuentra Los tambores y la Bestia - En esta carta, Igash es informado sobre los planes para despertar a la gran bestia que duerme en un rincón apartado de la Gran Escalera.";
      };
      [3] = {
        "Encuentra el informe de las perreras de Altopico - El informe de las perreras de Altopico detalla los planes secretos de los adiestradores de huargos en la Gran Escalera, quienes crian huargos en gran número para lanzar un asalto contra los enanos de Moria.";
      };
      [4] = {
        "Encuentra la petición de ayuda de los leales - Los orcos leales a Igash parecen haber conocido un horrendo final poco después de escribir esta nota apresurada, pidiendo ayuda contra una rebelión secreta de la Mano Blanca. La solicitud de ayuda no llegó a manos de a quien estaba dirigida.";
      };
      [5] = {
        "Encuentra el Tomo de Igash - Este documento es un registro de los logros de Igash desde el establecimiento de su mandato en la Gran Escalera.";
      };
  };
