  [1879175386] = {
      [1] = {
      ["NAME"] = "Colina del Aullador de la Manada"; 
      ["PROGRESS"] = "Descubre la Colina del Aullador de la Manada"; 
      ["LORE"] = "Esta colina aislada en los Troncosombríos es un punto de reunión para las manadas de lobos del Bosque Negro; aullidos lamentables se pueden escuchar a menudo en el viento desde esta dirección."; 
      ["POINTS"] = {
