      [2] = {
      ["NAME"] = "Gorogrod"; 
      ["PROGRESS"] = "Descubre Gorogrod"; 
      ["LORE"] = "Gorogrod es un oscuro y malvado escondite de las arañas de las Hondonadas Enmarañadas, lleno de trampas peligrosas y telarañas pegajosas. Incluso el viajero más experimentado debe tener cuidado antes de aventurarse aquí, ya que las arañas están entre los enemigos más mortales de la Tierra Media. Las arañas de las crías del Bosque Negro ciertamente no son una excepción."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "8.84S"; 
          ["LONG"] = "51.24W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Sâd Meryrn"; 
      ["PROGRESS"] = "Descubre Sâd Meryrn"; 
      ["LORE"] = "Incluso los árboles pueden ser corrompidos por influencias malignas, y los Ucornos del Bosque Negro pasan sus largos días volviéndose cada vez más oscuros y corruptos. Su hogar, Sâd Meryrn, es un lugar triste y solitario, lleno de la malicia de los árboles."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.71S"; 
          ["LONG"] = "57.98W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Estanque de la Muerte Rastrera"; 
      ["PROGRESS"] = "Descubre el Estanque de la Muerte Rastrera"; 
      ["LORE"] = "Las aguas corrompidas del Bosque Ahogado están contaminadas por muchos años de corrupción, y el corazón de la enfermedad en el pantano es el Estanque de la Muerte Rastrera, hogar de muchos cadáveres y criaturas desagradables."; 
      ["POINTS"] = {
