  -- Raza y sociedad / Cartógrafo -- Moria
  [1879206033] = {
      [1] = {
        "Obtén la carta de los Muros de Moria - También llamada Puerta de Acebeda, este mapa muestra el área que rodea la entrada a Moria.";
      };
      [2] = {
        "Obtén la carta de las Vetas del Cuerno de Plata - Este es un mapa de la zona de Moria que los enanos llaman las Vetas del Cuerno de Plata.";
      };
      [3] = {
        "Obtén la carta del Camino de Durin - Este mapa muestra la vía principal de Moria, también llamada el Camino de Durin.";
      };
      [4] = {
        "Obtén la carta de las Obras Hidráulicas - Este mapa de las Obras Hidráulicas de Moria muestra las secciones antiguas y ahora inundadas de la gran área del reino profundo.";
      };
      [5] = {
        "Obtén la carta de Zelem-melek - Este mapa destaca la zona de Moria conocida como Zelem-melek";
      };
      [6] = {
        "Obtén la carta de Nud-melek - Este mapa destaca los lugares importantes de la zona conocida como Nud-melek en Moria.";
      };
      [7] = {
        "Obtén la carta de las Fundaciones de Piedra - Este mapa detalla la ubicación conocida como las Fundaciones de Piedra dentro de Moria.";
      };
      [8] = {
        "Obtén la carta de las Vetas del Cuerno Rojo - Este mapa destaca los lugares importantes de la zona conocida como las Vetas del Cuerno Rojo en Moria.";
      };
      [9] = {
        "Obtén la carta de Zirakzigil - Este mapa muestra una ubicación en el lateral de las montañas fuera de Moria.";
      };
      [10] = {
        "Obtén un mapa de las Profundidades Llameantes - Este mapa destaca los lugares importantes de las áreas conocidas como las Profundidades Llameantes en Moria.";
      };
      [11] = {
        "Obtén un mapa del Gran Escalera - Este mapa detalla una ubicación que alguna vez fue un cruce importante de pasajes en Moria; ahora, es el hogar de muchas facciones de trasgos en las profundidades.";
      };
  };
  -- Raza y sociedad / Cartógrafo -- Eriador
  [1879206037] = {
      [1] = {
        "Obtén el mapa del Bosque Viejo - El Bosque Viejo es un lugar que es mejor evitar, ya que los peligros se encuentran en cada esquina. Has obtenido una copia de un mapa del Bosque Viejo.";
      };
      [2] = {
        "Obtén el mapa de Archet - Un pequeño pueblo en Bree, Archet, fue recientemente incendiado por los bandidos Montebruno. Has adquirido un mapa del pueblo y sus alrededores.";
      };
      [3] = {
        "Obtén el mapa de Bree - Bree es la ciudad principal de las Tierras de Bree. Lugares famosos como la Posada del Poney Pisador y la Fuente del Jabalí se encuentran en la ciudad. Has encontrado un mapa maravilloso de Bree.";
      };
      [4] = {
        "Obtén el mapa de Annúminas - Antaño hogar de los Reyes de los Hombres, Annúminas es ahora una ciudad inundada en la orilla sur del Lago Evendim, en la región de Evendim. Este es el mapa de la ciudad.";
      };
      [5] = {
        "Obtén el mapa de las Landas de Etten - Las Landas de Etten son una región olvidada del mundo, donde el mal se ha infiltrado en casi todas partes. Este es un mapa de la zona.";
      };
      [6] = {
        "Obtén el mapa de las Quebradas de los Túmulos del Norte - Los Hombres de Bree intentan mantenerse alejados de los antiguos túmulos funerarios de los Hombres de Cardolan, ya que se rumorea que criaturas aterradoras salen de la tierra para acechar a los que se encuentran entre los túmulos. Este es un mapa de la parte norte de la Quebrada de los Túmulos.";
      };
      [7] = {
        "Obtén el mapa de Rivendel - Rivendel es el valle oculto donde habitan los Elfos, en la frontera de las Montañas Nubladas y el Bosque de los Trolls. Este es un mapa de ese valle.";
      };
      [8] = {
        "Obtén el mapa de Eregion - Eregion fue hogar de los Elfos en tiempos pasados; ahora, las ruinas cubren un paisaje árido. Este es un mapa de esa tierra.";
      };
      [9] = {
        "Obtén el mapa de Enedwaith - Una sección de tierra que se extiende hacia el sur entre Eregion y las Tierras Brunas, Enedwaith es una tierra dura de piedra y naturaleza salvaje. Este es un mapa de la región.";
      };
      [10] = {
        "Obtén el mapa de la Puerta de Thorin - Esta pequeña comunidad de enanos descansa a la sombra de la Mansión de Thorin. Este es un mapa de esa zona.";
      };
      [11] = {
        "Obtén el mapa de Forochel - Una tierra fría y desolada reclamado por los Lossoth, Forochel se encuentra al norte. Este es un mapa de esas tierras heladas.";
      };
      [12] = {
        "Obtén el mapa del Risco Invernal - Una ciudad de ricos y pobres que necesitan ayuda durante los meses invernales. Este es un mapa de la ciudad.";
      };
      [13] = {
        "Obtén el mapa de las Quebradas de los Túmulos del Sur - La sección sur de las Quebradas de los Túmulos alberga más ruinas y montículos de antiguos Hombres. Este es un mapa de la zona.";
      };
      [14] = {
        "Obtén el mapa de las Tierras de Bree - Una tierra fértil donde muchos Hombres hacen sus hogares. Este es un mapa de la zona.";
      };
      [15] = {
        "Obtén el mapa de La Comarca - Un lugar que la mayoría de los hobbits consideran su hogar. La Comarca es una colección de muchos territorios más pequeños que conforman la gran tierra perteneciente a los hobbits. Este es un mapa de la zona.";
      };
      [16] = {
        "Obtén el mapa de Ered Luin - Ered Luin es el hogar tanto de Elfos como de enanos, y a ninguno de los dos les gusta mezclarse con el otro. Este es un mapa de la zona.";
      };
      [17] = {
        "Obtén el mapa de las Tierras Solitarias - Las Tierras Solitarias son un tramo solitario que se extiende hacia el este a través de las ruinas de los Hombres. Este es un mapa de la zona.";
      };
      [18] = {
        "Obtén el mapa de las Quebradas del Norte - La guerra ha llegado a los Hombres de las Quebradas del Norte, y necesitan ayuda. Este es un mapa de la zona.";
      };
      [19] = {
        "Obtén el mapa del Bosque de los Trolls - La tierra aquí es inhóspita y sombría, con trolls vagando por las tierras salvajes día y noche. Este es un mapa de la zona.";
      };
      [20] = {
        "Obtén el mapa de las Montañas Nubladas - El viento frío y el filo de las espadas forjadas por los trasgos esperan a los viajeros en las Montañas Nubladas. Este es un mapa de la zona.";
      };
      [21] = {
        "Obtén el mapa de Angmar - La tierra árida donde una vez gobernó el Rey Brujo. Ahora, la tierra está arruinada y el mal se extiende libremente y casi sin control. Este es un mapa de la zona.";
      };
  };
