  -- Épica / Exploración de Lhaid Ogo
  [1879206112] = {
      [1] = {
      ["NAME"] = "Lhaid Ogo es una serie de túneles bajo los Acantilados del Liche, en Enedwaith. Sus pasajes están atascados de barro y no parecen del todo estables."; 
      ["PROGRESS"] = "Adéntrate en Lhaid Ogo y desentraña sus misterios"; 
      ["LORE"] = "Lhaid Ogo es una serie de túneles bajo los Acantilados del Liche, en Enedwaith. Sus pasajes están atascados de barro y no parecen del todo estables."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "95.60S"; 
          ["LONG"] = "54.77E"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Atrapado detrás de una pared de madera en las profundidades de Lhaid Ogo, encontraste el cuerpo de un antiguo desafortunado. ¿Murió allí, en la pared, o fue movido a ese lugar para languidecer durante edades?"; 
      ["PROGRESS"] = "Encuentra al antiguo explorador desafortunado"; 
      ["LORE"] = "Atrapado detrás de una pared de madera en las profundidades de Lhaid Ogo, encontraste el cuerpo de un antiguo desafortunado. ¿Murió allí, en la pared, o fue movido a ese lugar para languidecer durante edades?"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "95.44S"; 
          ["LONG"] = "55.10E"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "El puente de madera era de construcción ancestral, pero la humedad pudrió parte de las barandas. El hueco podría usarse para dejarse caer al pasaje inferior, aunque sería un viaje de solo ida."; 
      ["PROGRESS"] = "Encuentra el hueco en el puente"; 
      ["LORE"] = "El puente de madera era de construcción ancestral, pero la humedad pudrió parte de las barandas. El hueco podría usarse para dejarse caer al pasaje inferior, aunque sería un viaje de solo ida."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "95.53S"; 
          ["LONG"] = "55.77E"; 
        }; 
      }; 
      };
      [4] = {
        "Encuentra la bolsa abandonada";
      };
      [5] = {
      ["NAME"] = "Alguien estaba comiendo una rata en las profundidades de Lhaid Ogo, pero ¿quién? ¿Y qué hizo que no la terminara?"; 
      ["PROGRESS"] = "Encuentra la cena sin terminar"; 
      ["LORE"] = "Alguien estaba comiendo una rata en las profundidades de Lhaid Ogo, pero ¿quién? ¿Y qué hizo que no la terminara?"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "95.82S"; 
          ["LONG"] = "55.02E"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "El Tragabarro ha acechado los pasajes de Lhaid Ogo durante muchos años y hace su guarida en la cámara más profunda. Arrastra a su presa de vuelta a su guarida antes de devorarla."; 
      ["PROGRESS"] = "Encuentra la guarida del Tragabarro"; 
      ["LORE"] = "El Tragabarro ha acechado los pasajes de Lhaid Ogo durante muchos años y hace su guarida en la cámara más profunda. Arrastra a su presa de vuelta a su guarida antes de devorarla."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "95.53S"; 
          ["LONG"] = "55.95E"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "En lo profundo de Lhaid Ogo, encontraste señales de que algo pesado fue arrastrado por una pendiente embarrada, llenándote de preocupación."; 
      ["PROGRESS"] = "Encuentra la pendiente de tierra removida"; 
      ["LORE"] = "En lo profundo de Lhaid Ogo, encontraste señales de que algo pesado fue arrastrado por una pendiente embarrada, llenándote de preocupación."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "95.68S"; 
          ["LONG"] = "55.71E"; 
        }; 
      }; 
      };
  };
