  [1879230977] = {
      [1] = {
      ["NAME"] = "Puesto de guardia del Limclaro"; 
      ["PROGRESS"] = "Descubre la Casa de la Puerta del Limclaro"; 
      ["LORE"] = "Cuando los últimos habitantes de la Garganta del Limclaro fueron expulsados por la llegada de trolls desde las Montañas Nubladas, los Rohirrim erigieron este puesto de guardia para vigilar la entrada de la Garganta y asegurarse de que nada saliera de ella sin ser visto. Afortunadamente, los trolls no se atreven a alejarse demasiado de las cuevas y salientes bajo los que se refugian durante los días despejados, por lo que no han intentado salir de la Garganta."; 
      ["POINTS"] = {
