      };
      [2] = {
      ["NAME"] = "Cataratas del Limclaro"; 
      ["PROGRESS"] = "Descubre las Cataratas del Limclaro"; 
      ["LORE"] = "Las Cataratas del Limclaro marcan el punto más bajo de las colinas que descienden de las Montañas Nubladas, mientras el río caudaloso se vacía hacia las llanuras del sur.\n\nEl frío arroyo garantiza un suministro constante de agua fresca para la comunidad de Stangard."; 
      ["POINTS"] = {
