      [3] = {
      ["NAME"] = "Claro del Limclaro"; 
      ["PROGRESS"] = "Descubre el Bosque de los Ents"; 
      ["LORE"] = "La parte más al norte del bosque de Fangorn termina aquí, en las orillas del río Limclaro.\n\nLos Ents han tenido durante mucho tiempo un pequeño lugar de reunión aquí, donde antaño se encontraban con los Elfos de Lothlórien para conocer las noticias del mundo exterior."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "29.41S"; 
          ["LONG"] = "72.08W"; 
