      }; 
      };
      [5] = {
      ["NAME"] = "El Agujero del Río"; 
      ["PROGRESS"] = "Descubre el Agujero del Río"; 
      ["LORE"] = "Esta antiguo Agujero del Río permanece desde tiempos lejanos, cuando el curso del Limclaro se extendía más arriba en la Garganta. Dejó este agujero extrañamente suavizado al cambiar de curso.\n\nAhora, por desgracia, parece que los trolls han tomado residencia en sus profundas sombras."; 
      ["POINTS"] = {
