  -- Rohan Oriental / Explorador / Exploradora de la Muralla del Este
  [1879244108] = {
      [1] = {
      ["NAME"] = "Campamento de Mansig"; 
      ["PROGRESS"] = "Descubre el Campamento de Mansig"; 
      ["LORE"] = "Este campamento de los Rohirrim proviene principalmente del Páramo, pero hay representantes de todo el reino de Rohan. Llegaron a la Muralla del Este bajo el mando de Mansig. Su propósito era investigar la reciente concentración de Orcos y Uruks que cruzaron el río, pero fueron emboscados al llegar y todavía trabajan para recuperarse de ese ataque."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "52.06S"; 
          ["LONG"] = "51.28W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Claro de los Orcos Muertos"; 
      ["PROGRESS"] = "Descubre el Claro de los Orcos Muertos"; 
      ["LORE"] = "Más de una docena de Orcos yacen muertos en un claro no muy lejos de Amon Hen. ¿Qué ocurrió aquí?"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "56.64S"; 
          ["LONG"] = "49.78W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Parth Galen"; 
      ["PROGRESS"] = "Descubre Parth Galen"; 
      ["LORE"] = "La pradera de Parth Galen sería un buen lugar para acampar para cualquier viajero obligado a desembarcar del río, pero está completamente a la vista de la orilla lejana y podría ser peligroso."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "58.59S"; 
          ["LONG"] = "47.94W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "El Tindrock"; 
      ["PROGRESS"] = "Descubre el Tindrock"; 
      ["LORE"] = "El Tindrock es un gran espolón de roca que divide las aguas del Anduin mientras se precipitan hacia las Cataratas de Rauros. Llamado Tol Brandir por los Elfos, se dice que es imposible de escalar."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "59.20S"; 
          ["LONG"] = "46.02W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Cataratas de Rauros"; 
      ["PROGRESS"] = "Descubre las Cataratas de Rauros"; 
      ["LORE"] = "Las grandes Cataratas de Rauros descienden desde los acantilados con un rugido atronador. Seguir el río por el borde significa la muerte."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "61.42S"; 
          ["LONG"] = "45.63W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Amon Hen"; 
      ["PROGRESS"] = "Descubre Amon Hen"; 
      ["LORE"] = "Amon Hen es una de las dos colinas que se elevan a ambos lados del Anduin en las Cataratas de Rauros. Los antiguos reyes se sentaban en el Trono de la Vista en su cima y veían muchas cosas útiles para ellos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "60.61S"; 
          ["LONG"] = "47.59W"; 
        }; 
      }; 
      };
