      [6] = {
      ["NAME"] = "Tumba de Dagred"; 
      ["PROGRESS"] = "Descubre la Tumba de Dagred"; 
      ["LORE"] = "Has encontrado la tumba del padre de Fastred, el anterior Reeve de las Campiñas del Sur. Fastred suele visitar el lugar para rendirle homenaje y cazar sin piedad a cualquier orco que se atreva a acercarse demasiado al lugar de descanso de su padre."; 
      ["POINTS"] = {
