      [4] = {
      ["NAME"] = "La Casa Negra"; 
      ["PROGRESS"] = "Encuentra la placa de la Casa Negra"; 
      ["LORE"] = "También conocida como Bâr Vorn, esta biblioteca fue nombrada así por la piedra oscura con la que está construida y por la tinta utilizada en su interior. Es la principal Sala de Redacción de Minas Tirith, donde los escribas escriben, copian y traducen textos antiguos y modernos. Forma parte de las Casas del Saber, y su torre alberga al Guardián de la escuela."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "22.35S"; 
          ["LONG"] = "37.87W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Casas del Saber"; 
      ["PROGRESS"] = "Encuentra la placa de las Casas del Saber"; 
      ["LORE"] = "También conocida como Bair Istoth, este conjunto de salas y torres acoge a los sabios, que se reúnen aquí para enseñar, aprender, debatir y pensar. Los hijos e hijas menores de la nobleza son enviados a menudo aquí para convertirse en sabios; los maestros de las Casas también trabajan en toda la ciudad, enseñando a leer y escribir a niños ricos y pobres por igual, así como números, historia y otros conocimientos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "22.28S"; 
          ["LONG"] = "37.92W"; 
        }; 
      }; 
      };
  };
