  -- La Meseta de Gorgoroth / El Abismo de Mordath -- Explorador / Exploradora de los Fosos Negros
  [1879360892] = {
      [1] = {
      ["NAME"] = "Lithannon"; 
      ["PROGRESS"] = "Descubre el Lithannon"; 
      ["LORE"] = "Has descubierto Lithannon, la Puerta de Ceniza de Mordath. Antaño entrada principal de Mordath, ha sido sellada tras la derrota de Sauron."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "9.35S"; 
          ["LONG"] = "123.77W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Durshnúl, el Puente Negro"; 
      ["PROGRESS"] = "Descubre Durshnúl, el Puente Negro"; 
      ["LORE"] = "Aunque ha sido destruido, Durshnúl, el Puente Negro, una vez se extendió sobre el Abismo de Mordath y era una gran vía para tanto los condenados de los fosos Negros como para las criaturas cautivas del Señor Oscuro."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "12.52S"; 
          ["LONG"] = "123.76W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "El Foso Oscuro"; 
      ["PROGRESS"] = "Descubre las Fosas Negras"; 
      ["LORE"] = "El Mordath, los Fosos Negros de Mordor, es un lugar desprovisto de esperanza. Es la base de Barad-dûr, una mina que no deja de profundizarse y un lugar de castigo para aquellos que han fallado al Señor Oscuro. Quienes son arrojados a los Fosos Negros nunca volverán a contemplar la luz de la Tierra Media."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "12.41S"; 
          ["LONG"] = "123.80W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Thol Shíkug, el Abismo Gritante"; 
      ["PROGRESS"] = "Descubre Thol Shíkug, el Abismo Gritante"; 
      ["LORE"] = "Thol Shíkug es una fortaleza de terror y muerte construida sobre los cimientos mismos de Barad-dûr. Para aquellos condenados a las Fosas Negras, se la conoce como el Abismo Gritante, ya que muchos orcos, hombres y bestias han encontrado su fin a manos del Señor Oscuro y sus más poderosos sirvientes en su interior. Nadie ha regresado jamás para contar lo que se oculta dentro de esta sombría estructura."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "12.80S"; 
          ["LONG"] = "122.64W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Murpraush, la Sala de la Corrupción"; 
      ["PROGRESS"] = "Descubre Murpraush, la Sala de la Corrupción"; 
      ["LORE"] = "Murpraush, la Sala de la Corrupción, es donde Sauron llevó a cabo los más viles de sus sortilegios. Allí buscó igualar los horrores del primer Señor Oscuro, Morgoth, y dar vida a nuevas y terribles criaturas de su propia imaginación."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "12.62S"; 
          ["LONG"] = "122.73W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Glúrghash, la Fosa de Fuego"; 
      ["PROGRESS"] = "Descubre Glúrghash, la Fosa de Llamas"; 
      ["LORE"] = "Glúrghash, la Fosa de Fuego, fue una vez la prisión de Thostír el Repugnante, un gran dragonzuelo de fuego del Este. Después de devorar uno de los Siete Anillos, fue capturado por agentes de Mordor y encarcelado bajo Barad-dûr. Sin embargo, cuando Mordath se rompió en pedazos, voló desde sus profundidades sombrías y escapó de la Tierra de las Sombras."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "13.96S"; 
          ["LONG"] = "123.64W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Glúrakul, la Fosa de Escarcha"; 
      ["PROGRESS"] = "Descubre Glúrakul, la Fosa de Escarcha"; 
      ["LORE"] = "Glúrakul, La fosa de Escarcha, En su día fue el hogar de Hrímil Corazón-de-Hielo, un dragón del frío de las Montañas Grises. Después de que Hrímil llegara a las salas de los enanos en el Este y devorara uno de los Siete Anillos, fue capturada y encarcelada bajo la Torre Oscura. Sin embargo, cuando Barad-dûr cayó y el Mordath quedó destrozado, salió volando de su prisión y escapó de Mordor."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "14.30S"; 
          ["LONG"] = "123.77W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Glurnákh, la Fosa de la Avaricia"; 
      ["PROGRESS"] = "Descubre Glurnákh, El foso de la Avaricia"; 
      ["LORE"] = "Glurnákh, La Fosa de la Avaricia, ha sido durante mucho tiempo el hogar de Fingar el Avaro, un antiguo Gusano de Angband. Después de devorar dos de los Siete Anillos, Fingar fue capturado y encarcelado bajo la Torre Oscura para sufrir eternamente."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "14.13S"; 
          ["LONG"] = "125.82W"; 
        }; 
      }; 
      };
  };
