  -- Valles de Anduin / Una crónica de la Compañía
  [1879387421] = {
      [1] = {
      ["NAME"] = "Ya había salido, con el abrigo rasgado, bajando corriendo las escaleras, mientras unos trasgos desconcertados seguían recogiendo sus botones en la puerta."; 
      ["PROGRESS"] = "Donde Bilbo perdió sus botones"; 
      ["LORE"] = "Ya había salido, con el abrigo rasgado, bajando corriendo las escaleras, mientras unos trasgos desconcertados seguían recogiendo sus botones en la puerta."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "12.10N"; 
          ["LONG"] = "63.37W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "¡Cómo saltaron! Gandalf estaba asombrado, mientras todos gritaban de sorpresa y alegría."; 
      ["PROGRESS"] = "Donde Bilbo se reúne con la Compañía"; 
      ["LORE"] = "¡Cómo saltaron! Gandalf estaba asombrado, mientras todos gritaban de sorpresa y alegría."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "10.91N"; 
          ["LONG"] = "61.23W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Habrías reído si hubieras visto a los enanos, encaramados en los árboles con sus barbas colgando, como viejos caballeros."; 
      ["PROGRESS"] = "Donde la Compañía se encontró con los huargos"; 
      ["LORE"] = "Habrías reído si hubieras visto a los enanos, encaramados en los árboles con sus barbas colgando, como viejos caballeros."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "11.04N"; 
          ["LONG"] = "59.75W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Gandalf había ayudado amablemente a las águilas y curado a su señor de una herida de flecha."; 
      ["PROGRESS"] = "Donde las Águilas llevaron a la Compañía a un lugar seguro"; 
      ["LORE"] = "Gandalf había ayudado amablemente a las águilas y curado a su señor de una herida de flecha."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "14.71N"; 
          ["LONG"] = "61.04W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "'¡Adiós! ¡Dondequiera que vayas, hasta que tu nido te acoja al final de tu viaje!"; 
      ["PROGRESS"] = "Donde las Águilas depositaron a la Compañía"; 
      ["LORE"] = "'¡Adiós! ¡Dondequiera que vayas, hasta que tu nido te acoja al final de tu viaje!"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "13.05N"; 
          ["LONG"] = "58.46W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "'Esta no es mi aventura. Tal vez vuelva a verlos antes de que termine, pero por el momento tengo asuntos que atender.'"; 
      ["PROGRESS"] = "Donde la Compañía se reúne en la Carroca"; 
      ["LORE"] = "'Esta no es mi aventura. Tal vez vuelva a verlos antes de que termine, pero por el momento tengo asuntos que atender.'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "13.48N"; 
          ["LONG"] = "57.85W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Eran más grandes que un pulgar, mucho más grandes, y las bandas amarillas de sus cuerpos negros brillaban como un oro radiante."; 
      ["PROGRESS"] = "Donde la Compañía atravesó los campos de abejas de Beorn"; 
      ["LORE"] = "Eran más grandes que un pulgar, mucho más grandes, y las bandas amarillas de sus cuerpos negros brillaban como un oro radiante."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "13.10N"; 
          ["LONG"] = "54.47W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "'¡Aquí están! No parecen peligrosos.' Beorn soltó una gran carcajada antes de dejar su hacha."; 
      ["PROGRESS"] = "Donde la Compañía se topó con la casa de Beorn"; 
      ["LORE"] = "'¡Aquí están! No parecen peligrosos.' Beorn soltó una gran carcajada antes de dejar su hacha."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "13.86N"; 
          ["LONG"] = "53.32W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "'¡Una historia excelente!' dijo Beorn. 'La mejor que he escuchado en mucho tiempo. ¡Comamos algo!'"; 
      ["PROGRESS"] = "Donde Beorn encontró a la Compañía"; 
      ["LORE"] = "'¡Una historia excelente!' dijo Beorn. 'La mejor que he escuchado en mucho tiempo. ¡Comamos algo!'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "13.40N"; 
          ["LONG"] = "53.31W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Las barbas de los enanos temblaban mientras escuchaban, pues sabían que pronto tendrían que aventurarse en el Bosque Negro."; 
      ["PROGRESS"] = "Donde la Compañía cenó con Beorn"; 
      ["LORE"] = "Las barbas de los enanos temblaban mientras escuchaban, pues sabían que pronto tendrían que aventurarse en el Bosque Negro."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "38.80N"; 
          ["LONG"] = "53.16E"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "'Espero que te guste. Ahora debes devolver los poneys que has pedido prestados a Beorn.'"; 
      ["PROGRESS"] = "Donde la Compañía entró en el Bosque Negro"; 
      ["LORE"] = "'Espero que te guste. Ahora debes devolver los poneys que has pedido prestados a Beorn.'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "15.71N"; 
          ["LONG"] = "51.18W"; 
        }; 
      }; 
      };
      [12] = {
      ["NAME"] = "Allí, a lo lejos, se encontraba la Montaña Solitaria en el borde del horizonte. La nieve permanecía en su pico más alto, sin derretirse y reluciente."; 
      ["PROGRESS"] = "Donde Bilbo volvió a casa"; 
      ["LORE"] = "Allí, a lo lejos, se encontraba la Montaña Solitaria en el borde del horizonte. La nieve permanecía en su pico más alto, sin derretirse y reluciente."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "9.78N"; 
          ["LONG"] = "64.98W"; 
