  -- Valles de Anduin / Enemigos de los Valles
  [1879387432] = {
      [1] = {
      ["NAME"] = "Ylgraf"; 
      ["PROGRESS"] = "Explora Ylgraf"; 
      ["LORE"] = "Los huargos han merodeado por las tierras de los Beórnidas a lo largo de los años, pero los que habitan en Ylgraf hoy son más grandes y feroces que otros de su especie. Estos huargos provienen de Gundabad y se esconden entre las rocas al norte del Beorninghús, esperando atacar a Grimbeorn y a sus parientes."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "16.76N"; 
          ["LONG"] = "53.60W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Puerta de los Trasgos"; 
      ["PROGRESS"] = "Explora la Puerta de los trasgos"; 
      ["LORE"] = "Los Beórnidas mantienen un ojo en la Puerta de los trasgos, ya que este lado de las montañas es la principal entrada y salida de la Ciudad de los Trasgos. Durante los últimos días de la Guerra del Anillo, orcos y trasgos se precipitaron por la Puerta de los trasgos hacia los Valles del Anduin, saqueando y quemando los pacíficos pueblos de los Hombres del bosque. Liderados por Grimbeorn el Viejo, los Beórnidas y los Hombres del bosque se enfrentaron a los trasgos y finalmente los rechazaron.\n\nAhora la Ciudad de los Trasgos está tranquila y hay poca actividad en la Puerta de los trasgos, pero los Beórnidas no lo han olvidado. La vigilan todavía."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "11.62N"; 
          ["LONG"] = "62.78W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Waldfast"; 
      ["PROGRESS"] = "Explora Waldfast"; 
      ["LORE"] = "El pacífico pueblo de los Hombres del bosque de Waldfast ha sido destruido por un ejército de trasgos. Centinelas están apostados por todo el pueblo, pero son demasiado pocos para explicar la magnitud de la destrucción. Una cueva detrás del pueblo podría contener respuestas."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "6.35N"; 
          ["LONG"] = "60.23W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Fil Sulmog"; 
      ["PROGRESS"] = "Explora Fil Sulmog"; 
      ["LORE"] = "Tras las últimas batallas de la Guerra del Anillo, un grupo de orcos ha establecido un campamento precario en las colinas del Borde del Bosque. Se trata de los Shapag-hai, que han descubierto que prefieren atacar a comerciantes y viajeros antes que a guerreros y soldados. Desde su campamento de Fil Sulmog practican el arte del pillaje, y se han vuelto bastante buenos en ello."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "25.59S"; 
          ["LONG"] = "4.98W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Tríubad"; 
      ["PROGRESS"] = "Explora Tríubad"; 
      ["LORE"] = "El campamento de leñadores de Tríubad proporcionó madera y otros suministros necesarios con los que los Hombres del bosque construyeron sus casas y los muros de sus aldeas, pero entonces llegaron los Taurogrims. Los Hombres del bosque los llaman 'Thyrsir', demonios del bosque, y temen su toque maldito.\n\nLos Hombres del bosque saben que Tríubad puede estar perdido, pero no pasan el tiempo lamentándose. En cambio, buscan aventureros para detener a los Thyrsir y evitar que propaguen la plaga a otras aldeas en el Borde del bosque."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "4.04N"; 
          ["LONG"] = "54.48W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Côs Braen"; 
      ["PROGRESS"] = "Explora Côs Braen"; 
      ["LORE"] = "Côs Braen se encuentra en el borde sur de Laerlad, hogar de los Ungoledain y sus venenosos parientes. Odian a Grimbeorn y a su gente con una pasión enfermiza, y acabarían con los Beórnidas y los Gauredain por igual si tuvieran la oportunidad."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "2.59S"; 
          ["LONG"] = "53.48W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Marisma de Zarquino"; 
      ["PROGRESS"] = "Explora el Pantano de Zarquino"; 
      ["LORE"] = "Las máquinas de dragado se encuentran en el barro de los Campos Gladios, una vez manejadas por orcos y semi-orcos, pero ahora abandonadas. Se excavó un gran agujero en el pantano de Zarquino, y se rumorea que se encontró algún tesoro en sus profundidades. Los semi-orcos permanecen allí, buscando más tesoros para ellos mismos y no para su maestro. Él permanece en silencio, con la mente en otro lugar, y sus sirvientes en el pantano no han recibido ningún mensaje de él desde hace algún tiempo."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "0.71N"; 
          ["LONG"] = "59.29W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Lúlstrok"; 
      ["PROGRESS"] = "Explora Lúlstrok"; 
      ["LORE"] = "Los orcos buscaron en el pantano durante muchas semanas, operando desde su campamento de Lúlstrok en la parte noroeste de los Campos Gladios. Una de las grandes máquinas de dragado se encuentra allí ahora, silenciosa e inmóvil, pero una vez removió la tierra tanto de día como de noche. Armas, piezas de armadura y otros objetos fueron llevados a Lúlstrok, pero se desconoce dónde han ido a parar estos tesoros desde entonces."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "2.30N"; 
          ["LONG"] = "61.93W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Las guaridas de Tûn Melen"; 
      ["PROGRESS"] = "Explora los túneles de Tûn Melen"; 
      ["LORE"] = "¿Qué se esconde en los túneles de Tûn Melen? Solo aventurándose en su interior se puede saber con certeza, pero los soldados que sirven a la Mano Blanca podrían haberlo hecho ya, buscando tesoros si no información."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.63N"; 
          ["LONG"] = "4.47W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Shathur-munzu"; 
      ["PROGRESS"] = "Explora Shathur-munzu"; 
      ["LORE"] = "Una niebla húmeda empapa las piedras que conducen a Shathur-munzu, el puesto más al sur de la perdida Khazad-dûm. La fortaleza está rota ahora, y los enanos no han vivido allí durante muchos años. Shathur-munzu fue el sitio de una de las batallas más sangrientas en la Guerra de Enanos y Orcos, y el Rey Thráin no la sostuvo por mucho tiempo."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "39.77S"; 
          ["LONG"] = "2.40E"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "Brafulug"; 
      ["PROGRESS"] = "Explora Brafulug"; 
      ["LORE"] = "Ugúrz estableció su campamento de Brafulug para atacar a los comerciantes en el camino, creyendo que sus Orcos estarían lo suficientemente lejos de Lothlórien como para escapar de la atención de los Elfos. Esto resultaría ser un error de cálculo."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "3.44S"; 
          ["LONG"] = "60.98W"; 
        }; 
      }; 
      };
  };
