  -- Valles de Anduin / Protector / Protectora de los Valles
  [1879387438] = {
      [1] = {
      ["NAME"] = "Beorninghús"; 
      ["PROGRESS"] = "Explora el Beorninghús"; 
      ["LORE"] = "Hogar de Grimbeorn el Viejo y otros miembros de su familia, el Beorninghús suele estar cerrado a los forasteros. Durante las últimas semanas de la Guerra del Anillo, los Beórnidas consideraron necesario asumir un papel más activo en la protección de los Valles del Anduin.\n\nEl canto de los pájaros y el zumbido de los abejorros dan la bienvenida a todos los que se acercan al Beorninghús, pero si no piden permiso a Grimbeorn, esos no serán los únicos sonidos que escucharán; la ira de Grimbeorn será tanto ruidosa como rápida."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "13.60N"; 
          ["LONG"] = "53.32W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Vegbár"; 
      ["PROGRESS"] = "Explora Vegbar"; 
      ["LORE"] = "El puesto de avanzada de Vegbar permite a los Beórnidas vigilar la carretera entre el Paso Alto y el Viejo Vado, y cobrar su peaje a los viajeros y comerciantes que pasan por allí. Skalla comanda en Vegbar, y a pesar de su exterior brusco se preocupa profundamente por sus vecinos y se preocupa por su seguridad."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "7.90N"; 
          ["LONG"] = "58.39W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Residencia de Ainhard"; 
      ["PROGRESS"] = "Explora la residencia de Ainhard"; 
      ["LORE"] = "El leñador Ainhard mantiene una residencia en las guaridas de los lobos, y sus compañeros más cercanos son sus tres perros. Vive con miedo de los Orcos, trasgos y taurogrim, ya que no es un guerrero. Depende del cercano puesto de avanzada beórnida de Vegbar para su protección."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "4.70N"; 
          ["LONG"] = "59.46W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Residencia de Hodver"; 
      ["PROGRESS"] = "Explora la residencia de Hodver"; 
      ["LORE"] = "Hodver mantiene una residencia en las guaridas de los lobos, pero siempre está listo para dirigirse al puesto de avanzada beórnida de Vegbar al primer signo de Orcos o de huargos. 'No soy un cobarde,' dice, 'pero tampoco soy un tonto.'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "6.65N"; 
          ["LONG"] = "58.13W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Residencia de Gudule"; 
      ["PROGRESS"] = "Explora la residencia de Gudule"; 
      ["LORE"] = "Gudule mantiene una residencia en las guaridas de los lobos. 'Esta tierra nunca ha sido segura,' dice ella. 'Vivimos demasiado cerca de las montañas para dormir muy profundamente por la noche. Pero este es nuestro hogar.'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "5.04N"; 
          ["LONG"] = "58.87W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Hultvís"; 
      ["PROGRESS"] = "Explora Hultvís"; 
      ["LORE"] = "El pueblo de Hultvís, habitado por los Hombres del Bosque, fue atacado durante las últimas semanas de la Guerra del Anillo, pero los Orcos y los huargos fueron repelidos y finalmente derrotados por una fuerza unida de Beórnidas y Hombres del Bosque en la Batalla del Viejo Vado. Ahora el pueblo busca reconstruirse y reforzarse, y busca aventureros dispuestos a ayudar con el esfuerzo de recuperación.\n\nLos Hombres del Bosque son un pueblo supersticioso, y en Hultvís seguramente escucharás muchas leyendas e historias. Estas conciernen a la hermosa y desdichada Doncella del Gladio, al espectral Vagári el Errante, al viejo loco Ubb, enloquecido por el hambre, y a los desaparecidos Hól-budlan."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "5.02N"; 
          ["LONG"] = "54.48W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Blómgard"; 
      ["PROGRESS"] = "Explora Blómgard"; 
      ["LORE"] = "El pueblo de Blómgard se encuentra en Laerlad, no muy lejos de los pantanos de los Campos Gladios. Los Hombres del Bosque que viven allí hablan en susurros de una oscuridad sobrenatural y de un sonido que se arrastra por los tejados de sus casas. La líder de Blómgard, Odahild, tiene fama de ser honesta y no es de las que mienten, pero otros habitantes del Valle del Anduin se preguntan si las historias de Blómgard son ciertas. Un aventurero podría llegar al fondo del asunto."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "1.78S"; 
          ["LONG"] = "55.23W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Puesto de vigilancia beórnida"; 
      ["PROGRESS"] = "Explora el puesto de vigilancia beórnida"; 
      ["LORE"] = "Este puesto de vigilancia beórnida protege la carretera que conduce al Valle del Crepúsculo. Los Elfos también vigilan la carretera del sur, pero ninguno confía en el otro para hacerlo solo."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "3.48S"; 
          ["LONG"] = "59.92W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Arhaim"; 
      ["PROGRESS"] = "Explora Arhaim"; 
      ["LORE"] = "Ubicado no muy lejos de la fortaleza enana perdida de Shathur-munzu, el pueblo de Arhaim está ocupado tanto por Hombres del Bosque como por Beórnidas. Juntos mantienen el comercio con los Elfos y llevan una vida sencilla en el Valle del Crepúsculo."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "5.88S"; 
          ["LONG"] = "60.94W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Glándir"; 
      ["PROGRESS"] = "Explora Glándir"; 
      ["LORE"] = "En Glándir, los Elfos vigilan la carretera que conduce a Lothlórien, manteniendo la seguridad del Bosque de Oro. Se sabe que la Dama Galadriel y el Señor Celeborn han visitado a los Elfos aquí en ocasiones, buscando informes de los Valles del Anduin y trayendo comida y alegría para aliviar la carga de aquellos Elfos que permanecen fuera de los límites de Lórien."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "7.85S"; 
          ["LONG"] = "61.72W"; 
        }; 
      }; 
      };
