  -- Valles de Anduin / Sitios de los Valles
  [1879387878] = {
      [1] = {
      ["NAME"] = "El Nido de las Águilas"; 
      ["PROGRESS"] = "Explora el Nido de las Águilas"; 
      ["LORE"] = "Los Nidos de las Grandes Águilas solo se pueden alcanzar volando. Es el hogar de Gwaihir el Señor del Viento y su gente, quizás los habitantes más antiguos de los Valles del Anduin. Han viajado lejos desde este alto nido, y su llegada siempre ha señalado un cambio en el curso del destino: durante las aventuras de Bilbo con Thorin y la Compañía, cuando Gandalf el Gris fue encarcelado por Saruman el Blanco y durante las últimas horas de la Guerra del Anillo.\n\nSi llegas al Nido, siempre es beneficioso ser lo más educado posible con tus anfitriones. No todas las Grandes Águilas son amigables con los forasteros o con los que no tienen alas."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "14.83N"; 
          ["LONG"] = "61.05W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Paso Alto"; 
      ["PROGRESS"] = "Explora el Paso Alto"; 
      ["LORE"] = "El Paso Alto a través de las Montañas Nubladas fue traicionero y difícil de cruzar durante muchos años, ya que tanto los saqueadores trasgos como los gigantes de piedra acechaban entre las piedras y los riscos, dificultando el viaje. Cuando llegaron los Beórnidas, despejaron el Paso Alto e hicieron un esfuerzo por alejar estos peligros. A cambio, cobraron un peaje por el paso, que otros pueblos consideraron un costo injusto.\n\nEl Paso Alto estuvo bloqueado durante la Guerra del Anillo, pero hoy los Beórnidas lo han despejado una vez más. Algunos dicen que los gigantes de piedra amistosos ayudaron en este esfuerzo, pero el pueblo de Grimbeorn no dirá si esto es así."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "10.17N"; 
          ["LONG"] = "65.61W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Hadhodiant"; 
      ["PROGRESS"] = "Explora Hadhodiant"; 
      ["LORE"] = "Hadhodiant era un poderoso puente de los Enanos que servía como el principal medio para cruzar el Anduin en el norte, pero se rompió poco después de la caída de Shathur-munzu en la Segunda Edad. Fue reconstruido, y de hecho, cuando la Gran Alianza marchó hacia el sur para sitiar Mordor, fue a través del Hadhodiant que cruzaron el Anduin.\n\nPero el puente no duraría. Se rompió por la mitad, y cuando se convocó a artesanos de las Colinas de Hierro para repararlo, fueron atacados por Orcos y todos los enanos fueron asesinados. A lo largo de los siglos, las piedras del puente continuaron cayendo al río, hasta que finalmente una tremenda inundación arrasó gran parte de las ruinas.\n\nCon la destrucción del Hadhodiant, el Viejo Vado ha vuelto a estar en servicio como el principal medio para cruzar el Anduin en el norte."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "8.60N"; 
          ["LONG"] = "56.59W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Avabárg"; 
      ["PROGRESS"] = "Explora Avabárg"; 
      ["LORE"] = "El viejo bastión de Avabárg se encuentra en un pequeño islote del río. En su día fue el hogar de los Pueblos de los Caballos, que más tarde serían conocidos como los Éothéod. Hoy, Avabárg permanece vacío, salvo por la penumbra que se ha apoderado de la isla y algún que otro orco o trasgo que intenta fortificarla y hacerla suya.\n\nLos Hombres del Bosque han intentado recuperarla a lo largo de los años, pero cada intento ha terminado en fracaso, y ahora la tratan con miedo supersticioso."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "5.01N"; 
          ["LONG"] = "57.14W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Rhosgobel"; 
      ["PROGRESS"] = "Explora Rhosgobel"; 
      ["LORE"] = "El pueblo de Rhosgobel, que fue en su día el asentamiento más septentrional de los Elfos del Bosque y más tarde el más meridional, es ahora hogar únicamente de Radagast el Pardo, uno de los cinco Magos. Durante un tiempo eligió una vida nómada y residió en Ost Guruth, la Fortaleza en ruinas de las Tierras Solitarias, pero ahora ha regresado al Borde del Bosque y busca combatir la oscuridad que se avecina."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "0.61N"; 
          ["LONG"] = "52.81W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Cascadas Gladias"; 
      ["PROGRESS"] = "Explora las Cascadas Gladias"; 
      ["LORE"] = "El curso del río Gladio no siempre fue como lo es hoy. Durante la lucha al final de la Segunda Edad, Sauron envió su pensamiento oscuro, intentando despertar grandes males a su causa. Se desconoce si tales calamidades respondieron a él, pero alrededor de este tiempo hubo enormes terremotos en las Montañas Nubladas, sacudiendo los salones de los enanos hasta el Paso Alto.\n\nEl levantamiento cambió el curso del río, llevando sedimentos río abajo y obstruyendo el Lago Gladio hasta que sus orillas se desbordaron. El agua se vertió sobre el acantilado, inundando el valle y sumergiendo sus caminos. De esta manera, los Campos Gladios se convirtieron en un amplio pantano de juncos y oscuros estanques. Con el tiempo, se restauró el nivel del lago, y las Cascadas Gladias se convirtieron en el estrecho torrente que es hoy."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "0.92N"; 
          ["LONG"] = "63.58W"; 
        }; 
      }; 
      };
  };
