  -- Imlad Morgul / Explorando el Mordor asediado
  [1879395348] = {
      [1] = {
      ["NAME"] = "Ram Raedas"; 
      ["PROGRESS"] = "Aprende sobre Ram Raedas"; 
      ["LORE"] = "'Era Ram Raedas, el Muro Enredador. Construimos esa fortificación a través de la Garganta de Hierro para evitar que los enemigos cruzaran desde Udûn y atacaran a la Gran Alianza por la retaguardia.' - Isildur"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "96.53S"; 
          ["LONG"] = "131.74W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Díngarth"; 
      ["PROGRESS"] = "Aprende sobre Díngarth"; 
      ["LORE"] = "'Díngarth era el lugar más seguro de los Pueblos Libres, construido al comienzo del asedio y repetidamente atacado y reconstruido durante los años siguientes. Hacia el final estaba casi vacío, mantenido como último reducto en caso de que las fuerzas avanzadas de la Alianza fueran abrumadas y obligadas a retirarse. A mis hijos les encantaba hacerle la vida imposible a Ontamo, el maestro de las fortificaciones de Díngarth, a pesar de mis reprimendas por ello.' - Isildur"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "97.30S"; 
          ["LONG"] = "131.51W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Echad-in-Edhil"; 
      ["PROGRESS"] = "Aprende sobre Echad-in-Edhil"; 
      ["LORE"] = "'Echad-in-Edhil era el campamento avanzado de los Elfos, y fue donde Gil-galad y su familia residieron durante gran parte del asedio. Desde este campamento, los Altos Elfos de la Compañía Brillante emprendieron muchas incursiones peligrosas en las llanuras frente a Barad-dûr y contra los sirvientes de Sauron.' - Isildur"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "96.23S"; 
          ["LONG"] = "127.69W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Adambel"; 
      ["PROGRESS"] = "Aprende sobre Adambel"; 
      ["LORE"] = "'Adambel era el campamento avanzado de los Hombres, desde donde mi padre Elendil, mi hermano Anárion y yo comandábamos nuestros ejércitos. Era el lugar más cercano a Barad-dûr donde considerábamos prudente acampar.' - Isildur"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "98.76S"; 
          ["LONG"] = "126.04W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Amon Fuin"; 
      ["PROGRESS"] = "Aprende sobre Amon Fuin"; 
      ["LORE"] = "'Era Amon Fuin, la Colina de la Oscuridad, la última gran fortificación que mantenían las fuerzas de Sauron más allá de la propia Torre Oscura. Los Mordorrim realizaban sacrificios y otros rituales detrás de los muros de esa fortaleza, y muchos fueron los soldados de la Gran Alianza que perdimos a causa de sus mortales incursiones.' - Isildur"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "98.91S"; 
          ["LONG"] = "122.01W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Dol Naeg"; 
      ["PROGRESS"] = "Aprende sobre Dol Naeg"; 
      ["LORE"] = "'Dol Naeg era el nombre de un espolón rocoso en la ladera norte de Amon Amarth. Es un lugar de gran tristeza para mí, porque allí murió mi padre. También es donde obtuve un artefacto de Sauron que me trajo solo dolor y sufrimiento. ¡Ojalá nunca hubiera estado allí!' - Isildur"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "97.17S"; 
          ["LONG"] = "118.47W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Halroth"; 
      ["PROGRESS"] = "Aprende sobre Halroth"; 
      ["LORE"] = "'Conozco el túnel de Halroth, pero nunca me aventuré dentro. Glorfindel de la Compañía Brillante conoce ese lugar. Que él hable de ello, si quiere.' - Isildur"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "92.72S"; 
          ["LONG"] = "116.68W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Barad-dûr"; 
      ["PROGRESS"] = "Aprende sobre Barad-dûr"; 
      ["LORE"] = "'Barad-dûr, la torre de Sauron, no fue construida por sus sirvientes, sino por manos númenóreanas. Él la ha doblado a su maldad, y se mantuvo como una cruel burla para mi pueblo. Permaneció dentro durante los largos años del asedio, contento de superarnos, pero no fue así.' - Isildur"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "96.76S"; 
          ["LONG"] = "114.39W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Baur Kasak"; 
      ["PROGRESS"] = "Aprende sobre Baur Kasak"; 
      ["LORE"] = "'Los huargos de Baur Kasak eran temidos por todos los hombres bajo mi mando, pues estas bestias podían moverse a una velocidad increíble a través de las llanuras, atrapando a un soldado desprevenido con sus poderosas mandíbulas y cargando lejos en cuestión de momentos. Muchos de mis soldados insistían en ser acompañados en las llanuras por un Elfo de las fuerzas de Gil-galad, pues solo sus arcos veloces podían disuadir el avance de tales criaturas.' - Isildur"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "100.98S"; 
          ["LONG"] = "130.85W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Mokh Shapat"; 
      ["PROGRESS"] = "Aprende sobre Mokh Shapat"; 
      ["LORE"] = "'Me entristece escuchar que los Orcos siguen presentes en este mundo. Eran un enemigo temible cuando luchamos contra Sauron, crueles y mortales, sin una pizca de misericordia. Muchos de mis amigos y soldados perecieron en sus campamentos. El que se llamaba Mokh Shapat permaneció durante años, a pesar de nuestros intentos de erradicarlo.' - Isildur"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "101.69S"; 
          ["LONG"] = "129.49W"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "Mokh Darga"; 
      ["PROGRESS"] = "Aprende sobre Mokh Darga"; 
      ["LORE"] = "'Mokh Darga era un gran campamento desde el cual los Orcos lanzaban numerosos ataques contra Adambel. Mi padre en persona repelió varios de estos asaltos, lo que dio coraje no solo a sus soldados, sino también a mi hermano y a mí. ¡Ay de Anárion!'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "95.48S"; 
          ["LONG"] = "123.92W"; 
        }; 
      }; 
      };
      [12] = {
      ["NAME"] = "Barthost"; 
      ["PROGRESS"] = "Aprende sobre Barthost"; 
      ["LORE"] = "'¿Barthost, dices? No recuerdo ese nombre. Tal vez el hechizo de Gultháva aún no me ha liberado de su control.' - Isildur"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "95.21S"; 
          ["LONG"] = "119.93W"; 
        }; 
      }; 
      };
      [13] = {
      ["NAME"] = "Urshúlagar"; 
      ["PROGRESS"] = "Aprende sobre Urshúlagar"; 
      ["LORE"] = "'Era un campamento de hombres malvados, juramentados a servir a Sauron. Nunca puse un pie dentro, pero sé que las fuerzas de Sauron se incubaban en su malicia dentro de sus límites, y salían con odio en sus corazones, con la intención de derrotar a la Gran Alianza.' - Isildur"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "94.14S"; 
          ["LONG"] = "118.84W"; 
        }; 
      }; 
      };
      [14] = {
      ["NAME"] = "Matum Graz"; 
      ["PROGRESS"] = "Aprende sobre Matum Graz"; 
      ["LORE"] = "'Las sombras y espíritus de Matum Graz permanecieron junto a los muertos que caminan, y alimentaron el odio hacia los vivos en sus corazones malvados. No deseo hablar de ellos ahora.' - Isildur"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "95.54S"; 
          ["LONG"] = "115.99W"; 
        }; 
      }; 
      };
      [15] = {
      ["NAME"] = "Angathrai"; 
      ["PROGRESS"] = "Aprende sobre Angathrai"; 
      ["LORE"] = "'Sombras se arremolinaron en Angathrai, movidas por los oscuros designios de Sauron y de los adeptos mordorrim. Mejor no hablar de ello.' - Isildur"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "95.63S"; 
          ["LONG"] = "114.24W"; 
        }; 
      }; 
      };
  };
