  -- Imlad Morgul / Explorando Minas Morgul
  [1879395353] = {
      [1] = {
      ["NAME"] = "Barad Angarth, la fortaleza de los guardianes de la puerta"; 
      ["PROGRESS"] = "Explora Barad Angarth, la fortaleza de los guardianes de la puerta"; 
      ["LORE"] = "Barad Angarth ha sido recuperada de los Orcos, y ahora sirve a la Compañía Blanca como base en la ciudad. Otras torres de este tipo podrían servir mejor a la recuperación, pero primero deberán ser tomadas de los enemigos que las poseen."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "24.97S"; 
          ["LONG"] = "19.26E"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Barad Orhant, la Torre del Patio del Árbol"; 
      ["PROGRESS"] = "Explora Barad Orhant, la torre de los guardianes del árbol"; 
      ["LORE"] = "Barad Orhant una vez dominó el Círculo de la Habilidad en Minas Ithil, pero ahora la vista ha cambiado. Ese nivel es ahora el Círculo de Tristeza, y solo alberga a los Muertos. Lo mismo ocurrió con la Torre del Árbol, que fue tomada para el uso de la Compañía Blanca. Quizás ocurra lo mismo con el Círculo de Tristeza."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "26.45S"; 
          ["LONG"] = "19.16E"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Barad Elenath, la Torre de los Observadores de Estrellas"; 
      ["PROGRESS"] = "Explora Barad Elenath, la torre de los astrónomos"; 
      ["LORE"] = "Barad Elenath, la torre de los astrónomos, fue una vez un lugar de estudio y aprendizaje. Desde su gran altura, los eruditos de la ciudad pasaban noche tras noche estudiando la luna y las estrellas, pero eso fue hace mucho tiempo. Los merrevail de Lhaereth la Mancillada reclamaron esta torre, y solo recientemente han sido expulsados. La torre sirve ahora como base para la recuperación de Minas Morgul por parte de la Compañía Blanca."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "25.19S"; 
          ["LONG"] = "19.31E"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Barad Arthir, la alta fortaleza de vigilancia"; 
      ["PROGRESS"] = "Explora Barad Arthir, el alto fuerte de vigilancia"; 
      ["LORE"] = "El Círculo de la Alegría, sobre el que se erguía Barad Arthir, se ha convertido en el Círculo de Desesperación, un lugar de gran peligro para la Compañía Blanca, perseguida por los espíritus. El objetivo de la Compañía de recuperar la ciudad sigue siendo difícil, pero cada paso dado es una victoria, y la expulsión de los espíritus de Barad Arthir podría augurar más progresos en el futuro."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "26.60S"; 
          ["LONG"] = "19.56E"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Casa de los Cantos de Lindalírë"; 
      ["PROGRESS"] = "Explora la Casa de los cantos de Lindalírë"; 
      ["LORE"] = "Los poetas y los juglares acudían a Minas Ithil cuando Gondor estaba en su apogeo, y las lámparas de la Casa de los cantos de Lindalírë permanecían encendidas hasta altas horas de la noche. Pero la Noche resultó más oscura e insidiosa, y con la llegada del Rey Brujo el teatro es ahora un lugar solo para los Muertos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "67.11S"; 
          ["LONG"] = "3.14E"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Roz Dagalur, la Casa de los Demonios"; 
      ["PROGRESS"] = "Explora Roz Dagalur, la Casa de los Demonios"; 
      ["LORE"] = "Los Hombres demacrados entran en Roz Dagalur, pero pocos saben cómo encontrar el camino. Aún menos saben cómo salir."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "5.77S"; 
          ["LONG"] = "28.54E"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Búrzangh, la Forja Velada"; 
      ["PROGRESS"] = "Explora Búrzangh, la Forja Oculta"; 
      ["LORE"] = "Dicen que la forja sigue funcionando, pero las manos de los hombres no la tocan. En Búrzangh, un poder fantasmal toma el mando, buscando crear alguna reliquia de tiempos antiguos, pero ninguno de los vivos puede decir qué artefacto desean crear los espíritus."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "55.73N"; 
          ["LONG"] = "54.80E"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Dâr Grazadh, el Salón de la Putrefacción"; 
      ["PROGRESS"] = "Explora Dâr Grazadh, el Salón de la Putrefacción"; 
      ["LORE"] = "El olor a carne en descomposición llena el Salón de la Putrefacción, y los espectros acechan entre las salas que una vez fueron hogar de la luz y la vida. Pero esos días han pasado, y el rey Elessar no sabe si alguna vez podrán volver."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "57.81N"; 
          ["LONG"] = "54.80E"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Ghashan-kútot, los Salones del Saber Oscuro"; 
      ["PROGRESS"] = "Explora Ghashan-kútot, el Salón del Saber Oscuro"; 
      ["LORE"] = "Una fuerza sobrenatural recorre los polvorientos caminos que separan los estantes de Ghashan-kútot. Responde al nombre de Dolguzigir, pero pocos han visto al Sabio Maldito. Se dice que puede adoptar la forma que desee, pero no es un Hombre, y si aparece como tal es solo por capricho. Está ansioso por conocer la historia de cualquiera que se adentre en el Salón del Saber Oscuro, ansioso casi hasta el punto de la enfermedad, y no desea que nadie se vaya... sin ser recogido."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "68.01S"; 
          ["LONG"] = "0.71E"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Aguas Sombrías"; 
      ["PROGRESS"] = "Explora las Aguas sombrías"; 
      ["LORE"] = "Los baños de Minas Ithil fueron una vez un lugar para descansar y relajarse, y la gente que vivía allí se lavaba de la suciedad y la mugre de sus vidas diarias, sumergiéndose en aguas de satisfacción. Ahora los baños están vacíos de toda buena gente, perseguidos por sombras del mal."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "67.23S"; 
          ["LONG"] = "2.39E"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "El Patio de Angáth"; 
      ["PROGRESS"] = "Explora el Claustro de Angáth"; 
      ["LORE"] = "'¿Hay algo más triste que un jardín muerto y retorcido? Así era Ithilien, y ya trabajamos para restaurar la belleza de mi tierra. Quizás pueda ser lo mismo aquí.' - Príncipe Faramir"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "66.83S"; 
          ["LONG"] = "1.43E"; 
        }; 
      }; 
      };
      [12] = {
      ["NAME"] = "Bâr Maenath"; 
      ["PROGRESS"] = "Explora Bâr Maenath"; 
      ["LORE"] = "La mayoría de los tesoros de Minas Ithil ya han sido saqueados, ya sea por sus habitantes que huyeron de la ciudad antes de su caída o por fuerzas del mal en busca de artefactos y oro. Los pocos restos que quedan han sido corrompidos por la larga presencia de los Nazgûl y sus secuaces, y ahora Bâr Maenath solo ofrece mala fortuna a los pocos buscadores de tesoros que se atreven a explorar allí."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "12.29S"; 
          ["LONG"] = "28.71E"; 
        }; 
      }; 
      };
      [13] = {
