      };
      [14] = {
      ["NAME"] = "Salón de la Tortura"; 
      ["PROGRESS"] = "Explora el Salón de la tortura"; 
      ["LORE"] = "Una vez un lugar de banquetes y alegría, el Salón de la tortura no ha conocido una comida libre de terror durante innumerables años. Ahora es un antro de maldad, y solo horrores se sientan allí."; 
      ["POINTS"] = {
