  -- Imlad Morgul / Explorando Thuringwath
  [1879395363] = {
      [1] = {
      ["NAME"] = "Falch Gurth"; 
      ["PROGRESS"] = "Explora Falch Gurth"; 
      ["LORE"] = "Falch Gurth, la Grieta de la Muerte, era un camino secreto que conducía de regreso a las Ephel Dúath del sur. Fue excavado por los Nazgûl cuando conquistaron por primera vez Minas Ithil durante la Segunda Edad, y ocultado mediante hechizos de ocultación que no podían romperse mientras Sauron sobreviviera. Solo era visible para el Señor Oscuro y sus sirvientes, pero ahora, con su maestro derrotado, se revela a todos como el paso hacia la garganta de Thuringwath, que había estado oculta durante mucho tiempo."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "68.28S"; 
          ["LONG"] = "6.31E"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Torgris, la Grieta Oculta"; 
      ["PROGRESS"] = "Explora Torgris"; 
      ["LORE"] = "Con muchos de ellos demasiado temerosos para adentrarse en las sombras de Thuringwath, los Montaraces de Ithilien acampan en Torgris, la Grieta Oculta, una pequeña grieta en el corazón de Falch Gurth."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "68.10S"; 
          ["LONG"] = "6.46E"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Aufaltor, el Templo del Ojo"; 
      ["PROGRESS"] = "Explora Aufaltor"; 
      ["LORE"] = "En lo alto de una enorme tumba subterránea se encuentra Aufaltor, el Templo del Ojo. Sin número son aquellos contados entre los Muertos de Aufaltor, pues fue aquí donde los sirvientes de los Nazgûl depositaron los cuerpos sin vida de aquellos que consideraban indignos de los oscuros ritos de Agath-kali, Señora del Lamento, en Bâr Nírnaeth."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "70.17S"; 
          ["LONG"] = "10.39E"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Ufurok, el Fuerte del Terror"; 
      ["PROGRESS"] = "Explora Ufurok"; 
      ["LORE"] = "Fue a Ufurok, el Fuerte del Terror, donde el Rey Brujo de Angmar atrajo a cinco de los Hombres Demacrados más poderosos de los Días Antiguos. Su intención era empoderarlos, moldeándolos en reflejos terribles y retorcidos de los Magos cuya llegada a la Tierra Media amenazaba al Señor Oscuro. Las viles hechicerías del Rey Brujo los deshicieron y los remodelaron en Señores Demacrados. Estos eran sus nombres, y su número era cinco: Ivar la Mano Sangrienta, Thadúr el Despojador, Ferndúr el Virulento, Drugoth el Sembrador de Muerte y Gortheron el Exterminador."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "71.61S"; 
          ["LONG"] = "7.67E"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Laugdursh, el Tramo Terrible"; 
      ["PROGRESS"] = "Explora Laugdursh"; 
      ["LORE"] = "Mucho antes de que Ufurok se convirtiera en un monumento a los Señores Demacrados, era una fortaleza erigida en defensa de Bâr Nírnaeth. Era Laugdursh, la Extensión Temible por la que los Nazgûl y sus víctimas más desafortunadas viajaban hacia las Casas del Lamento. Cayó en desuso una vez que los Nazgûl adoptaron bestias terribles como sus monturas aladas en la Tercera Edad del mundo."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "72.48S"; 
          ["LONG"] = "7.66E"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Bâr Nírnaeth"; 
      ["PROGRESS"] = "Explora Bâr Nírnaeth"; 
      ["LORE"] = "Fue en Bâr Nírnaeth, las Casas del Lamento, donde los Nazgûl adoraban a su maestro Sauron. Muchos fueron los oscuros y profanos rituales que se llevaron a cabo aquí en su nombre, y la marca de esos terribles males aún permanece en cada uno de sus edificios y patios."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "73.54S"; 
          ["LONG"] = "7.65E"; 
        }; 
      }; 
      };
  };
