  -- Imlad Morgul / Explorando Rath Dúath
  [1879395366] = {
      [1] = {
      ["NAME"] = "Annon Morgul"; 
      ["PROGRESS"] = "Explora Annon Morgul"; 
      ["LORE"] = "Esta puerta occidental del valle podría cerrarse en caso de problemas, impidiendo el acceso a Ithilien. Esto ha ocurrido con bastante frecuencia durante la larga y tumultuosa historia de Gondor. Annon Morgul ha sido dañada por la guerra y ahora es una ruina."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "64.25S"; 
          ["LONG"] = "2.28W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Gúliant"; 
      ["PROGRESS"] = "Explora el Gúliant"; 
      ["LORE"] = "Este es el puente principal sobre el Morgulduin. Ha sido destruido y reconstruido varias veces a lo largo de la historia del Rath Duath, pero ahora se mantiene en pie, llevando la carretera principal hacia Minas Morgul a través de las aguas turbulentas."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "64.83S"; 
          ["LONG"] = "0.58W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Eithel Gwaur"; 
      ["PROGRESS"] = "Explora Eithel Gwaur, el Pozo putrefacto"; 
      ["LORE"] = "El Pozo putrefacto de Eithel Gwaur se encuentra en la fuente del Morgulduin, y parece ser la causa de la contagiosa suciedad de este río. No se sabe cuándo cayó en la corrupción y la enfermedad, pero el río no ha sido llamado Ithilduin durante muchos años, y sus aguas limpias son ahora solo un recuerdo lejano."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "66.63S"; 
          ["LONG"] = "7.46E"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Gorthad Nûr, el Túmulo Profundo"; 
      ["PROGRESS"] = "Explora Gorthad Nûr, el Túmulo profundo"; 
      ["LORE"] = "Incontables huesos llenan el Túmulo profundo de Gorthad Nûr, un osario profano tallado en la roca de las montañas. Las tumbas y los santuarios permanecen, pero han sido profanados por las artes oscuras. Los Kergrim aúllan entre las estatuas olvidadas, hambrientos de carne, pero se oyen pocos otros sonidos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "68.69S"; 
          ["LONG"] = "3.37E"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Estolad Lân"; 
      ["PROGRESS"] = "Explora Estolad Lân"; 
      ["LORE"] = "Anborn, Montaraz de Ithilien, ha establecido el campamento de Estolad Lân en el lado oeste del Rath Duath. Desde allí busca cumplir las órdenes del príncipe Faramir de Ithilien, aunque el campamento se encuentra casi directamente bajo la sombra de Minas Morgul."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "64.61S"; 
          ["LONG"] = "2.02W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Echad Uial"; 
      ["PROGRESS"] = "Explora Echad Uial"; 
      ["LORE"] = "La Compañía Blanca del príncipe Faramir estableció el campamento de Echad Uial en el lado este del Rath Dúath, con la intención de organizar expediciones hacia Minas Morgul. Pero han dedicado mucha atención a mantener la vigilancia en la Puerta del Terror de Fennas Gost, y nunca hay suficientes aventureros dispuestos a enfrentarse a la Ciudad Muerta."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "65.01S"; 
          ["LONG"] = "4.11E"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Râkh Mathán"; 
      ["PROGRESS"] = "Explora Râkh Mathán"; 
      ["LORE"] = "Las guaridas de los huargos de Râkh Mathán se extienden hasta las colinas que rodean Rath Dúath, y los aullidos de estas criaturas infunden miedo incluso en los valientes corazones de los Montaraces de Faramir. Especialmente en los Montaraces, ya que han sufrido muchas pérdidas a causa de los dientes y garras de las bestias durante los últimos meses, mientras los huargos se han aventurado más lejos de sus guaridas por orden de sus amos orcos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "63.39S"; 
          ["LONG"] = "4.14E"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Banám Lugaun"; 
      ["PROGRESS"] = "Explora Banám Lugaun"; 
      ["LORE"] = "El campamento orco de Banám Lugaun ve una gran actividad tanto de día como de noche, sirviendo como un punto de paso para los siervos del mal en su camino hacia un lugar u otro dentro de Imlad Morgul."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "63.30S"; 
          ["LONG"] = "1.07E"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Shakam Moz"; 
      ["PROGRESS"] = "Explora Shakam Moz"; 
      ["LORE"] = "El nido de morrovals de Shakam Moz vigila el Rath Duath y Lhingris desde la cima, y los siervos de Lhaereth la Mancillada aterrorizan a todos los que se ven obligados a viajar por esos valles."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "66.88S"; 
          ["LONG"] = "8.37E"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Dáru Lagúrz, las Casas Rotas"; 
      ["PROGRESS"] = "Explora Dáru Lagúrz, las casas en ruinas"; 
      ["LORE"] = "Los viles y desagradables Kergrims se han asentado en Daru Lagurz, hurgando entre los restos. La suciedad y la enfermedad los han seguido hasta las Casas en Ruinas, peligrosas para aquellos pocos que deben entrar en lo que alguna vez fue un lugar de descanso."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "67.74S"; 
          ["LONG"] = "4.90E"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "Taen Orwath"; 
      ["PROGRESS"] = "Explora Taen Orwath"; 
      ["LORE"] = "Pocos de los Montaraces de Ithilien se han aventurado en las colinas del Rath Duath. Allí, en un mirador, esos pocos han establecido el pequeño campamento de Taen Orwath."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "66.85S"; 
          ["LONG"] = "5.84E"; 
        }; 
      }; 
      };
  };
