  -- Imlad Morgul / Explorando Cirith Ungol
  [1879395370] = {
      [1] = {
      ["NAME"] = "La Escalera Recta"; 
      ["PROGRESS"] = "Explora la Escalera Recta"; 
      ["LORE"] = "Esta es la primera de las escaleras que subieron Frodo Bolsón, Samsagaz Gamyi y la criatura Gollum para intentar acceder a la Tierra de Mordor. Las escaleras son altas y empinadas, y aunque la subida es recta y sin curvas, los escalones son irregulares y traicioneros. Las escaleras están talladas en los flancos de las Ephel Dúath y suben desde el fondo del valle hasta el propio paso, en el lado occidental de Cirith Ungol."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "62.72S"; 
          ["LONG"] = "0.54W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "La Escalera Retorcida"; 
      ["PROGRESS"] = "Explora la Escalera Tortuosa"; 
      ["LORE"] = "Esta segunda escalera comienza muy por encima del fondo del valle y, a diferencia de la Escalera Recta, serpentea a lo largo del acantilado, con un gran abismo abierto a un lado. En la parte superior de las escaleras, una grieta oscura conduce a la entrada de Torech Ungol y a los horrores que se encuentran dentro."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "62.05S"; 
          ["LONG"] = "2.17E"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Echad Taerdim"; 
      ["PROGRESS"] = "Explora Echad Taerdim"; 
      ["LORE"] = "Mablung ha establecido el pequeño campamento de Echad Taerdim en la cima de la Escalera Recta, y tiene la intención de usarlo como base desde la cual montar pequeñas expediciones hacia el cercano Cirith Ungol."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "61.92S"; 
          ["LONG"] = "0.53W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Cadar Skûs"; 
      ["PROGRESS"] = "Explora Cadar Skûs"; 
      ["LORE"] = "Los Ungoledain han recorrido un largo camino por tierra a través de la Tierra Media, siguiendo un llamado que solo ellos pueden escuchar, y han establecido el lugar de descanso de Cadar Skûs en las montañas. ¿Está su largo viaje finalmente cerca de su fin?"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "59.26S"; 
          ["LONG"] = "1.08W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Torech Ungol"; 
      ["PROGRESS"] = "Explora Torech Ungol"; 
      ["LORE"] = "El paso de Cirith Ungol rara vez quedaba sin vigilancia, pero pocos se atrevían a cruzarlo mientras los orcos de la torre podían espiarlos desde arriba. El peligro más grande y peor se hablaba solo en susurros, ya que pocos buenos conocían siquiera rumores al respecto. Algún oscuro terror habitaba en el túnel de Torech Ungol, por el que debía pasar el camino. Incluso si un viajero lograba atravesar con seguridad el pasaje infestado de telarañas, el túnel daba paso a un abismo abierto al cielo pero lleno de bocas de cuevas en cada acantilado desde las cuales cualquier enemigo podría tener la ventaja de la sorpresa. Ningún estratega aconsejaría tomar ese camino.\n\nEra el terreno de caza favorito de Ungwetári, última hija de Ungoliant, y solo los muy tontos o los muy desesperados deberían ir por ese camino."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "27.33N"; 
          ["LONG"] = "12.74E"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Remmorchant, la Red de las Tinieblas"; 
      ["PROGRESS"] = "Explora Remmorchant"; 
      ["LORE"] = "Nadie ha pasado la entrada de Remmorchant, la Red de las Tinieblas, pues es el túnel más profundo y subterráneo de Ungwetári, el abismo sin fondo y sin luz al que se retiró tras su inesperada herida a manos de Samsagaz Gamyi y la punta de Dardo, la hoja forjada en Gondolin que empuñaron tanto Bilbo como Frodo Bolsón, y más tarde el aterrorizado pero letal jardinero de Bolsón Cerrado.\n\nUngwetári no sabía nada de esos hobbits ni del linaje de esa hoja, pero recuerda el dolor de aquel encuentro, y eso le ha generado una rabia cegadora y ardiente. En Remmorchant medita sobre su herida y se consume en su odio."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "34.63N"; 
          ["LONG"] = "14.08E"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Taurlingol"; 
      ["PROGRESS"] = "Explora Taurlingol"; 
      ["LORE"] = "El bosque de Taurlingol se ha convertido en un lugar infestado de arañas, lleno de telarañas y voces antinaturales. Si los Ungoledain pueden entender el chasquido de sus ídolos, no están dispuestos a compartir su significado. Probablemente sea algo bueno."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "60.11S"; 
          ["LONG"] = "3.24E"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Kaslokroz"; 
      ["PROGRESS"] = "Explora Kaslokroz"; 
      ["LORE"] = "Los Uruks siguiendo las órdenes de Rukhor, el Heraldo Pálido, han establecido este campamento en la cima de la Escalera Tortuosa, al oeste de Cirith Ungol. Parece que se han enfrentado a los Ungoledain y a las arañas que merodean por Taurlingol y Torech Ungol, lo cual no es sorprendente. Como era de esperar, algunos uruks también han caído en luchas internas entre ellos y con otras bandas de orcos que se arrastran desde la torre y a través del paso."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "61.66S"; 
          ["LONG"] = "1.83E"; 
        }; 
      }; 
      };
  };
