  -- Manantiales del Río Grande / Formaciones naturales en los Manantiales del Río Grande
  [1879405904] = {
      [1] = {
      ["NAME"] = "Tithroz"; 
      ["PROGRESS"] = "Explora Tithroz"; 
      ["LORE"] = "Las Colinas Inundadas están llenas de cuevas, pero los Beórnidas que viven en esta zona prefieren no aventurarse en sus profundidades oscuras y estrechas. Insectos repugnantes, murciélagos pestilentes y excavadores con dientes afilados hacen sus hogares en estos lugares, y la gente de Limlók solo desea preocuparse por estas desagradables criaturas si salen a la luz del sol o de la luna."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "25.86N"; 
          ["LONG"] = "1.47W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Reikfoss de Greylin"; 
      ["PROGRESS"] = "Explora el Reikfoss de la Greylin"; 
      ["LORE"] = "La gran cascada del Reikfoss marca el lugar donde el río Greylin fluye desde Valle Ancestral hacia el Valle de la Niebla para formar una de las cascadas de las Tres Hermanas. Juntas, los vapores que se elevan desde la base del Reikfoss y los de las Cascadas Gemelas cubren todo el Valle de la Niebla."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "31.85N"; 
          ["LONG"] = "60.03W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Cascadas Gemelas"; 
      ["PROGRESS"] = "Explora Las Cascadas Gemelas"; 
      ["LORE"] = "Las dos Cascadas Gemelas se forman en el paso del Río Grande y un arroyo más pequeño que fluye desde Valle Ancestral hacia el Valle de la Niebla. Junto con el Reikfoss, estas tres cascadas forman las Tres Hermanas, cuyos vapores combinados cubren todo el Valle de la Niebla."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "31.44N"; 
          ["LONG"] = "62.75W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Veithhól"; 
      ["PROGRESS"] = "Explora Veithhól"; 
      ["LORE"] = "Las laderas rocosas de Veithhól sirven de guarida a los gatos salvajes que acechan en Havrebrume. Los pocos aventureros que se han encontrado en esta zona informan haber escuchado el sonido de pasos suaves y sigilosos en algún lugar de la niebla. La consecuencia natural de estos informes parece obvia para los más sabios entre nosotros: los gatos no debían tener hambre, o estos informes no existirían."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "30.52N"; 
          ["LONG"] = "58.31W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Valle del Rascador"; 
      ["PROGRESS"] = "Explora el Valle del Rascador"; 
      ["LORE"] = "Las grietas estrechas del Valle del Rascador han sido ampliadas por el incansable trabajo de los Rascacuevas que viven allí, un esfuerzo laborioso que solo se detiene cuando es hora de que las criaturas se alimenten. Esto lo hacen con las desafortunadas bestias que tropiezan en el Valle, y con los aventureros que hacen lo mismo. Estas últimas comidas tienden a subestimar a las criaturas como 'simples rascacuevas,' un error de juicio que los habitantes del Valle del Rascador están más que felices de fomentar."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "26.35N"; 
          ["LONG"] = "5.54W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Cabed Rhimdath"; 
      ["PROGRESS"] = "Explora el Cabed Rhimdath"; 
      ["LORE"] = "El paso rocoso de Cabed Rhimdath sirve como camino para aquellos Holbytlan que se atreven a aventurarse desde la seguridad de su hogar en Lyndelby. Los pocos que han viajado al Cabed Rhimdath han informado de zarzas espesas y extrañas piedras pintadas antes de darse la vuelta en el sitio de las Águilas que acechan."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "26.32N"; 
          ["LONG"] = "62.45W"; 
        }; 
      }; 
      };
  };
