  -- Manantiales del Río Grande / Ruinas en los Manantiales del Río Grande
  [1879405906] = {
      [1] = {
      ["NAME"] = "Sundergrót"; 
      ["PROGRESS"] = "Encuentra Sundergrót"; 
      ["LORE"] = "La historia de Sundergrot está envuelta en misterio, pues ha estado abandonada durante mucho tiempo. La tradición de los Barbiluengos sostiene que esta gran grieta que domina las Colinas Inundadas fue hecha por el impacto del hacha de Durin en algún momento de la Primera Edad.\n\nHoy en día, las ruinas están habitadas por goblins, pero ellos no saben nada de los antiguos acontecimientos que allí tuvieron lugar. Para los trasgos, solo es un recuerdo del trabajo de los Enanos, y eso es un agudo puñal de odio para ellos, aunque codician los tesoros y gemas que sus enemigos desentierran."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "31.84N"; 
          ["LONG"] = "33.19E"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Yegua Blanca"; 
      ["PROGRESS"] = "Encuentra la Yegua Blanca"; 
      ["LORE"] = "En algún momento durante la residencia de los Éothéod en estas tierras, tallaron la Yegua Blanca en una ladera de las Colinas Inundadas. No se sabe si su forma distintiva estaba destinada a representar a los mearas que encontraron pastando en la franja de tierra entre los Cascadas Gemelas y el Reikfoss, pero parece probable. La Yegua Blanca hoy está descolorida y algo cubierta de vegetación, pero sigue siendo un recordatorio del amor de los Éothéod por los caballos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "22.26N"; 
          ["LONG"] = "56.29W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Skerabrygg"; 
      ["PROGRESS"] = "Encuentra Skerabrygg"; 
      ["LORE"] = "El puente de Skerabrygg, construido por los Enanos, permitía el paso del Río Grande a aquellos que querían explorar Sundergrot, pero hoy el puente está destruido. Alguien lo ha reparado apresuradamente con tablones de madera, pero parece una solución temporal. El viento y la lluvia de la Lande inundada sin duda pronto harán que este camino se derrumbe en el río."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "17.92N"; 
          ["LONG"] = "58.70W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "El Salto de Hengi"; 
      ["PROGRESS"] = "Encuentra el Salto de Hengi"; 
      ["LORE"] = "Quienquiera que haya sido Hengi, y el conocimiento de por qué este puente de enanos roto lleva su nombre, se ha perdido con el tiempo."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "23.27N"; 
          ["LONG"] = "60.12W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Framsburgo"; 
      ["PROGRESS"] = "Encuentra Framsburg"; 
      ["LORE"] = "El gran bastión de los Ai-thuda se llamaba Fasthalla, y era la sede de su jefe Frumgar. Cuando Scatha el Gusano lo quemó y destruyó, y Frumgar resultó gravemente herido, su joven hijo Fram juró vengarse del gran dragón sin alas. Finalmente lo logró, y Fram se convirtió en Fram Rompegusanos. Los Ai-thuda reconstruyeron Fasthalla y le dieron un nuevo nombre: Framsburg.\n\nDesde su ubicación en lo alto de un espolón rocoso en Valle de la Niebla, Framsburg no podía ser fácilmente conquistado por los Orcos, aunque estos pusieron a prueba sus defensas y la determinación de sus habitantes de vez en cuando. Tras la partida de los Éothéod, Framsburg cayó gradualmente en ruinas por negligencia. Nunca fue saqueado, pero con el tiempo quedó vacío y los Orcos merodeaban por las ruinas.\n\nHoy en día, gusanos y dragonzuelos han construido nidos entre los esqueletos de antiguos edificios, y Framsburg les pertenece. De esta manera, quizás Scatha finalmente haya logrado vengarse de Fram Rompegusanos y del recuerdo de su pueblo."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "30.33N"; 
          ["LONG"] = "52.91W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Lumrog"; 
      ["PROGRESS"] = "Encuentra Lumrog"; 
      ["LORE"] = "Los trolls de las colinas y sus desagradables aliados han erigido una barricada en Lumrog, vigilando el paso por la carretera y no permitiendo que nadie pase. Se desconoce si este bloqueo está motivado por el interés propio o si ha sido ordenado por poderes más astutos con mayores planes."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "28.41N"; 
          ["LONG"] = "59.54W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Stramvárth"; 
      ["PROGRESS"] = "Encuentra Stramvárth"; 
      ["LORE"] = "Los tragos de Stramvárth buscan entre las ruinas de Sundergrot tesoros, luchando entre ellos por el derecho a conservar las piezas más valiosas."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "19.25N"; 
          ["LONG"] = "59.22W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Egvárth"; 
      ["PROGRESS"] = "Encuentra Egvárth"; 
      ["LORE"] = "Los trasgos y los orcos de Egvarth se pelearon con sus congéneres del este por el derecho a acampar más cerca de Sundergrot. Podrían arrepentirse de esa decisión si en las profundidades de esa grieta se encontrara algo más que tesoros."; 
