  -- Manantiales del Río Grande / Asentamientos en los Manantiales del Río Grande
  [1879405913] = {
      [1] = {
      ["NAME"] = "Limlók"; 
      ["PROGRESS"] = "Explora el pueblo beórnida de Limlók"; 
      ["LORE"] = "Tras la muerte de su jefe Bolgo durante la Batalla de los Cinco Ejércitos, los Orcos de las Montañas Nubladas entraron en declive. Esta reducción de su número y poder no duraría para siempre, pero durante este tiempo el pueblo de Beorn pudo reafirmar su presencia en las Colinas Inundadas, vagando por los páramos más abiertamente. En las Colinas Inundadas construyeron el pueblo de Limlók, que sería la localidad más septentrional del pueblo de Beorn.\n\nAl igual que los arbustos crecidos y las raíces enmarañadas de las tierras bajas, los Beórnidas son más salvajes en las Colinas Inundadas. Hoy en día, el jefe del pueblo es Runerik Barbanudosa, y desconfía de los forasteros, creyendo que su propio pueblo posee la fuerza suficiente para rechazar cualquier posible incursión desde Gundabad o cualquier otro lugar."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "20.83N"; 
          ["LONG"] = "56.02W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Lyndelby"; 
      ["PROGRESS"] = "Explora el pueblo escondido de Lyndelby"; 
      ["LORE"] = "Esta rústica aldea de smials se encuentra entre acantilados escarpados, oculta hasta hoy a los ojos de los Sabios y protegida de cualquier descubrimiento por las Águilas guardianas que habitan en las altas cumbres. ¿Podría haber sido este el último lugar de residencia de los Holbytlan que una vez prosperaron en el Valle de la Niebla y en las Colinas Inundadas, y que a menudo aparecían en los Cuentos de los Éothéod? Si es así, sería el hogar de los descendientes de aquellos Albos que no cruzaron las Montañas Nubladas en su eventual camino hacia lo que se convertiría en la Comarca."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "26.68N"; 
          ["LONG"] = "65.73W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Thokvist"; 
      ["PROGRESS"] = "Explora Thokvist"; 
      ["LORE"] = "Thokvist ha sido el hogar de Skarding Azotedeorcos durante muchos años, pero el pequeño campamento a menudo queda sin vigilancia; el Beórnida pasa la mayor parte de su tiempo cazando peligros hostiles entre las brumas del Valle de la Niebla. Cuando regresa a casa, es solo por un corto tiempo, tal vez para disfrutar de una de las manzanas que crecen en los árboles fuera de su hogar y descansar brevemente antes de salir nuevamente."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "25.92N"; 
          ["LONG"] = "58.37W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Hlithseld"; 
      ["PROGRESS"] = "Explora Hlithseld"; 
      ["LORE"] = "Quizá en los años venideros, cuando la historia de los Éothéod haya sido ampliada por el viaje de Léothred y sus estudios académicos, el nombre de Hlithseld será considerado con gran estima. '¡Aquí acampó durante su búsqueda de conocimiento!' dirán tal vez los habitantes... o tal vez no. No siempre es fácil saber qué será recordado."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "30.48N"; 
          ["LONG"] = "59.25W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Shulgmokh"; 
      ["PROGRESS"] = "Explora Shulgmokh"; 
      ["LORE"] = "Los Beórnidas de las Colinas Inundadas no saben si los trolls silvanos de Shulgmokh están relacionados con los Taurogrim de otras tierras, y no les importa mucho. Les preocupa mucho más el tiempo que se tarda en arrancar la madera vital de la que dependen, y su deseo de detener a estas criaturas que amenazan Limlók."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "21.33N"; 
          ["LONG"] = "52.30W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Ujâk-fulug"; 
      ["PROGRESS"] = "Explora Ujâk-fulug"; 
      ["LORE"] = "Los huargos de Ujâk-fulug preferirían atacar a los débiles y cobardes, pero hay pocos de esos en las Colinas Inundadas, ya que esa tierra es dura y quienes viven allí son más fuertes y resistentes. Los huargos se contentan con alimentarse de bestias salvajes y cabras que se alejan demasiado de sus protectores, pero estas presas solo agudizan su apetito por carnes más desafiantes y sustanciosas."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "19.20N"; 
          ["LONG"] = "52.77W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Grazadh-gropor"; 
      ["PROGRESS"] = "Explora Grazadh-gropor"; 
      ["LORE"] = "La mayor amenaza que representan los trolls silvanos de Grazadh-gropor es la sorpresa, ya que la región boscosa que es su hogar cruje y se balancea con cada brisa que perturba la niebla asentada. El sonido de estas quejas arbóreas sirve para ocultar el acercamiento de los trolls silvanos hasta que están muy cerca de su víctima, y entonces es demasiado tarde."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "25.44N"; 
          ["LONG"] = "55.45W"; 
        }; 
      }; 
      };
  };
