  -- Valle Ancestral / Campo de batalla de la Guerra de las Tres Cumbres
  [1879411142] = {
      [1] = {
      ["NAME"] = "Shakal-atrâd"; 
      ["PROGRESS"] = "Descubre Shakal-atrâd"; 
      ["LORE"] = "Tras la derrota de los ritualistas angmarim que residían en su interior, Shakal-atrâd vuelve a pertenecer a los enanos. Recuperar las ruinas fue un paso adelante, un pequeño paso, quizás, pero un paso adelante al fin y al cabo."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "99.33S"; 
          ["LONG"] = "16.44W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Zarkul-sulûn"; 
      ["PROGRESS"] = "Descubre Zarkul-sulûn"; 
      ["LORE"] = "Las sólidas fortificaciones han reemplazado las barreras orcas que anteriormente protegían Zarkul-sulûn, manteniendo a raya a los enemigos de los enanos. Es desde aquí que los enanos elaboran nuevas estrategias con las que derrotar a sus enemigos y quizás se atrevan a soñar con recuperar Gundabad por fin."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "100.76S"; 
          ["LONG"] = "17.21W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Paso de los Aulladores"; 
      ["PROGRESS"] = "Descubre el Paso de los Aulladores"; 
      ["LORE"] = "Donde antes el aullido inquietante de los huargos llenaba el aire alrededor del Paso de los Aulladores, ahora solo se puede escuchar el gruñido gutural de las bestias de las colinas. La antigua guarida de los huargos alberga a feroces bestias de las colinas, manipuladas y criadas para la guerra por los domadores de bestias hobotrasgos. Jaulas y cadenas aprisionan a las salvajes bestias de las colinas que han sido capturadas en contra de su voluntad."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "97.86S"; 
          ["LONG"] = "16.95W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Zudramdân"; 
      ["PROGRESS"] = "Descubre Zudramdân"; 
      ["LORE"] = "Las fuerzas orcas abrumaron a los enanos en Zudramdân y reclamaron las ruinas como propias. Ahora Zudramdân es una sombra de lo que fue, su interior incendiado y lleno de orcos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "96.87S"; 
          ["LONG"] = "19.07W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Caivád Sâr"; 
      ["PROGRESS"] = "Descubre Caivád Sâr"; 
      ["LORE"] = "Caivád Sâr sigue siendo una fortaleza para las fuerzas malignas del Valle Ancestral. Sin inmutarse, y quizás alimentados por la guerra que se libra en el exterior, los angmarim continúan torturando y experimentando en sus espantosas cámaras."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "95.00S"; 
          ["LONG"] = "18.99W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Drenghól"; 
      ["PROGRESS"] = "Descubre Drenghól"; 
      ["LORE"] = "A pesar de estar profundamente atrincherado en territorio enemigo, Drenghól ha permanecido oculto a los ojos curiosos del enemigo. Su posición dentro del Valle Ancestral ha resultado útil, ya que ofrece una vista clara de las murallas exteriores de Gundabad."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "94.88S"; 
          ["LONG"] = "19.85W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Ifbar-athrâkh"; 
      ["PROGRESS"] = "Descubre Ifbar-athrâkh"; 
      ["LORE"] = "En las líneas del frente, la vanguardia de Gabil'akkâ mantiene su posición, plantándose firmemente en las trincheras. Un flujo interminable de órdenes entra y sale de Ifbar-athrâkh, el centro de mando que los enanos han excavado cerca. Mientras que otros deben pensar en el panorama general de la guerra, los que están en Ifbar-athrâkh se ocupan de los detalles de la toma y el control del territorio orco."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "98.50S"; 
          ["LONG"] = "18.38W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Ushkútoz"; 
      ["PROGRESS"] = "Descubre Ushkútoz"; 
      ["LORE"] = "Los orcos han excavado túneles serpenteantes a la sombra de Zudramdân, profanando aún más las ruinas enanas. Desde estos túneles, elaboran planes para frustrar a la vanguardia de Gabil'akkâ y reforzar sus propias defensas."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "96.92S"; 
          ["LONG"] = "19.07W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Bagûd-mekhem"; 
      ["PROGRESS"] = "Descubre Bagûd-mekhem"; 
      ["LORE"] = "Situado en las regiones septentrionales del Valle Ancestral, Bagûd-mekhem se extiende desde Gundabad y se asoma al valle. A esta altitud, los vientos fríos traen un escalofrío antinatural. Combinado con los enjambres de orcos listos para la batalla, Bagûd-mekhem es un espectáculo imponente."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "93.40S"; 
          ["LONG"] = "21.06W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Azgh-buzru, la Loma de la Guerra"; 
      ["PROGRESS"] = "Descubre Azgh-buzru, la Loma de la Guerra"; 
      ["LORE"] = "La Guerra de las Tres Cumbres ha transformado una llanura del Valle Ancestral que antes estaba cubierta de hierba en Azgh-buzru, la Loma de la Guerra. Al igual que Azanulbizar de antaño, este será el sitio de los enfrentamientos más sangrientos entre los enanos de los Gabil'akkâ y los orcos de Gundabad."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "95.14S"; 
          ["LONG"] = "20.74W"; 
        }; 
      }; 
      };
  };
