  -- Valle Ancestral / Ruinas de enanos del Valle Ancestral
  [1879411148] = {
      [1] = {
      ["NAME"] = "Puente de Hárveg"; 
      ["PROGRESS"] = "Descubre el puente de Hárveg"; 
      ["LORE"] = "Perchado sobre el río Greylin, el puente de Hárveg había estado, hasta hace poco, roto e intransitable. Los enanos han reparado hábilmente el puente, abriendo un paso seguro hacia y desde Valle de la Niebla una vez más."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "32.63N"; 
          ["LONG"] = "59.71W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Annâk-khurfu"; 
      ["PROGRESS"] = "Descubre Annâk-khurfu"; 
      ["LORE"] = "A pesar de los muchos años que ha soportado, Annâk-khurfu sigue en pie. Los enanos se han reunido en estas ruinas y han llamado a sus aliados a las armas, preparándose para lo inevitable.\n\nAnnâk-khurfu ofrece una vista ventajosa de las principales rutas que conducen al Valle Ancestral: desde Ered Mithrin al este y Valle de la Niebla al sur, donde se pueden ver claramente amigos y enemigos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "32.74N"; 
          ["LONG"] = "61.12W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Zarkul-sulûn"; 
      ["PROGRESS"] = "Descubre Zarkul-sulûn"; 
      ["LORE"] = "Los años no han sido amables con Zarkul-sulûn, que ahora alberga todo tipo de maldad: orcos, trasgos, huargos y quizás otros.\n\nLas ruinas están demasiado cerca de Annâk-khurfu para la comodidad de los enanos. Mantienen un ojo vigilante sobre Zarkul-sulûn, entendiendo que será el primero de muchos obstáculos que deberán superar si desean recuperar Gundabad."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "32.78N"; 
          ["LONG"] = "62.77W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Shakal-atrâd"; 
      ["PROGRESS"] = "Descubre Shakal-atrâd"; 
      ["LORE"] = "Las fuerzas de Gundabad han mantenido durante mucho tiempo Shakal-atrâd bajo su control. Aunque todo parece tranquilo fuera de estas siniestras ruinas, adentrarse más podría revelar lo contrario..."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "34.11N"; 
          ["LONG"] = "62.50W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Zudramdân"; 
      ["PROGRESS"] = "Descubre Zudramdân"; 
      ["LORE"] = "Zudramdân no es tan formidable como Annâk-khurfu, pero el campamento norte de los enanos les permite cierta seguridad en la larga lucha por recuperar su hogar."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "36.80N"; 
          ["LONG"] = "64.65W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Grálinvarth"; 
      ["PROGRESS"] = "Descubre Grálinvarth"; 
      ["LORE"] = "Las rugientes cataratas del río Greylin ahogan incluso los sonidos más fuertes en Grálinvarth. Desde este punto de vista, se puede ver fácilmente Courseporte y Annâk-khurfu, así como vislumbrar el valle de Valle de la Niebla en un día despejado."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "35.32N"; 
          ["LONG"] = "58.45W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Puertas de Gundabad"; 
      ["PROGRESS"] = "Descubre las Puertas de Gundabad"; 
      ["LORE"] = "Las construcciones rudimentarias desfiguran las Puertas de Gundabad, un recordatorio burlón de las pérdidas y derrotas de los enanos. Uno podría preguntarse qué más han hecho los orcos para corromper aún más el antiguo reino enano más allá de este umbral siniestro."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "38.07N"; 
          ["LONG"] = "68.43W"; 
        }; 
      }; 
      };
  };
