  -- Valle Ancestral / Campamentos enemigos del Valle Ancestral
  [1879411174] = {
      [1] = {
      ["NAME"] = "Paso de los Aulladores"; 
      ["PROGRESS"] = "Descubre el Paso de los Aulladores"; 
      ["LORE"] = "Los afloramientos rocosos y las cuevas ocultas de las colinas del Valle Ancestral son un lugar perfecto para las guaridas de Huargos. El suelo está lleno de huesos y las armas de aquellos que intentaron y fracasaron contra las bestias.\n\nUn olor fétido impregna el aire, y se puede escuchar el retumbar de gruñidos bajos en la distancia."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "35.75N"; 
          ["LONG"] = "62.58W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Malkorlash"; 
      ["PROGRESS"] = "Descubre Malkorlash"; 
      ["LORE"] = "Agazapado entre los huesos blanqueados por el sol de antiguos gusanos, Malkorlash otorga a los hobgoblins el control tanto del río como de los caminos cercanos. El campamento también sirve para dificultar el paso a través de las colinas hasta el río Wyrmsgráf en el lado este. El paso lleno de hobotrasgos y dragones es de donde Malkorlash, 'brecha en la montaña,' obtiene su nombre."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "40.79N"; 
          ["LONG"] = "62.76W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Hanksar-mokh"; 
      ["PROGRESS"] = "Descubre Hanksar-mokh"; 
      ["LORE"] = "Acechando en las sombras de las grandes murallas de Gundabad, Hanksar-mokh es un nido vil de Orcos. Alrededor de los montones de huesos y las tiendas de piel, se encuentran en ruinas antiguas estructuras construidas por enanos, dando una pista de la gloria pasada. Andamios rudimentarios permiten a los hobgoblins subir y bajar por las murallas sin tener que usar las enormes escaleras de Gundabad."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "37.59N"; 
          ["LONG"] = "68.29W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Bagûd-mekhem"; 
      ["PROGRESS"] = "Descubre Bagûd-mekhem"; 
      ["LORE"] = "El aire alrededor de Bagûd-mekhem es anormalmente frío, con vientos cortantes que atraviesan todo excepto las pieles y cueros más gruesos. Se han erigido andamios precarios y muros altos y toscos alrededor de las murallas del norte de Gundabad. Orcos, goblins y criaturas aún más temidas se agolpan entre muros de madera y piedra."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "39.68N"; 
          ["LONG"] = "66.37W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Dûn Traikh"; 
      ["PROGRESS"] = "Descubre Dûn Traikh"; 
      ["LORE"] = "Dûn Traikh es testigo de hasta dónde han llegado los Angmarim en el Valle Ancestral, y durante cuánto tiempo han disfrutado de un reinado libre en las tierras de los enanos. Aunque su reino ha caído, hay quienes dentro de los muros de Dûn Traikh se esfuerzan por devolver el reino que una vez engendró el Rey Brujo de Angmar."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "36.19N"; 
          ["LONG"] = "68.10W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Caivád Sâr"; 
      ["PROGRESS"] = "Descubre Caivád Sâr"; 
      ["LORE"] = "Oscura e imponente, la flecha de Caivad Sâr es el lugar donde los Angmarim vienen a participar en rituales, artes arcanas y tortura. Caivad Sâr proporciona una línea de defensa a lo largo del camino oriental, albergando numerosas fuerzas mortales. Su torre se eleva hacia los cielos, una garra que se extiende desde la cual se pueden detectar enemigos a millas de distancia."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "38.51N"; 
          ["LONG"] = "64.65W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Kulûg-mokh"; 
      ["PROGRESS"] = "Descubre Kulûg-mokh"; 
      ["LORE"] = "Acechando en las sombras de las grandes murallas de Gundabad y siendo el gemelo de Hanksar-mokh, Kulûg-mokh también es un vil nido de Orcos. Alrededor de los montones de huesos y las tiendas de piel, se encuentran en ruinas antiguas estructuras construidas por enanos, dando una pista de la gloria pasada. Andamios rudimentarios permiten a los hobotrasgos subir y bajar por las murallas sin tener que usar las enormes escaleras de Gundabad."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "38.32N"; 
          ["LONG"] = "68.04W"; 
        }; 
      }; 
      };
  };
