  -- Tierras de Bree / Lugares del Bosque Salvaje
  [1879414505] = {
      [1] = {
      ["NAME"] = "Embarcadero de los comerciantes"; 
      ["PROGRESS"] = "Explora el embarcadero de los comerciantes"; 
      ["LORE"] = "El embarcadero de los comerciantes es la base de operaciones de la Liga del Hacha y uno de los pocos puntos de acceso al Bosque Salvaje. Comerciantes, cazadores, mineros y otros pasan por este pequeño puerto al ir y volver de recolectar recursos en los bosques."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "21.31S"; 
          ["LONG"] = "61.45W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Retoral"; 
      ["PROGRESS"] = "Explora Retoral"; 
      ["LORE"] = "Los retorcidos túneles de Retoral fueron excavados en las colinas hace mucho tiempo por mineros desconocidos. Abandonadas durante siglos, las minas se han convertido en un campo de batalla disputado entre los que buscan su riqueza y secretos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "14.81S"; 
          ["LONG"] = "53.09E"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Mina Este"; 
      ["PROGRESS"] = "Explora la Mina Este"; 
      ["LORE"] = "Enormes vigas de madera bordean las paredes rocosas que conducen a la entrada oriental de las minas de Retoral."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "23.90S"; 
          ["LONG"] = "60.79W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Mina Oeste"; 
      ["PROGRESS"] = "Explora la Mina Oeste"; 
      ["LORE"] = "Soportes de madera y andamios bordean los muros de la entrada occidental de las minas de Retoral. La fosa ha sido excavada en la montaña a lo largo de incontables generaciones, pero las minas se adentran todavía más en su interior."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "23.88S"; 
          ["LONG"] = "61.91W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "El Cruce de Marl"; 
      ["PROGRESS"] = "Explora el Cruce de Marl"; 
      ["LORE"] = "Muy alto sobre los rápidos y aguas turbulentas del Pozohondo, un puente improvisado se balancea con el viento. Marl el Treparriscos fue el primer hombre de la historia conocido por haber escalado los muros del abismo de Cirith Nûr. Lamentablemente, la bestia que aguardaba al acecho en el lado del Bosque Salvaje acabó rápidamente con el aventurero."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "16.83S"; 
          ["LONG"] = "60.19W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Mirador del Cazador"; 
      ["PROGRESS"] = "Explora el Mirador del Cazador"; 
      ["LORE"] = "Este promontorio rocoso sobre el centro del Bosque Salvaje ofrece una vista despejada del valle que lo rodea. Debido a las peligrosas bestias que frecuentan este área, no está claro quién es el cazador y quién la presa."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.33S"; 
          ["LONG"] = "57.61W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Risco de Helva"; 
      ["PROGRESS"] = "Explora el Risco de Helva"; 
      ["LORE"] = "En los días antes de que Cotfast fuera invadido, una de las niñas del pueblo se alejó de sus padres. Al día siguiente, encontraron a Helva de espaldas a este acantilado, con lobos acercándose a ella. Un ciervo blanco, brillante como la nieve, se erguía ante ella manteniendo a los lobos a raya. La llegada de los aldeanos hizo que los lobos se vieran superados en número y se disperaran. El ciervo tocó suavemente con su nariz la cabeza de la niña antes de desaparecer por el risco."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "21.60S"; 
          ["LONG"] = "58.27W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Pradera de Blomley"; 
      ["PROGRESS"] = "Explora la Pradera de Blomley"; 
      ["LORE"] = "La Pradera de Blomley es un hermoso prado, alfombrado con espesa hierba verde e innumerables flores blancas. Sería el lugar perfecto para un picnic hobit, si no fuera por las bestias que merodean por la ladera de la colina y los bosques cercanos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "22.54S"; 
          ["LONG"] = "60.84W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "La Casa del Viejo Risco"; 
      ["PROGRESS"] = "Explora la Casa del Viejo Risco"; 
      ["LORE"] = "La naturaleza ha reclamado los muros en ruinas y la cúpula destrozada de este antiguo mirador. La vista desde el promontorio abarca gran parte del Bosque Salvaje, pero la Casa del Viejo Risco no parece haber sido una torre de vigilancia. En cambio, la estructura recuerda una época en la que era posible construir por el simple placer de la belleza."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "23.50S"; 
          ["LONG"] = "59.24W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Salón Sobrevino"; 
      ["PROGRESS"] = "Explora el Salón Sobrevino"; 
      ["LORE"] = "Esta antigua ruina arnoriana se erigió en su día como centinela, vigilando el río Brandivino. Hoy en día, sus ruinosos muros albergan fuerzas oscuras que utilizan el Salón Sobrevino como base desde la que partir para asolar y saquear el Bosque Salvaje."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "19.72S"; 
          ["LONG"] = "59.50W"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "Guardanorte"; 
      ["PROGRESS"] = "Explora Guardanorte"; 
      ["LORE"] = "La alta y estrecha torre de Guardanorte ahora es el hogar de aquellos contra quienes debía proteger. Los años no han sido amables con la antigua mampostería de la torre de vigilancia, ni con sus nuevos residentes."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.47S"; 
          ["LONG"] = "55.21W"; 
        }; 
      }; 
      };
      [12] = {
      ["NAME"] = "Guardasur"; 
      ["PROGRESS"] = "Explora Guardasur"; 
      ["LORE"] = "Tallada en la roca madre de la montaña, Guardasur fue en su día una majestuosa torre de vigilancia arnoriana. Desde entonces ha caído en la ruina y ocupantes actuales la profanan aún más."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "23.57S"; 
          ["LONG"] = "56.01W"; 
        }; 
      }; 
      };
      [13] = {
      ["NAME"] = "Cotfast"; 
      ["PROGRESS"] = "Explora Cotfast"; 
      ["LORE"] = "El pequeño pueblo de Cotfast fue construido originalmente por los Pueblos Libres. Los aldeanos se vieron obligados a abandonarlo debido a una mala cosecha y las crecientes amenazas y peligros del Bosque Salvaje. Hoy día, bandidos y orcos lo habitan por igual."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "19.91S"; 
          ["LONG"] = "56.84W"; 
        }; 
      }; 
      };
      [14] = {
      ["NAME"] = "Fosa de Roehuesos"; 
      ["PROGRESS"] = "Explora la Fosa de Roehuesos"; 
      ["LORE"] = "Huesos blanqueados por el sol y espadas oxidadas cubren la ladera de la Fosa de Roehuesos. Los huargos que habitan entre las rocas se han vuelto fuertes y feroces gracias a la abundancia del Bosque Salvaje."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "19.35S"; 
          ["LONG"] = "55.29W"; 
        }; 
      }; 
      };
  };
