  -- Sangre de Azog / Restos de Khazad-dûm
  [1879415678] = {
      [1] = {
      ["NAME"] = "Amdân, el Umbral"; 
      ["PROGRESS"] = "Infórmate sobre Amdân"; 
      ["LORE"] = "'Antes de la caída de Moria, Amdân era un próspero pueblo comercial que surgió bajo el gran arco que Durin en persona había colocado en la frontera sur del reino de Khazad-dûm. Ahora se ha convertido en el campamento de concentración de los Haban’akkâ.'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "63.78N"; 
          ["LONG"] = "134.96W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Gabilthurkhu, el gran camino"; 
      ["PROGRESS"] = "Infórmate sobre Gabilthurkhu"; 
      ["LORE"] = "'En su momento una importante vía de comunicación y ruta comercial que salía de Khazad-dûm a través de Amdân y llegaba a las Montañas Nubladas, la gran vía había desaparecido en gran medida tras la caída de Moria, dejando solo piedras dispersas y señales en su camino.'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "64.95N"; 
          ["LONG"] = "134.56W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Labam-gairu, la Hendidura Blanca"; 
      ["PROGRESS"] = "Infórmate sobre Labam-gairu"; 
      ["LORE"] = "'En pleno invierno, Labam-gairu, o la Hendidura Blanca en la lengua común, estaba casi completamente congelada. Aun así, el agua fría seguía fluyendo desde sus cataratas orientales mientras se acercaba a las tierras de los Elfos, pero este relato no trata de su reino.'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "64.03N"; 
          ["LONG"] = "135.66W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Khur Azan, el Cruce Tenebroso"; 
      ["PROGRESS"] = "Infórmate sobre Khur Azan"; 
      ["LORE"] = "'En Khur Azan se encontraban los caminos que llevaban a Khazad-dûm y Lórien. En tiempos pasados, se erigió un pabellón de piedra en conmemoración de la amistad entre enanos y elfos. El pabellón de Khur Azan aún se mantiene en pie, pero el reino de los elfos ahora parece frío y distante, incluso bajo sus brillantes y doradas cornisas.'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "64.45N"; 
          ["LONG"] = "133.01W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Kibil-nâla, el Cauce de Plata"; 
      ["PROGRESS"] = "Infórmate sobre Kibil-nâla"; 
      ["LORE"] = "'¡Ah, el Cauce de Plata! ¡Más brillante y frío que nunca! Cayendo desde Kheled-zâram, su fresca bruma calmaba las heridas de la guerra.'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "64.82N"; 
          ["LONG"] = "133.08W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Tharkh Shathur"; 
      ["PROGRESS"] = "Infórmate sobre Tharkh Shathur"; 
      ["LORE"] = "'Una vez el paso hacia Atrad-zarakh, una avalancha en las laderas de Shathûr lo dejó inaccesible durante muchos años después de la caída de Moria. Al construir uno de sus puentes rudimentarios para llegar al antiguo paso, ¡parece que los Orcos nos han hecho, sin saberlo, un gran favor!'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "68.17N"; 
          ["LONG"] = "132.19W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Ashmargathâl"; 
      ["PROGRESS"] = "Infórmate sobre Ashmargathâl"; 
      ["LORE"] = "'Con la ayuda de los Kámbrada, ganamos un punto de apoyo en las laderas de Bundushathûr. El gran puesto de guardia de Ashmargathâl había caído en manos de los Orcos, pero ya no. Lamentablemente, la torre de vigilancia más allá será más difícil de conquistar.'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "69.52N"; 
          ["LONG"] = "133.25W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Atrad-zarakh, la Aguja de Protección"; 
      ["PROGRESS"] = "Infórmate sobre Atrad-zarakh"; 
      ["LORE"] = "'Fue en Atrad-zarakh, la torre de vigilancia, donde las grandes campanas de Khazad-dûm resonaban a lo largo de Azanulbizar. Una vez sonaron en tiempos de celebración, se convirtieron en un faro de advertencia en los últimos días de Moria. Lamentablemente, ahora la torre está tomada.'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "69.36N"; 
          ["LONG"] = "134.68W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Tharkh Baraz"; 
      ["PROGRESS"] = "Infórmate sobre Tharkh Baraz"; 
      ["LORE"] = "'De todos los pasos entre los picos de Khazad-dûm, el más transitado en tiempos antiguos fue Tharkh Baraz, el Paso del Cuerno Rojo. Espero que en los años venideros pueda ser seguro caminar por él nuevamente.'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "69.37N"; 
          ["LONG"] = "137.47W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Anlakh-zeleg"; 
      ["PROGRESS"] = "Infórmate sobre Anlakh-zeleg"; 
      ["LORE"] = "'Incluso la corrupción de los Orcos no pudo empañar la belleza de Anlakh-zeleg, la Escalera de Dimrill. Al pie de Tharkh Baraz, sus cascadas brillaban al sol mientras caían en Kheled-zâram.'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "69.87N"; 
          ["LONG"] = "136.15W"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "Tharkh Zigil"; 
      ["PROGRESS"] = "Infórmate sobre Tharkh Zigil"; 
      ["LORE"] = "'En verdad, se sabe poco de Tharkh Zigil. Una vez un paso tallado en las laderas de Zirakzigil, cayó en desuso incluso antes de la caída de Moria. Quizás alguna vez estuvo destinado a conducir a la Torre de Durin, pero no he descubierto su verdadero propósito.'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "66.81N"; 
          ["LONG"] = "137.47W"; 
        }; 
      }; 
      };
      [12] = {
      ["NAME"] = "Zirakazhâr"; 
      ["PROGRESS"] = "Infórmate sobre Zirakazhâr"; 
      ["LORE"] = "'Zirakazhâr, antaño armurería y puesto de vigilancia al sur de Khazad-dûm, fue conquistado por los Orcos poco después de la caída de Moria. ¡Debemos recuperarlo si queremos tener alguna oportunidad de vencer a las fuerzas de Azog!'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "66.22N"; 
          ["LONG"] = "136.70W"; 
        }; 
      }; 
      };
      [13] = {
      ["NAME"] = "Kheled-zâram, el Lago Espejo"; 
      ["PROGRESS"] = "Infórmate sobre Kheled-zâram"; 
      ["LORE"] = "'¡Ah, el Lago Espejo! Debe de haber algún hechizo sobre él, pues siempre refleja el cielo nocturno. Fue en las aguas de Kheled-zâram donde Durin el Inmortal vislumbró por primera vez una corona de estrellas sobre su cabeza, y con su sabiduría, excavó las primeras salas de Khazad-dûm.'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "67.25N"; 
          ["LONG"] = "134.62W"; 
        }; 
      }; 
      };
      [14] = {
      ["NAME"] = "Durinul’aban"; 
      ["PROGRESS"] = "Infórmate sobre Durinul’aban"; 
      ["LORE"] = "'Han pasado muchos años desde que algún enano ha mirado Durin'abal. La Piedra de Durin se colocó en conmemoración del lugar donde Durin el Inmortal se encontraba cuando por primera vez contempló Kheled-zâram. Me brinda un gran consuelo verla, incluso en medio de la guerra.'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "66.50N"; 
          ["LONG"] = "134.98W"; 
        }; 
      }; 
      };
      [15] = {
      ["NAME"] = "Nud-mekhem, la Puerta Este"; 
      ["PROGRESS"] = "Infórmate sobre Nud-mekhem"; 
      ["LORE"] = "'Después de tantos años, la fachada de Nud-mekhem, la gran puerta este, ha resistido caer en ruina completa a pesar de los esfuerzos de los Orcos. Las puertas están desfiguradas con garabatos orcos, pero como con todas las obras de los Orcos y su especie, ¡no puede perdurar!'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "67.60N"; 
          ["LONG"] = "137.52W"; 
        }; 
      }; 
      };
  };
