  -- Sangre de Azog / El reino de Azog
  [1879415681] = {
      [1] = {
      ["NAME"] = "Kamaz-kala"; 
      ["PROGRESS"] = "Infórmate sobre Kamaz-kala"; 
      ["LORE"] = "'Contaminando las aguas de Kibil-nâla con su suciedad, los Orcos habían construido un fortín rudimentario a lo largo de la antigua gran vía, bloqueando nuestro camino más seguro hacia la Puerta Este.'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "45.67N"; 
          ["LONG"] = "123.93W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Gadh Ujáf"; 
      ["PROGRESS"] = "Infórmate sobre Gadh Ujáf"; 
      ["LORE"] = "'En las colinas bajas de Zirakzigil, encontré una gran guarida de huargos. Antes de que Komog, el hijo más joven de Azog, fuera asesinado en Gundabad, sus huargos habían reclamado la vida de innumerables enanos. ¡Al fin, la venganza sería nuestra!'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "65.22N"; 
          ["LONG"] = "135.42W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Dursh Hûl"; 
      ["PROGRESS"] = "Infórmate sobre Dursh Hûl"; 
      ["LORE"] = "'Al norte de Khur Azan, encontramos el viejo puente destruido. En su lugar, los Orcos habían erigido un pequeño paso para vigilar el paso hacia Shathûr.'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "65.87N"; 
          ["LONG"] = "132.67W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Târ-kútoz"; 
      ["PROGRESS"] = "Infórmate sobre Târ-kútoz"; 
      ["LORE"] = "'A la sombra de Atrad-zarakh, en las laderas de Shathûr, los Orcos habían construido un extenso puesto de vigilancia. Entre sus toscos aparejos se encontraban innumerables murciélagos, criaturas que Azog y sus hijos habían favorecido durante mucho tiempo para usarlas como espías en Azanulbizar.'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "69.80N"; 
          ["LONG"] = "134.65W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Rung-shakam"; 
      ["PROGRESS"] = "Infórmate sobre Rung-shakam"; 
      ["LORE"] = "'Muy por encima de la Puerta Este, en las laderas de Zirakzigil, los Orcos acamparon con trolls provenientes de Moria. Desde esas alturas vertiginosas, los trolls lanzaban innumerables piedras hacia el valle, matando tanto a Orcos como a enanos.'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "68.12N"; 
          ["LONG"] = "137.67W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Zaghúth"; 
      ["PROGRESS"] = "Infórmate sobre Zaghúth"; 
      ["LORE"] = "'Cuando finalmente llegamos a Azanulbizar, encontramos el paso a través de Baraz bloqueado por un gran campamento de orcos. No habría refuerzos desde el norte, al menos, ninguno que nos encontrara como amigos y aliados.'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "70.88N"; 
          ["LONG"] = "137.32W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Muru Azog"; 
      ["PROGRESS"] = "Infórmate sobre Muru Azog"; 
      ["LORE"] = "'Antes de las puertas de Moria, Azog y sus Orcos construyeron un gran baluarte. En las sombras de sus torres de vigilancia, los cráneos de innumerables enanos fueron colocados en estacas en burla de Thráin.'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "67.52N"; 
          ["LONG"] = "136.58W"; 
        }; 
      }; 
      };
