  -- Gundabad / La Cuna de Durin
  [1879422591] = {
      [1] = {
      ["NAME"] = "Zâram-mekhem"; 
      ["PROGRESS"] = "Explora Zâram-mekhem"; 
      ["LORE"] = "Portando terribles advertencias en khuzdul, Zâram-mekhem, la puerta del lago, se alza en forma de dos grandes columnas de piedra inscritas con runas donde Hendidura Profunda se encuentra con Lagosombrío. Una vez poseedora de un poderoso encantamiento que prohibía a todos, excepto a los Enanos de la Tierra Media, entrar en las sagradas cavernas del Monte Gundabad, fue superada en los últimos días por los Angmarim que empuñaban un artefacto creado hace mucho tiempo por el Rey Brujo de Angmar: Máltagar, el Infame Burin."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "50.43S"; 
          ["LONG"] = "120.47W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Durthuzâram, el Lago Oscuro"; 
      ["PROGRESS"] = "Explora Durthuzâram, el Lago Oscuro"; 
      ["LORE"] = "Durthuzâram, el Lago Oscuro, es una de las maravillas naturales del Monte Gundabad y, de hecho, de la Tierra Media. Profundo, claro y tan tranquilo como un mar en calma, fue Durthuzâram, Lagosombrío, el que dio su nombre a las sagradas cavernas del Monte Gundabad."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "46.28S"; 
          ["LONG"] = "120.85W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Nido de los Vigilantes"; 
      ["PROGRESS"] = "Explora el Nido de los Vigilantes"; 
      ["LORE"] = "Una vez un gran mirador desde el cual los Barbiluengos podían contemplar casi la totalidad de Durthuzâram, el Nido de los Vigilantes se ha convertido en un campamento improvisado para los Gabil'akkâ mientras trabajan para repeler a sus enemigos de las sagradas cavernas de Lagosombrío."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "47.72S"; 
          ["LONG"] = "121.91W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Lugun-nâla"; 
      ["PROGRESS"] = "Explora Lugun-nâla"; 
      ["LORE"] = "Lugun-nâla, el camino sagrado, es un antiguo puente construido con el basalto de Lagosombrío. Arqueándose sobre Durthuzâram, Lugun-nâla conduce quizás al sitio más sagrado de todo el Monte Gundabad: Abkân'aban, la Piedra del Despertar."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "45.40S"; 
          ["LONG"] = "122.12W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Abkân'aban, la Piedra del Despertar"; 
      ["PROGRESS"] = "Explora Abkân'aban, la Piedra del Despertar"; 
      ["LORE"] = "Según la leyenda, fue en Abkân'aban, la Piedra del Despertar, donde Durin el Inmortal despertó por primera vez en las profundidades del Monte Gundabad. Sobre su cuna de tierra, se dice que el propio Durin forjó un yunque de piedra negra, Narag-dehar, y una fragua de ladrillo blanco, Labam-khebab. Sin embargo, tras la Rebelión de los Martillos Grises, se decretó que la fragua debía permanecer apagada hasta el regreso profetizado de Durin el Último, y así fue extinguida, sirviendo desde entonces únicamente como un lugar de ceremonia para los Barbiluengos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "44.99S"; 
          ["LONG"] = "120.87W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Burmumekhem"; 
      ["PROGRESS"] = "Explora Burmumekhem"; 
      ["LORE"] = "Portando terribles advertencias en khuzdul, Burmumekhem, la puerta de la fosa, se alza en forma de dos grandes columnas de piedra inscritas con runas donde Pasohendido se encuentra con Lagosombrío. Una vez poseedora de un poderoso encantamiento que prohibía a todos, excepto a los Enanos de la Tierra Media, entrar en las sagradas cavernas del Monte Gundabad, también fue superada por los Angmarim de la Corona de Hierro."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "42.63S"; 
          ["LONG"] = "121.90W"; 
        }; 
      }; 
      };
  };
