  -- Gundabad / Invasores en el Lago Oscuro
  [1879422593] = {
      [1] = {
      ["NAME"] = "Drúkala"; 
      ["PROGRESS"] = "Explora Drúkala"; 
      ["LORE"] = "Durante mucho tiempo conocida por los Orcos como Skaizagâf, o la cueva maldita, Lagosombrío les estaba prohibida a todos hasta que los Angmarim superaron las runas de protección con la ayuda de Máltagar, el Infame Buril. Aunque los Orcos ahora pueden entrar en Lagosombrío sin temor a sucumbir al encantamiento de las runas, muchos eligen no permanecer mucho tiempo, pues los ecos en la oscuridad parecen tener vida propia. Los pocos Orcos que se atreven a explorar la caverna sagrada han establecido su campamento en Drúkala, no muy lejos de las primeras piedras del camino donde Deepscrave se encuentra con Lagosombrío."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "50.20S"; 
          ["LONG"] = "121.29W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Ormgren"; 
      ["PROGRESS"] = "Explora Ormgren"; 
      ["LORE"] = "Aunque casi no queda evidencia de sus depósitos antaño ricos, Ormgren fue una de las primeras vetas exploradas por Durin el Inmortal tras despertar en el Monte Gundabad. Durante muchos años después de que Lagosombrío fuera sellado, los gusanos luminosos fueron los únicos habitantes de los antiguos túneles, pero desde la llegada de los Angmarim, muchos de los suyos se han vuelto inusualmente agresivos y territoriales. Sin embargo, otros simplemente se han retirado más profundamente en Ormgren, proyectando su luz pálida en cámaras olvidadas del Monte Gundabad."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "44.65N"; 
          ["LONG"] = "11.60E"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Glittengrof"; 
      ["PROGRESS"] = "Explora Glittengrof"; 
      ["LORE"] = "Se rumorea que es la caverna donde Durin el Inmortal descubrió los primeros cristales que usaría para iluminar los salones del Monte Gundabad, Glittengrof es ahora el hogar de una camada invasora de arañas cuyas telarañas amenazan con profanar todo Lagosombrío."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "56.37N"; 
          ["LONG"] = "25.50E"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Skelstrand"; 
      ["PROGRESS"] = "Explora Skelstrand"; 
      ["LORE"] = "A lo largo de la orilla occidental del Durthuzâram se encuentra Skelstrand, un tramo de bajos rocosos y pozas de marea habitado por los ukhrâsh parecidos a cangrejos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "46.97S"; 
          ["LONG"] = "121.73W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Mîn Lorg"; 
      ["PROGRESS"] = "Explora Mîn Lorg"; 
      ["LORE"] = "Decididos a desvelar los secretos de Lagosombrío, los Angmarim han descubierto sin querer Mîn Lorg, un pasaje antiguo y aparentemente intacto que conduce hacia las profundidades más recónditas del Monte Gundabad."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "45.65S"; 
          ["LONG"] = "125.73W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Lochan Dúv"; 
      ["PROGRESS"] = "Explora Lochan Dúv"; 
      ["LORE"] = "Establecido poco después de que los Angmarim franquearan las runas de protección de Lagosombrío, Lochan Dúv es el bastión más profundo de la Corona de Hierro dentro de las sagradas cavernas del Monte Gundabad. Aunque muchos Angmarim han viajado desde entonces a las alturas de la Montaña-hogar, algunos han decidido quedarse, con la esperanza de descubrir secretos y reliquias de los Días Antiguos que aún puedan estar ocultos en Lagosombrío."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "45.77S"; 
          ["LONG"] = "123.69W"; 
        }; 
      }; 
      };
  };
