      [3] = {
      ["NAME"] = "Gabil-memâg"; 
      ["PROGRESS"] = "Explora Gabil-memâg"; 
      ["LORE"] = "El agua del adyacente Lagosombrío se vierte sobre los antiguos molinos de agua en Gabil-memâg. Durante los días más brillantes, los molinos de agua alimentaban los ascensores de Hendidura Profunda. Ahora sirven de poco, girando sin cesar a lo largo de los siglos."; 
      ["POINTS"] = {
