  -- la Ciénaga de los Cisnes y Cardolan / Peligros de la Ciénaga de los Cisnes
  [1879450861] = {
      [1] = {
      ["NAME"] = "Piedras Aullantes"; 
      ["PROGRESS"] = "Encuentra las Piedras Aullantes"; 
      ["LORE"] = "Los lobos han vivido en las Piedras Aullantes desde que el pueblo de Musgovilla tiene memoria, pero por lo general no se acercaban demasiado a la empalizada exterior. Eso ha cambiado en las últimas noches: los guardias de la ciudad han visto ojos lupinos observándolos desde la oscuridad con inquietante frecuencia."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "61.31S"; 
          ["LONG"] = "33.38W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Radlaw"; 
      ["PROGRESS"] = "Encuentra Radlaw"; 
      ["LORE"] = "Nadie sabe con certeza cuándo llegaron los rufianes a la Ciénaga de los Cisnes, pero para los Fuertes, el asentamiento proscrito de Radlaw pareció surgir de la noche a la mañana. Ahora no es seguro para la mayoría recorrer los Valles de los Fuertes sin cuidado, pues los rufianes de Radlaw siempre están atentos para robar monedas u objetos valiosos a los incautos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "59.73S"; 
          ["LONG"] = "29.29W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Colmillar"; 
      ["PROGRESS"] = "Encuentra Colmillar"; 
      ["LORE"] = "El Aguaestancada está lleno de peligros, pero pocos lugares del pantano son tan amenazadores como Colmillar, donde los avanc construyen sus nidos. Solo los dunlendinos de la cercana Lhan Garan se aventuran cómodamente en esta zona de cría, y aun así sus mejores exploradores intentan no acercarse demasiado sin necesidad urgente."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "54.73S"; 
          ["LONG"] = "30.46W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Cuencasangre"; 
      ["PROGRESS"] = "Encuentra la Cuencasangre"; 
      ["LORE"] = "Montones de huesos desechados y las carcasas de presas muertas hace tiempo marcan las guaridas de los huargos en la Cuencasangre, un lugar tan peligroso que incluso los más habilidosos guerreros dunlendinos de Lhan Garan intentan evitarlo salvo en extrema necesidad. Pero a veces surge tal necesidad: el entrenamiento de nuevos exploradores exige ponerlos a prueba frente a circunstancias peligrosas y enemigos amenazantes, y ¿qué prueba mejor que los huargos que acechan la Cuencasangre?"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "56.83S"; 
          ["LONG"] = "21.63W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Hondonada del Terrón"; 
      ["PROGRESS"] = "Encuentra Hondonada del Terrón"; 
      ["LORE"] = "Las arañas tejedoras que habitan Hondonada del Terrón no toleran ninguna intrusión de los Fuertes que viven cerca, pero los habitantes de Glyn Helyg y Clegur aprendieron hace mucho a no internarse bajo los árboles cubiertos de telarañas, y la gente de Lintrev no suele alejarse de sus propias granjas."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "65.49S"; 
          ["LONG"] = "26.09W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Sharmokal"; 
      ["PROGRESS"] = "Encuentra Sharmokal"; 
      ["LORE"] = "Una partida de incursión uruk ha establecido un campamento no muy lejos del Viejo Camino del Sur, donde se alzan los restos de una torre élfica. ¿Para qué se construyó esta torre en una Edad pasada? Los uruks lo ignoran, y los Elfos que podrían recordarlo prefieren no decirlo. Ahora el lugar es Sharmokal, y no es seguro que los viajeros se acerquen demasiado."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "60.39S"; 
          ["LONG"] = "22.32W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Caras Gelebren"; 
      ["PROGRESS"] = "Encuentra Caras Gelebren"; 
      ["LORE"] = "El gran herrero élfico Celebrimbor construyó la ciudad donde forjaría su legado en la confluencia de los ríos Sirannon y Glanduin. Caras Gelebren, el Bastión de Plata, fue un lugar de belleza y aprendizaje durante gran parte de la Segunda Edad, pero la dicha no perduró. Bajo un bello disfraz, el mal llegó a Caras Gelebren, y Celebrimbor fue engañado. Atrapado por su orgullo y su ansia de conocimiento secreto, el herrero élfico estuvo a punto de quebrar el mundo.\n\nCuando Sauron trajo la guerra a Eregion tras el desatino de Celebrimbor, la ciudadela fue destruida y todo recuerdo de sus días pacíficos quedó olvidado. Aun habría triunfos en los años venideros, pero en el fondo los Elfos recuerdan la vergüenza sobre la que se asentó todo, y lloran."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "53.62S"; 
          ["LONG"] = "20.92W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Tham Lasgol"; 
      ["PROGRESS"] = "Encuentra Tham Lasgol"; 
      ["LORE"] = "Los árboles han reclamado Tham Lasgol. Los Elfos no habrían lamentado tal destino, pero algo ha atraído a los trolls silvanos a este lugar antaño hermoso, y ahora se ha convertido en un sitio peligroso."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "49.30S"; 
          ["LONG"] = "23.79W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Gwâl Cruban"; 
      ["PROGRESS"] = "Encuentra Gwâl Cruban"; 
      ["LORE"] = "Los edificios que una vez se alzaron aquí están ahora cubiertos por juncos, y solo son visitados por tortugas."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "51.95S"; 
          ["LONG"] = "26.14W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Tham Celechir"; 
      ["PROGRESS"] = "Encuentra Tham Celechir"; 
      ["LORE"] = "Tham Celechir, el Salón del Río Veloz, fue uno de los últimos lugares en resistir a los ejércitos de Sauron cuando llevó la guerra a Eregion en la Segunda Edad. Muchos Elfos murieron dentro y fuera de sus muros, y las huellas de su última resistencia aún pueden verse entre los restos que pueblan esta antigua y orgullosa ruina."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "45.56S"; 
          ["LONG"] = "19.45W"; 
        }; 
      }; 
      };
  };
  -- la Ciénaga de los Cisnes y Cardolan / Habitantes de la Antigua Ciénaga de los Cisnes
  [1879450862] = {
      [1] = {
      ["NAME"] = "Piedra angular"; 
      ["PROGRESS"] = "Descubre una vieja piedra angular"; 
      ["LORE"] = "Estas viejas piedras pueden haber sido testigo del ataque de Sauron, pero aún se aferran a recuerdos más felices. Bodas, centenarios personales y ceremonias de todo tipo tuvieron lugar en este pabellón antaño elegante."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "53.11S"; 
          ["LONG"] = "20.83W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Colgante curioso"; 
      ["PROGRESS"] = "Descubre un colgante curioso"; 
      ["LORE"] = "'Amor mío, si estás leyendo esto, entonces has tenido éxito en mi pequeña búsqueda del tesoro y reclamado el premio. Mandé hacer este collar a tu gusto. Espero con ansias verte llevarlo.'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "55.86S"; 
          ["LONG"] = "19.32W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Piedra grabada"; 
      ["PROGRESS"] = "Descubre una piedra grabada"; 
      ["LORE"] = "Hay inscripciones en la piedra para marcar cada vez que esta estructura fue renovada. Los números más antiguos son imposibles de descifrar, y los más recientes se remontan a una época que muy pocos recuerdan."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "59.08S"; 
          ["LONG"] = "21.04W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Caña de pescar muy usada"; 
      ["PROGRESS"] = "Descubre una caña de pescar muy usada"; 
      ["LORE"] = "El anzuelo se hundió en el agua con un chapoteo suave. El hobbit solitario sumergió los dedos de los pies en el agua, considerando que su temperatura era 'refrescantemente fresca' en lugar de 'horriblemente fría'.\n\n'Podría acostumbrarme a esto', dijo a nadie en particular.\n\nY así lo hizo, pescando junto al molino cada jueves por la tarde, casi todas las semanas durante el resto de su vida. El único cambio en su rutina fue la incorporación de algo de compañía a medida que pasaban los años."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "62.49S"; 
          ["LONG"] = "26.21W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Alijo de viejas notas"; 
      ["PROGRESS"] = "Descubre un alijo de viejas notas"; 
      ["LORE"] = "Recuperas notas de eruditos y conservacionistas de antaño. Les complacería saber que las tortugas de Aguaestancada están prosperando. Quizás, demasiado."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "51.84S"; 
          ["LONG"] = "25.98W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Colección de poesía"; 
      ["PROGRESS"] = "Descubre una colección de poesía"; 
      ["LORE"] = "Encuentras un alijo de papel improbablemente bien conservado, en el que están escritos varios borradores de poemas en caligrafía fluida.\nUna página contiene las siguientes frases, cada una tachada con el trazo de una pluma enfadada:\nBajo los aleros del acebo rojo vino\nacebo carmesí\nacebo tonalidad del ocaso\nacebo escarlata\nacebo rojo rubí\nacebo color acebo\n\nY finalmente, 'Bajo los aleros del acebo'\nNo se puede encontrar ninguna atribución o reclamo de autoría."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "49.03S"; 
          ["LONG"] = "23.71W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Daga oxidada"; 
      ["PROGRESS"] = "Descubre una daga oxidada"; 
      ["LORE"] = "El ladrón pasaba la moneda entre sus dedos, un pequeño truco que aprendió de uno de sus muchos mentores.\n'Es audaz de tu parte exhibir bienes mal obtenidos tan abiertamente', dijo una voz detrás del ladrón.\nSin lograr ocultar su sorpresa, el ladrón giró sobre sus talones. Vio a una mujer vestida con ropas que parecían haber estado empapándose en Aguaestancada durante días. ¿Cuánto tiempo llevaba siguiéndolo?\n'¿Oh, esto?' El ladrón sostuvo el oro en alto y puso una sonrisa inocente.\n'Esto fue solo un poco de buena suerte, nada más. No hay ladrones aquí, a menos que pretendas quitarme esto'. Su mano libre se deslizó hacia la daga a su costado.\n'He compensado a tu víctima con monedas de mi propia bolsa', dijo ella, ignorando su mentira.\n'No pretendo quitarte esa moneda. No te conozco, ni tus necesidades. Pero hay trabajo honrado en Musgovilla. Ataca a quienes viajan por este camino bajo tu propio riesgo'.\nEl ladrón se burló.\n'¡No voy a dejarme mandonear por alguien como tú!'\nEl ladrón fue a desenfundar su daga, pero la Montaraz, como un día llegaría a conocerla, estuvo sobre él en un instante. Paró su débil puñalada y lo desarmó, enviando la hoja repiqueteando al suelo. El ladrón sintió el mordisco del acero frío contra su cuello, y se congeló.\n'La única razón por la que te doy esta oportunidad es que no dañaste a la mujer de quien robaste'.\nRetiró su hoja, y las manos del ladrón se dispararon a su cuello, buscando sangre. No encontró ninguna. Para cuando se recuperó, la espalda de la Montaraz estaba hacia él. Se estaba alejando.\nMiró hacia donde había caído su daga, luego a la Montaraz, y decidió hacer lo mismo."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "58.65S"; 
          ["LONG"] = "34.54W"; 
        }; 
      }; 
      };
  };
