      [11] = {
      ["NAME"] = "Granja de Hove"; 
      ["PROGRESS"] = "Explora la Granja Hove"; 
      ["LORE"] = "Aunque no tan establecida como sus vecinos en la Granja Scurloc, la familia Hove ha mantenido una vida precaria en su propia pequeña granja. Sin embargo, en días recientes, la familia ha sido expulsada por asaltantes trasgos del norte."; 
      ["POINTS"] = {
