  -- Volver a Carn Dûm / Gwathrenost, la Ciudadela del Rey Brujo -- Sombras del Pasado
  [1879458848] = {
      [1] = {
      ["NAME"] = "Gwathrenost"; 
      ["PROGRESS"] = "Encuentra Gwathrenost"; 
      ["LORE"] = "Elevándose por encima de Carn Dûm, Gwathrenost fue erigido hace mucho tiempo durante el reinado del Rey Brujo de Angmar. Fue desde esta fortaleza casi inexpugnable que Angmar libró su larga guerra contra Arnor, devastando los reinos de Arthedain, Cardolan y Rhudaur. Después de que la batalla de Fornost se volviera en contra del Rey Brujo de Angmar, huyó hacia Gwathrenost, pero fue alcanzado por las fuerzas de Eärnur y Glorfindel antes de poder regresar a Carn Dûm. Con Angmar prácticamente destruido, quedó abandonado durante muchos años hasta que el Falso Rey y Senescal de Angmar, Mordirith, provocó el primer renacimiento de Angmar y convocó a aquellos que aún eran leales a la corona de hierro del Rey Brujo de Angmar a su servicio en Carn Dûm."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "72.84N"; 
          ["LONG"] = "31.19W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Armamentos de los Caídos"; 
      ["PROGRESS"] = "Encuentra los armamentos de los caídos"; 
      ["LORE"] = "Aunque fueron asesinados durante la segunda caída de Angmar, Mura, una hechicera angmarim, y Rodakhan, una mujer del clan de los Trev Duvardain, no han sido olvidados entre las filas de la Corona de Hierro. Tras el regreso de la Corona de Hierro a Carn Dûm, sus viejas armas, un bastón y una alabarda, fueron recuperadas y montadas ceremonialmente en las paredes de Gwathrenost. Quienes se acerquen a ellas deben tener cuidado de no molestarlas, para no incurrir en la ira de la Corona de Hierro."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "73.50N"; 
          ["LONG"] = "49.65E"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Tomo Olvidado"; 
      ["PROGRESS"] = "Encuentra un tomo olvidado"; 
      ["LORE"] = "De hecho, es raro encontrar este volumen completo en tan buen estado. Muchas de sus copias encontradas en toda la Tierra Media carecían misteriosamente de páginas, pero la Corona de Hierro ha hecho bien en reunirlas todas para las que se conservan en Gwathrenost."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "73.35N"; 
          ["LONG"] = "49.64E"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Tirith Gúlaran"; 
      ["PROGRESS"] = "Encuentra Tirith Gúlaran"; 
      ["LORE"] = "Desde Tirith Gúlaran, el Rey Brujo de Angmar, y más tarde, Mordirith, el Falso Rey y Senescal de Angmar, podían vigilar todo Carn Dûm y sus tierras circundantes."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "73.53N"; 
          ["LONG"] = "31.21W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Inscripción de Golodir"; 
      ["PROGRESS"] = "Encuentra la inscripción de Golodir"; 
      ["LORE"] = "Fue en esta alta cámara donde Golodir fue encarcelado en Gwathrenost, solo concediéndole las libertades más breves y crueles los días en que se le obligaba a mirar el palantír por orden de Mordirith. A través de todo su sufrimiento, su amor por su hija, Lorniel, nunca flaqueó y soñaba con el día en que finalmente se reunirían. Por desgracia, Mordirith conocía bien las esperanzas de Golodir y su fe en aquellos que había dejado atrás en Gath Forthnír..."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "73.65N"; 
          ["LONG"] = "49.87E"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Tham Mornarcham"; 
      ["PROGRESS"] = "Encuentra Tham Mornarcham"; 
      ["LORE"] = "Hace mucho tiempo, desde Tham Mornarcham, el Rey Brujo de Angmar gobernaba su reino. Después de que se viera obligado a abandonar Angmar, esta sala, como todo Carn Dûm, permaneció vacía durante muchos años. Sin embargo, cuando Mordirith buscó traer de nuevo la vida a Angmar, se convirtió en la sede del Falso Rey y Senescal de Angmar y en el gran salón de la Corona de Hierro. Fue aquí donde el Montaraz Golodir se enfrentó a Mordirith en batalla, lo hirió con la espada Dúnachar y lo obligó a retirarse."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "74.01N"; 
          ["LONG"] = "49.65E"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Pedestal del Palantír Perdido"; 
      ["PROGRESS"] = "Encuentra el pedestal del palantír perdido"; 
      ["LORE"] = "Guardado por el Rey Brujo de Angmar y, más tarde, por el Falso Rey y Senescal de Angmar, Mordirith, uno de los palantíri descansaba sobre este pedestal hasta que la piedra de visión fue robada de Gwathrenost."; 
      ["POINTS"] = {
