      [4] = {
      ["NAME"] = "Sudor purulento"; 
      ["PROGRESS"] = "Encuentra Dulceinfector"; 
      ["LORE"] = "El líquido nocivo de Dulceinfector, derivado de hongos, es mortal al contacto físico. Esta concentración se ha fermentado con otras soluciones alquímicas durante largos períodos de tiempo para crear resultados alternativos a partir de sus diversas propiedades."; 
      ["POINTS"] = {
