  -- Gondor del Rey Oriental / Rezagados y nuevas amenazas en Lossarnach
  [1879464436] = {
      [1] = {
      ["NAME"] = "Ost Norhír"; 
      ["PROGRESS"] = "Encuentra Ost Norhír"; 
      ["LORE"] = "La ruina de Ost Norhír se encuentra en la cima de la colina que domina el río al sur del Harlond, pero ahora solo está habitada por la fauna. Cuando la gente se fue a reconstruir sus vidas después de la guerra, las bestias regresaron para hacer sus propios hogares."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "75.65S"; 
          ["LONG"] = "21.20W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Valle de Galdir"; 
      ["PROGRESS"] = "Encuentra el valle del Galdir"; 
      ["LORE"] = "El campamento que una vez se levantó en el valle del Galdir ahora está quemado e irreconocible. Los huargos merodean entre las estructuras de madera chamuscadas, y sus aullidos resuenan en las brisas que barren el río."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "77.14S"; 
          ["LONG"] = "21.43W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Aegollant"; 
      ["PROGRESS"] = "Encuentra Aegollant"; 
      ["LORE"] = "Las tiendas de los Haradrim permanecen en Aegollant, a pesar de la derrota de la Serpiente Negra en la Batalla de los Campos del Pelennor, pero ahora albergan principalmente a bandidos y otros que albergan la villanía en sus corazones."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "78.64S"; 
          ["LONG"] = "23.07W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Delta del Erui"; 
      ["PROGRESS"] = "Encuentra el delta del Erui"; 
      ["LORE"] = "El río Erui desemboca en el Anduin aquí, y los avancs merodean entre las orillas llenas de juncos, amenazando a los viajeros desprevenidos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "80.53S"; 
          ["LONG"] = "24.19W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Taustrok"; 
      ["PROGRESS"] = "Encuentra Taustrok"; 
      ["LORE"] = "Los restos de la hueste de Morgul, dispersos tras la Batalla de los Campos del Pelennor, han comenzado a reunirse en números alarmantes en un campamento que llaman 'Taustrok'. Dentro de cuevas húmedas se entierran en la ladera de la montaña, amenazando con desbordarse y convertirse en una amenaza para el cercano pueblo del Harlond."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "70.72S"; 
          ["LONG"] = "22.65W"; 
        }; 
      }; 
      };
  };
  -- Gondor del Rey Oriental / Reconquista de Lossarnach
  [1879464437] = {
      [1] = {
      ["NAME"] = "Arnach"; 
      ["PROGRESS"] = "Encuentra a Arnach"; 
      ["LORE"] = "El Señor Forlong, gobernante de Lossarnach, tenía un salón en el pueblo de Arnach hasta que cabalgó a Minas Tirith durante la Guerra del Anillo. Pereció en los combates en el Pelennor y ahora su salón está vacío, mientras la gente de Arnach hace lo mejor que puede para seguir adelante sin su querido señor. Arnach sigue siendo un asentamiento bullicioso para comerciantes y artesanos, pero el recuerdo de los ataques de los Haradrim durante los meses anteriores sigue siendo doloroso."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "76.55S"; 
          ["LONG"] = "24.40W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Imloth Melui"; 
      ["PROGRESS"] = "Encuentra a Imloth Melui"; 
      ["LORE"] = "Imloth Melui, el Valle de las Dulces Flores, es el hogar de la Dama Vanyalos, hermana del Senescal Denethor y esposa de Forlong, Señor de Lossarnach. Ambos hombres perecieron durante la guerra, uno dentro de los muros de la Ciudad Blanca y el otro fuera, pero las heridas de su partida pesan especialmente sobre Vanyalos, ya que soñó que sucedería y siente la carga de no haber podido evitarlo.\n\nImloth Melui proporciona muchos de los sanadores que trabajan en las Casas de Curación en Minas Tirith, incluida la mujer Ioreth, que sabe un poco sobre una impresionante variedad de cosas y una cantidad impresionante sobre muy pocas cosas."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "73.20S"; 
          ["LONG"] = "24.79W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Nan Harlond"; 
      ["PROGRESS"] = "Encuentra a Nan Harlond"; 
      ["LORE"] = "Los campos y granjas de Nan Harlond se encuentran a ambos lados del camino, debajo del puerto sur de Gondor, ya no amenazados por los ejércitos de Sauron, pero aún en peligro por enemigos ocasionales dejados atrás por sus aliados derrotados. La belleza natural de Lossarnach lucha por emerger tras la Guerra del Anillo, y las flores aquí son un testimonio de su resiliencia."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "74.29S"; 
          ["LONG"] = "21.04W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Rammas Echor"; 
      ["PROGRESS"] = "Encuentra el Rammas Echor"; 
      ["LORE"] = "La gran muralla que es el Rammas Echor rodea Minas Tirith y los Campos del Pelennor. Durante la guerra, la muralla fue atravesada en varios lugares y las fuerzas de Sauron se precipitaron para sitiar la Ciudad Blanca. Ahora, enanos y trabajadores gondorianos trabajan para reparar los daños y reforzar las defensas una vez más, aunque todos esperan que el Rammas no vuelva a ser necesario durante muchos años."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "72.14S"; 
          ["LONG"] = "18.75W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "El Harlond"; 
      ["PROGRESS"] = "Encuentra el Harlond"; 
      ["LORE"] = "El Harlond fue ocupado por los Orcos de Mordor en los días previos a la Batalla de los Campos del Pelennor, durante los cuales quemaron tantos barcos gondorianos como pudieron. Cuando los barcos corsarios con velas negras subieron por el río desde el sur, los Orcos se sorprendieron al ver que se izaba la bandera del Rey, revelando que los barcos estaban comandados por Aragorn y los aliados de Gondor. Su llegada al campo de batalla resultó fundamental para la defensa de Minas Tirith y la derrota de las fuerzas de Sauron.\n\nHoy en día, la gente de Gondor y los enanos de las Montañas Blancas trabajan para reparar y reconstruir el puerto del sur, con la esperanza de que el comercio y las mercancías vuelvan a fluir libremente por el río hacia puertos cercanos y lejanos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "72.72S"; 
          ["LONG"] = "20.01W"; 
        }; 
      }; 
      };
  };
  -- Gondor del Rey Oriental / Reconquista del Alto Lebennin
  [1879464470] = {
      [1] = {
      ["NAME"] = "Minlos"; 
      ["PROGRESS"] = "Encuentra Minlos"; 
      ["LORE"] = "La Almenara de Minlos es la más cercana a Minas Tirith, y fue tomada por los asaltantes Haradrim durante la guerra mientras intentaban atacar el pueblo de Arnach. Ahora la Almenara ha sido apagada y los habitantes de las granjas cercanas esperan que permanezca apagada durante muchos años, una señal de que el peligro ha pasado."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "76.83S"; 
          ["LONG"] = "25.96W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Halach"; 
      ["PROGRESS"] = "Encuentra Halach"; 
      ["LORE"] = "El pequeño puerto de Halach fue abandonado a los Haradrim durante la guerra, pero la derrota de Sauron ha permitido que los habitantes regresen y comiencen el largo proceso de reconstrucción."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "82.26S"; 
          ["LONG"] = "26.21W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Glaniath"; 
      ["PROGRESS"] = "Encuentra Glaniath"; 
      ["LORE"] = "La pequeña comunidad agrícola de Glaniath fue amenazada por los asaltantes Haradrim durante la guerra, y ahora la gente intenta reconstruir sus vidas después de los acontecimientos. Algunos habitantes creen que la cautividad de Sirgon a manos de los Haradrim lo ha hecho incapaz de gobernar y que su hijo Faltharan debería convertirse en el Señor de Lebennin en su lugar."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "80.62S"; 
          ["LONG"] = "29.70W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Tumladen"; 
      ["PROGRESS"] = "Encuentra Tumladen"; 
      ["LORE"] = "Tumladen es el gran refugio de Gondor, similar al Abismo de Helm en el reino de Rohan. Durante la guerra, muchas personas se refugiaron en Tumladen, incluida una de las obstinadas hermanas del Senescal Denethor, la obstinada Dama Terenis. Para alivio del Capitán Imladir, responsable de la defensa de Tumladen, la Dama Terenis ha regresado a Minas Tirith. El santuario ya no está abarrotado de personas desplazadas de Gondor."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "76.84S"; 
          ["LONG"] = "29.35W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Pelargir"; 
      ["PROGRESS"] = "Encuentra Pelargir"; 
      ["LORE"] = "La ciudad portuaria de Pelargir fue el escenario de la batalla decisiva contra los corsarios de Umbar durante la Guerra del Anillo, cuando Aragorn ordenó al Ejército de los Muertos apoderarse de sus barcos. Balakhôr el Azote encontró su fin a bordo de su gran nave, la Joya de la Noche, y se espera que su muerte marque el fin de la amenaza que representan los Herederos de Castamir.\n\nLa flota gondoriana está en ruinas tras la Guerra del Anillo, y será tarea de Sirgon, Señor del Lebennin, reconstruir los barcos y el poder marítimo del reino lo más rápido posible. Con ese fin, la ciudad de Pelargir está llena del sonido de martillos y hachas a todas horas del día y de la noche."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "84.01S"; 
          ["LONG"] = "33.18W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Sirthanc"; 
      ["PROGRESS"] = "Encuentra Sirthanc"; 
      ["LORE"] = "La Almenara de Sirthanc se encendió durante la guerra para convocar a los guerreros a defender Minas Tirith, pero ahora está apagada. Si la fortuna de Gondor se mantiene, permanecerá apagada durante muchos años. Fue en Sirthanc donde el Señor Sirgon fue rescatado de la cautividad de los Haradrim, y ahora algunos de sus habitantes creen que debería permitírsele renunciar a su cargo como Señor de Lebennin para que pueda sanar las heridas de su mente y cuerpo."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "79.35S"; 
          ["LONG"] = "31.96W"; 
        }; 
      }; 
      };
  };
  -- Gondor del Rey Oriental / Rezagados y nuevas amenazas en el Alto Lebennin
  [1879464471] = {
      [1] = {
      ["NAME"] = "Grafeleg"; 
      ["PROGRESS"] = "Encuentra Grafeleg"; 
      ["LORE"] = "La cueva de Grafeleg está escondida en las montañas detrás de Tumladen, y los osos que habitan allí generalmente no han molestado a los residentes del refugio, el pueblo de Gondor correspondiendo de la misma manera. Sin embargo, con muchas más personas viviendo detrás de los muros de Tumladen mientras la guerra rugía, las tensiones con los que viven cerca se han inflamado."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "74.48S"; 
          ["LONG"] = "30.54W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Lhingar"; 
      ["PROGRESS"] = "Encuentra Lhingar"; 
      ["LORE"] = "Las arañas de Lhingar no se vieron obstaculizadas por la Guerra del Anillo, ni se vieron impedidas por su final. Aún se arrastran entre los árboles, tejiendo telarañas para atrapar a sus presas y alimentándose de cualquiera que se acerque demasiado a su guarida."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "74.77S"; 
          ["LONG"] = "26.37W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Campamento de Sadúkh"; 
      ["PROGRESS"] = "Encuentra el campamento de Sadúkh"; 
      ["LORE"] = "Tras la Guerra del Anillo, algunos corsarios huyeron a la naturaleza y buscaron obtener la victoria de su aparente derrota. Este es el campamento de Sadúkh, que cree que es él quien unificará a los corsarios bajo su bandera."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "77.42S"; 
          ["LONG"] = "27.79W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Campamento de Múshex"; 
      ["PROGRESS"] = "Encuentra el campamento de Múshex"; 
      ["LORE"] = "Tras el final de la guerra, algunos corsarios huyeron a la naturaleza para reagruparse. Este es el campamento de Múshex, que busca unificar a los corsarios bajo su propia bandera."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "80.67S"; 
          ["LONG"] = "25.71W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Campamento de Hárba"; 
      ["PROGRESS"] = "Encuentra el campamento de Hárba"; 
      ["LORE"] = "Tras su derrota en Pelargir, algunos corsarios escaparon a la naturaleza. Este es el campamento de Hárba, que cree que la victoria no está muy lejos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "82.37S"; 
          ["LONG"] = "29.64W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Campamento de Bukhád"; 
      ["PROGRESS"] = "Encuentra el campamento de Bukhád"; 
      ["LORE"] = "Tras su derrota en Pelargir, algunos corsarios escaparon a la naturaleza. Este es el campamento de Bukhád, que está seguro de que sus guerreros tendrán la victoria si pueden recuperar sus fuerzas."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "81.39S"; 
          ["LONG"] = "31.84W"; 
        }; 
      }; 
      };
  };
  -- Gondor del Rey Oriental / Reconquista del Bajo Lebennin
  [1879464488] = {
      [1] = {
      ["NAME"] = "Erynos"; 
      ["PROGRESS"] = "Encuentra Erynos"; 
      ["LORE"] = "El asentamiento de Erynos fue el escenario de uno de los sucesos más extraños de la guerra, cuando se descubrió a un grupo de saqueadores corsarios fuera de las murallas de la ciudad, aparentemente ahogados. Algunos creen que esto fue obra de las Cinco Hermanas de Lebennin, doncellas del río que se cree protegen las tierras por las que fluyen sus ríos, pero otros dicen que son solo figuras míticas.\n\nHoy en día, los habitantes de Erynos trabajan para restaurar sus vidas y ayudar a sus vecinos que sufrieron durante la guerra."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "80.08S"; 
          ["LONG"] = "32.80W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Ost Anglebed"; 
      ["PROGRESS"] = "Encuentra Ost Anglebed"; 
      ["LORE"] = "La gran ciudad de Ost Anglebed alberga a los guardianes de la Almenara de Amon Anglebed, que se encendió durante la Guerra del Anillo. A diferencia de las otras almenaras de Gondor, la de aquí permanece encendida a pesar de la llegada de la paz del Rey. Ahora los guardias mantienen una vigilancia sobre los habitantes del pueblo, temerosos de que algunos aliados del desleal Malthellim puedan pensar en continuar su trabajo y entregar el control del pueblo a los enemigos de Gondor."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "78.98S"; 
          ["LONG"] = "39.14W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Malbarth"; 
      ["PROGRESS"] = "Encuentra Malbarth"; 
      ["LORE"] = "El pequeño pueblo de Malbarth escapó de la mayor parte de los combates durante la guerra, pero las noticias de otras regiones de Gondor llenaron a los habitantes del pueblo de temor y miedo a que sus hogares no permanecieran seguros por mucho tiempo. Incluso ahora hay rumores de que algunos corsarios huyeron de la batalla en Pelargir y se esconden en la naturaleza, esperando su oportunidad para apoderarse del pueblo."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "80.14S"; 
          ["LONG"] = "42.38W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Linhir"; 
      ["PROGRESS"] = "Encuentra Linhir"; 
      ["LORE"] = "La ciudad de Linhir se extiende a lo largo del río Gilrain, y durante la Guerra del Anillo el cielo se oscureció por las artes malvadas de Sauron. Los hijos de Comeldir organizaron las defensas, y cuando finalmente terminó la lucha, la gente se mantuvo fuerte, menos dividida que su ciudad. Hoy, con la amenaza de la guerra detrás de ellos y el cielo brillante y despejado una vez más, los habitantes de Linhir han vuelto a sus vidas."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "81.41S"; 
          ["LONG"] = "45.43W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Sarnhad"; 
      ["PROGRESS"] = "Encuentra Sarnhad"; 
      ["LORE"] = "Este pequeño pueblo en el río Serni escapó de la mayor parte de los combates durante la guerra, pero las noticias de corsarios y semi-trolls atacando otros pueblos cercanos llenaron a los habitantes de temor, al igual que el cielo oscurecido por el Día sin Amanecer. Hoy, los habitantes de Sarnhad buscan volver a sus vidas normales."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "81.59S"; 
          ["LONG"] = "43.90W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Zarsatrâd"; 
      ["PROGRESS"] = "Encuentra Zarsatrâd"; 
      ["LORE"] = "Ubicado en el bosque al sur del bastión enano de Furukzahar, Zarsatrâd sirve como un puesto avanzado para los enanos Temámir que ahora viven en las Montañas Blancas. Trabajan para transportar piedra extraída a varios lugares de Gondor, ansiosos por ayudar a sus vecinos a reparar y reconstruir después de la Guerra del Anillo... por un precio razonable."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "77.80S"; 
          ["LONG"] = "34.56W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Furukzahar"; 
      ["PROGRESS"] = "Encuentra Furukzahar"; 
      ["LORE"] = "La fortaleza de Furukzahar es un bastión seguro para los enanos Temámir de las Montañas Blancas. Bajo el gobierno de su líder Hámisar, los enanos de cualquier clan son bienvenidos a visitar, pero las relaciones con la gente de Gondor no son especialmente cálidas en este momento. La decisión de Hámisar de cerrar las puertas de Furukzahar y no participar en la Guerra del Anillo no ha hecho que los enanos sean muy queridos por los habitantes de Lebennin."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "70.34S"; 
          ["LONG"] = "35.35W"; 
        }; 
      }; 
      };
  };
  -- Gondor del Rey Oriental / Rezagados y nuevas amenazas en el Bajo Lebennin
  [1879464489] = {
      [1] = {
      ["NAME"] = "Lornost"; 
      ["PROGRESS"] = "Encuentra Lornost"; 
      ["LORE"] = "Las ruinas de Lornost son un triste recordatorio de la crueldad infligida por los Herederos de Castamir y sus aliados haradrim: cuando la gente de Lornost se negó a rendirse, fueron masacrados y el castillo reducido a escombros. Ahora solo bestias salvajes caminan por los caminos de Lornost, y una brisa cruel se desliza entre los edificios abandonados."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "80.77S"; 
          ["LONG"] = "34.41W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Thama Aklam"; 
      ["PROGRESS"] = "Encuentra Thama Aklam"; 
      ["LORE"] = "El campamento de guerra de Thama Aklam fue construido durante la guerra por las fuerzas haradrim que buscaban cumplir los objetivos de Mordor. Con la derrota de Sauron, el campamento de guerra se ha convertido en el hogar de bandidos y otros tipos poco recomendables."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "80.69S"; 
          ["LONG"] = "36.55W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Hata Kebir"; 
      ["PROGRESS"] = "Encuentra Hata Kebir"; 
      ["LORE"] = "El campamento de guerra de Hata Kebir fue uno de los principales asentamientos construidos por los haradrim y corsarios que se unieron para invadir Lebennin y las vastas tierras de Gondor. Desde el final de la guerra, los bandidos se han congregado allí y ponen en peligro la paz del rey."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "84.53S"; 
          ["LONG"] = "37.30W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Ruinas de Ethillorn"; 
      ["PROGRESS"] = "Encuentra las ruinas de Ethillorn"; 
      ["LORE"] = "Los corsarios de Umbar quemaron el puerto de Ethillorn como parte de su campaña para conquistar Gondor para Sauron. Ahora que la guerra ha terminado, los corsarios se han ido, pero un mal más oscuro ha llegado a Ethillorn y ahora amenaza las tierras circundantes."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "83.85S"; 
          ["LONG"] = "45.62W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Ghyll de Orlach"; 
      ["PROGRESS"] = "Encuentra el Ghyll de Orlach"; 
      ["LORE"] = "Atraídas desde las cumbres nevadas de las Montañas Blancas por el sonido de la industria en la cantera de Aban-bazan, feroces bestias de nieve han hecho nuevas guaridas en los bosques de Lebennin. Huesos roídos y carroña sucia yacen en montones bajo los árboles y entre las rocas, un testimonio del hambre insaciable de estas bestias."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "74.96S"; 
          ["LONG"] = "35.77W"; 
        }; 
      }; 
      };
  };
