  -- Gondor del Rey del Oeste / Exploración del Valle de la Raíz Negra renovada
  [1879466366] = {
      [1] = {
      ["NAME"] = "Fennas Dûr"; 
      ["PROGRESS"] = "Encuentra Fennas Dûr"; 
      ["LORE"] = "Desde el umbral de la Puerta Oscura y en las sombras del Bosque Sombrío de Rohan, los Senderos de los Muertos tallan un gran túnel bajo la Montaña Embrujada, Dwimorberg, hasta Fennas Dûr en el Valle de la Raíz Negra de Gondor. Fue a través de Fennas Dûr que muchos de los Hombres Muertos de Dunharrow siguieron al Rey Elessar hasta la Piedra de Erech y al cumplimiento de su juramento en Pelargir. Lamentablemente, los pocos impenitentes que rechazaron la convocatoria traicionaron su juramento por segunda vez, condenándose a su destino por su propia voluntad. Ahora, estos Muertos Implacables aún permanecen, rondando las sombras del Valle de la Raíz Negra, inciertos y quizás indiferentes a si la maldición que Isildur les impuso alguna vez será levantada."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "53.15S"; 
          ["LONG"] = "66.85W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Morlad"; 
      ["PROGRESS"] = "Encuentra Morlad"; 
      ["LORE"] = "En las laderas meridionales de las Montañas Blancas, a orillas del río Morthond, se encuentra la capital del Valle de la Raíz Negra: la ciudad amurallada de Morlad. En lo alto de sus sinuosas calles se encuentra la finca del señor del Valle de la Raíz Negra, Duinhir, y de su esposa, Rosfin. Cuando Gondor fue llamado a la guerra, el señor Duinhir y sus hijos, Duilin y Derufin, lideraron a unos quinientos arqueros hasta Minas Tirith para defender la ciudad contra los ejércitos de Mordor. Una vez terminada la guerra y tras el regreso del señor Duinhir y sus hombres a Morlad, se difundió la noticia de la muerte de sus hijos y del intento de culparle del asesinato de un emisario haradrim. A pesar de la victoria de Gondor, Morlad se ha convertido en un lugar sombrío, y muchos de sus habitantes creen que el rey Elessar los ha dejado de lado tras la Guerra del Anillo."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "56.84S"; 
          ["LONG"] = "67.55W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Alagrant"; 
      ["PROGRESS"] = "Encuentra Alagrant"; 
      ["LORE"] = "Situado en el bosque al oeste de la Colina de Erech, el pueblo de Alagrant está habitado principalmente por cazadores y comerciantes del Valle de la Raíz Negra."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "58.61S"; 
          ["LONG"] = "68.59W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Tingobel"; 
      ["PROGRESS"] = "Encuentra Tingobel"; 
      ["LORE"] = "Aunque fue saqueado por los Orcos de las Montañas Blancas durante la Guerra del Anillo, el pueblo minero de Tingobel ha sido recuperado por orden del señor Duinhir. Se han reparado los daños en sus casas y se ha restaurado la mina, pero las vidas perdidas en su caída no han sido olvidadas por quienes habitan en el Valle de la Raíz Negra."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "56.13S"; 
          ["LONG"] = "64.04W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Sardol"; 
      ["PROGRESS"] = "Encuentra Sardol"; 
      ["LORE"] = "Al sur de Alagrant, a lo largo del río Morthond, se encuentra Sardol, un pequeño pueblo habitado por pescadores y agricultores. Antes de que los Herederos de Castamir erigieran el ahora arruinado bloqueo en el camino a través de la Corona de Tarlang, Sardol servía como un pequeño puesto comercial para aquellos que viajaban entre Morlad y Dol Amroth."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "60.97S"; 
          ["LONG"] = "69.74W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Lancrath"; 
      ["PROGRESS"] = "Encuentra Lancrath"; 
      ["LORE"] = "Al este de la Colina de Erech y junto al paso conocido como el Cuello de Tarlang se encuentra Lancrath, un pequeño pueblo habitado por agricultores, artesanos y comerciantes. Antes del regreso del señor Duinhir de la guerra y la recuperación de Tingobel, muchos de los refugiados desplazados del pueblo minero buscaron refugio y fueron bien recibidos por la amable gente de Lancrath."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "58.19S"; 
          ["LONG"] = "62.98W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Eryn Asgath"; 
      ["PROGRESS"] = "Encuentra Eryn Asgath"; 
      ["LORE"] = "En medio de los bosques al sureste de la Colina de Erech, cerca del Cuello de Tarlang, se encuentra Eryn Asgath, una guarida habitada por los lobos invasores que han llegado desde Lamedon y las colinas circundantes. Con sus terribles aullidos resonando en la noche, los lobos han traído una nueva inquietud al Valle de la Raíz Negra tras la Guerra del Anillo."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "60.29S"; 
          ["LONG"] = "64.68W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Lhingroth"; 
      ["PROGRESS"] = "Encuentra Lhingroth"; 
      ["LORE"] = "En las tierras altas al este del pueblo de Sardol, las cavernas de Lhingroth se adentran bajo los picos de Tarlang. Aunque han estado habitadas durante mucho tiempo por las arañas del Valle de la Raíz Negra, se dice que también eran conocidas por los Hombres de las Montañas en tiempos antiguos, ya que se han visto a los Muertos en la oscuridad de Lhingroth."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "47.88S"; 
          ["LONG"] = "7.11W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Colina de Erech"; 
      ["PROGRESS"] = "Encuentra la colina de Erech"; 
      ["LORE"] = "Situada cerca de la entrada al Valle de la Raíz Negra, la Colina de Erech ha sido el escenario de una gran cantidad de historias en Gondor. En la Segunda Edad, fue allí donde Isildur colocó la Piedra de Erech, fue allí donde los Hombres de las Montañas juraron ayudar a Gondor y fue allí donde traicionaron a Isildur y fueron maldecidos. Fue por esta razón que la Colina de Erech llegó a ser mal vista e incluso temida por la gente del Valle de la Raíz Negra, quienes creían que los Muertos la habitaban."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "58.26S"; 
          ["LONG"] = "64.86W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Piedra de Erech"; 
      ["PROGRESS"] = "Encuentra la Piedra de Erech"; 
      ["LORE"] = "Traída desde la destrucción de Númenor, la Piedra de Erech se encuentra en la cima de la Colina de Erech en el Valle de la Raíz Negra. En verdad, la Piedra de Erech es una de las siete Vandassari, las Piedras del Juramento, y se llama Orossar, pero esto ha sido olvidado por todos excepto por los eruditos más instruidos de la Tierra Media. Fue sobre la Piedra de Erech que los Hombres de las Montañas hicieron hace mucho tiempo un juramento a Isildur para ayudar a Gondor en la guerra contra el Señor Oscuro, Sauron. Sin embargo, cuando se negaron a honrar su juramento, Isildur los maldijo, condenándolos a disminuir y convertirse en los Muertos sin sueño. Aunque muchos de los Muertos han partido ahora con el cumplimiento de su juramento, la Piedra de Erech todavía descansa en lo alto de su colina y sirve para siempre como recordatorio de la traición de los Hombres de las Montañas."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "58.05S"; 
          ["LONG"] = "65.05W"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "Calle de Azruthor"; 
      ["PROGRESS"] = "Encuentra la calle de Azruthor"; 
      ["LORE"] = "Bajo el mando de Balakhôr el Azote, uno de los Herederos de Castamir, Azruthor construyó un bloqueo en la Corona de Tarlang. Allí se suponía que se desarrollarían los planes del Azote para saquear Anfalas y reclamar sus costas para Umbar, pero Azruthor fracasó en su intento de conquistar las tierras de Gondor. Con su compañía de corsarios derrotada y su aparente alianza con los Muertos Implacables rota, encontró su fin a manos de valientes aventureros y el bloqueo fue destruido. Tras la Guerra del Anillo, todo lo que queda del gran plan de Azruthor es un campamento medio arruinado en medio de un bloqueo destrozado en la Corona de Tarlang."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "67.28S"; 
          ["LONG"] = "68.88W"; 
        }; 
      }; 
      };
  };
