      [1] = {
      ["NAME"] = "Grijâti"; 
      ["PROGRESS"] = "Encuentra Grijâti"; 
      ["LORE"] = "Grijâti, el Hogar de los Náufragos, se encuentra en la costa occidental del Cabo de Umbar. Los Haradrim permanecen aquí con la esperanza de usurpar el control de la Hermandad de las Monedas."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "16.67S"; 
          ["LONG"] = "114.86W"; 
        }; 
      }; 
