      [2] = {
      ["NAME"] = "Súlstrok"; 
      ["PROGRESS"] = "Encuentra Súlstrok"; 
      ["LORE"] = "Súlstron, el Refugio de los saqueadores, dirigido por el corsario goblin Shakfut Tranche-gorge, es un campamento improvisado al pie de las montañas del Cabo de Umbar."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.62S"; 
          ["LONG"] = "112.41W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Jâghimsa"; 
      ["PROGRESS"] = "Encuentra Jâghimsa"; 
      ["LORE"] = "Jâghimsa, el Bosque Errante, alberga ucornos y un temible pastor de trolls silvanos. Se encuentra en la ladera de la colina al noreste de Rakhatâb."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "23.13S"; 
          ["LONG"] = "112.86W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Kan Skûrja"; 
      ["PROGRESS"] = "Encuentra Kan Skûrja"; 
      ["LORE"] = "El Refugio Lúgubre, o Kan Skûrja, es el hogar improvisado de los corsarios nómadas que todavía saquean los mares a lo largo de las Islas Escudo y el Cabo de Umbar."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "19.81S"; 
          ["LONG"] = "109.88W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Ghadir Sûd"; 
      ["PROGRESS"] = "Encuentra Ghadir Sûd"; 
      ["LORE"] = "Ghadir Sûd, los Pozos Negros, hace referencia a antiguos manantiales de alquitrán que que brotaban de la tierra hace mucho tiempo. Estos manantiales oscuros y burbujeantes atraían a las salamandras que aún hoy habitan allí. Aunque los manantiales ya no existen, las salamandras siguen allí."; 
      ["POINTS"] = {
