      [8] = {
      ["NAME"] = "Bêkhmol"; 
      ["PROGRESS"] = "Encuentra Bêkhmol"; 
      ["LORE"] = "Piratas que no son leales ni a los caídos Herederos de Castamir ni a los reinantes de la Hermandad de las Monedas atacan barcos en el mar al norte del Cabo de Umbar y traen sus botines a tierra en Bêkhmol, el Muelle libre."; 
