      [10] = {
      ["NAME"] = "Taj-kâta"; 
      ["PROGRESS"] = "Encuentra Taj-kâta"; 
      ["LORE"] = "Los merodeadores de los pantanos cubiertos de juncos hacen de Taj-kâta, los Llanos del Pantano, su hogar ancestral. Aquí, las criaturas vivieron en paz durante siglos. Ahora, los cazadores recorren los Llanos del Pantano para adquirir semillas y patas de los merodeadores de los pantanos para abastecer a los cocineros de Umbar Baharbêl."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "14.29S"; 
          ["LONG"] = "97.68W"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "Jêbel Lakha"; 
      ["PROGRESS"] = "Encuentra Jêbel Lakha"; 
      ["LORE"] = "Jêbel Lakha, la Piedra de reunión, alberga dos manadas de leones en guerra dirigidas por los hermanos Skûr y Kabûro. Ambas bestias han atacado durante mucho tiempo a los exploradores insensatos que se acercan demasiado a su territorio. Los hermanos acechan la sabana y las piedras de Jêbel Lakha en busca del otro."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "15.49S"; 
          ["LONG"] = "92.87W"; 
        }; 
      }; 
      };
      [12] = {
      ["NAME"] = "Hâtaphor"; 
      ["PROGRESS"] = "Encuentra Hâtaphor"; 
      ["LORE"] = "Hâtaphor, la guarida del ratero, es una zona peligrosa al este de Umbar Baharbêl que alberga una camada particularmente peligrosa de arañas. La seda de esta misma camada es muy apreciada por los sastres de la ciudad y a menudo se secuestra a los trabajadores mientras intentan recuperar las telas de seda en la guarida."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "19.17S"; 
          ["LONG"] = "92.78W"; 
        }; 
      }; 
      };
      [13] = {
      ["NAME"] = "Bâlakhat"; 
      ["PROGRESS"] = "Encuentra Bâlakhat"; 
      ["LORE"] = "Los viajeros que se encuentran en Bâlakhat, las Aguas del Devorador, rara vez regresan. Los temibles cocodrilos que habitan esta región son conocidos por su gusto por la carne."; 
      ["POINTS"] = {
