  -- Umbar Baharbêl / Umbar Baharbêl, la Ciudad de los Corsarios
  [1879477633] = {
      [1] = {
      ["NAME"] = "Calatirion / Torre del faro de Elendil"; 
      ["PROGRESS"] = "Encuentra Calatirion, la Torre Faro"; 
      ["LORE"] = "Has descubierto Calatirion, la Torre de la Almenara, que fue levantada por el Rey Elendil para celebrar su victoria sobre Sauron. Sin embargo, la torre no se mantendría para siempre, pues los siervos del Señor Oscuro no habían desaparecido, y retornarían en una era posterior. Por orden del Despojador Proscrito, uno de los Nazgûl, Calatirion fue derribada. El día de su caída fue llamado la Muerte de la Luz, y el horror de ello es recordado aún por los residentes más antiguos de la ciudad."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "19.88S"; 
          ["LONG"] = "103.85W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Almenara del Muelle"; 
      ["PROGRESS"] = "Encuentra la Almenara del Muelle"; 
      ["LORE"] = "Has descubierto el Faro del Muelle, que recibe a los barcos que llegan al Refugio de los Veleros después de largos viajes en el mar, guiándolos a seguridad cuando llegan de noche."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "20.00S"; 
          ["LONG"] = "100.87W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Astillero del Norte"; 
      ["PROGRESS"] = "Encuentra el Astillero del Norte"; 
      ["LORE"] = "En la lengua umbari, los lugares donde se encuentran los grandes esqueletos de los barcos en construcción se llaman Jâsh-bithi. Este es el más septentrional de los dos más grandes, y está bajo la supervisión de Ahûd, quien ha trabajado entre los barcos del Refugio de los Veleros durante muchos años."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.84S"; 
          ["LONG"] = "100.15W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Astillero del Sur"; 
      ["PROGRESS"] = "Encuentra el Astillero del Sur"; 
      ["LORE"] = "En la lengua umbari, los lugares donde se encuentran los grandes esqueletos de los barcos en construcción se llaman Jâsh-bithi. Este es el más meridional de los dos más grandes, y está bajo la supervisión de Râmax, quien ha jurado ver derrotados por fin a los Herejes que permanecen en el Refugio de los Veleros."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "21.37S"; 
          ["LONG"] = "98.64W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Torre del guardián del puerto"; 
      ["PROGRESS"] = "Encuentra la Torre del guardián del puerto"; 
      ["LORE"] = "Eshmun, el Capitán del Refugio, vigila cuidadosamente los sucesos en todo el Refugio de los Veleros desde su puesto en la Torre del Guardián del Puerto. Es un aliado leal de la Hermandad de las Monedas y espera con entusiasmo el regreso de Tumúldo Aguas Feroces, a quien espera que navegue de regreso a Umbar cualquier día."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "20.10S"; 
          ["LONG"] = "99.25W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Dâr Irkant / Sala de subastas"; 
      ["PROGRESS"] = "Encuentra Dâr Irkant"; 
      ["LORE"] = "Has descubierto Dâr Irkant, la casa de subastas de Umbar, por la que fluye una gran cantidad de moneda hacia adentro y hacia afuera de las arcas de las familias mercantes del Barrio Alto. Hármelak, la Reina de Oro, vigila cuidadosamente los negocios realizados en Dâr Irkant."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "17.93S"; 
          ["LONG"] = "98.31W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Baños de Ilmai Iforikh"; 
      ["PROGRESS"] = "Encuentra los Baños de Ilmai Iforikh"; 
      ["LORE"] = "Has descubierto los Baños de Ilmai Iforikh, conocidos por los residentes locales como las Aguas Floridas. Se rumorea que la tranquila paz de estos baños calman tanto el cuerpo como la mente."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.03S"; 
          ["LONG"] = "98.86W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Bith Gabâr / El Foro"; 
      ["PROGRESS"] = "Encuentra Bith Gabâr"; 
      ["LORE"] = "Has descubierto Bith Gabâr, el gran foro y lugar de encuentro del Barrio Alto. Retiene un aire de permanencia duradera otorgado por la presencia de abundante arquitectura Númenóreana, y ha sido conocido por atraer a gente de toda clase que desea llamar la atención sobre sí mismos o sus actividades."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.30S"; 
          ["LONG"] = "97.84W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Dâr Laja / Sala de reuniones"; 
      ["PROGRESS"] = "Encuentra Dâr Laja"; 
      ["LORE"] = "Has descubierto Dâr Laja, la Sala de Encuentros, ubicada en la cabecera del gran foro en el Barrio Alto. Esta sala es una de las estructuras Númenóreanas intactas restantes en la ciudad, y es el lugar donde la Hermandad de las Monedas a menudo se reúne para asuntos oficiales."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.60S"; 
          ["LONG"] = "97.50W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Dâr Jeraf / Casa de la Sabiduría"; 
      ["PROGRESS"] = "Encuentra Dâr Jeraf"; 
      ["LORE"] = "Has descubierto Dâr Jeraf, la gran academia de los Jardines de Tor que fue conocida una vez como la Casa de la Sabiduría. Fue destruida por siervos de la Iglesia del Omnividente, y ahora solo escombros permanecen como recordatorio del daño hecho por los seguidores de Sauron."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "17.95S"; 
          ["LONG"] = "96.83W"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "Kamîr Kateb / Scriptorium"; 
      ["PROGRESS"] = "Encuentra Kamîr Kateb"; 
      ["LORE"] = "Has descubierto Kamîr Kateb, el escritorio que alguna vez sostuvo innumerables registros e historias de Umbar Baharbêl. Ahora ha caído en desreparo y desuso, y las Cámaras de Registros solo reúnen polvo."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.26S"; 
          ["LONG"] = "96.67W"; 
        }; 
      }; 
      };
      [12] = {
      ["NAME"] = "Dâr Tabib / Boticario"; 
      ["PROGRESS"] = "Encuentra Dâr Tabib"; 
      ["LORE"] = "Has descubierto Dâr Tabib, la botica parcialmente arruinada que fue conocida en una época como la Casa de los Sanadores. Como otras estructuras de aprendizaje y conocimiento en los Jardines de Tor, la Iglesia del Omnividente cobró un tributo cruel sobre Dâr Tabib."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.67S"; 
          ["LONG"] = "96.88W"; 
        }; 
      }; 
      };
      [13] = {
      ["NAME"] = "Dahâl Huliz / La Arena"; 
      ["PROGRESS"] = "Encuentra Dahâl Huliz"; 
      ["LORE"] = "Has descubierto Dahâl Huliz, la gran arena gladiatoria de Umbar Baharbêl. Mucha sangre ha sido derramada en la arena durante muchos años de la historia de la ciudad, y en la noche del Motín de la Piedra del Mar, aún más fue derramada cuando Rothog la Tormenta volvió su mirada a los Herederos de Castamir que observaban desde los asientos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "19.32S"; 
          ["LONG"] = "95.62W"; 
        }; 
      }; 
      };
      [14] = {
      ["NAME"] = "Baños de Kadax"; 
      ["PROGRESS"] = "Encuentra los Baños de Kadax"; 
      ["LORE"] = "Has descubierto los Baños de Kadax, donde se alienta a los ciudadanos del Barrio Bajo a encontrar un respiro del polvo y la suciedad de la ciudad."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "20.18S"; 
