      };
      [15] = {
      ["NAME"] = "El Pozo Abismal"; 
      ["PROGRESS"] = "Encuentra el Pozo Sin Fondo"; 
      ["LORE"] = "Has descubierto el Pozo Sin Fondo, una piscina profunda y ancha que recoge agua de mar que luego puede ser utilizada por los residentes de la ciudad o para combatir incendios. Dos pescadores vienen al Pozo Sin Fondo todos los días, y lo han hecho sin falta desde que eran niños."; 
      ["POINTS"] = {
