      [20] = {
      ["NAME"] = "Cárcel"; 
      ["PROGRESS"] = "Encuentra la Cárcel de la Flota Rápida"; 
      ["LORE"] = "Has descubierto la Cárcel de la Flota Rápida, donde se retiene a quienes son encontrados culpables de delitos hasta que se determina qué debe hacerse con ellos. Muchas de estas personas eligen juicio por combate en la arena como medio para ganarse su libertad, esperando de corazón que no sean enfrentados contra Rothog la Tormenta cuando les toque."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "23.91S"; 
          ["LONG"] = "99.89W"; 
        }; 
      }; 
      };
      [21] = {
      ["NAME"] = "Campo del Desfile"; 
      ["PROGRESS"] = "Encuentra el Terraplén de la Flota Rápida"; 
      ["LORE"] = "Has descubierto el Terraplén de la Flota Rápida, donde los soldados marchan ante los líderes reunidos de la Hermandad de las Monedas. Tales reuniones no han sido comunes recientemente, pero en tiempos de paz, cuando se requiere ceremonia, el Terraplén estará listo."; 
      ["POINTS"] = {
