      [22] = {
      ["NAME"] = "Stûna"; 
      ["PROGRESS"] = "Encuentra el Stûna"; 
      ["LORE"] = "Has descubierto el Stûna, donde atracan los barcos de los Corsarios. La mayoría de la Flota Rápida se perdió en Pelargir durante la Guerra del Anillo, pero algunos barcos permanecen, ahora bajo el mando de la Hermandad de las Monedas."; 
      ["POINTS"] = {
