  -- Umbar Baharbêl / Reconquista de Khabârkhad
  [1879486395] = {
      [1] = {
      ["NAME"] = "Itekh-kên"; 
      ["PROGRESS"] = "Encuentra Itekh-kên"; 
      ["LORE"] = "Este pequeño campamento de buscadores de tesoros, ubicado en los confines del norte de Khabârkhad, da la impresión de que podría desaparecer en cualquier momento, especialmente en el instante en que se descubra algo valioso más lejos de lo que le conviene a Itekh-kên. El nombre que le dan a esta cámara quienes residen aquí significa 'refugio de los buscadores' en lengua umbari, pero sigue siendo un lugar activo dentro de Umbar-môkh solo mientras haya algo cerca que valga la pena buscar."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "117.30S"; 
          ["LONG"] = "140.94W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Mekab-kuphâr"; 
      ["PROGRESS"] = "Encuentra Mekab-kuphâr"; 
      ["LORE"] = "Bajo las órdenes del Padre del Salón, los enanos Temámir trabajaron sin descanso para tallar pasadizos hacia Umbar-môkh desde la Piedra de la Costa. Este campamento de su pueblo sirve como entrada vigilada a los salones y cámaras de Khabârkhad, y Khôltekh observa atentamente las idas y venidas de quienes pasan por Mekab-kuphâr."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "119.70S"; 
          ["LONG"] = "140.17W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Lôkhalel"; 
      ["PROGRESS"] = "Encuentra Lôkhalel"; 
      ["LORE"] = "Las tumbas de Lôkhalel han llamado la atención de los saqueadores que buscan saquear las criptas en busca de tesoros y baratijas de valor incalculable. Desde aquí, los más audaces a veces se adentran en los pasadizos contiguos de Khabârkhad, poniendo en peligro a cualquiera que consideren un rival por los objetos de valor que hay en su interior."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "118.08S"; 
          ["LONG"] = "141.55W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Nishabêt"; 
      ["PROGRESS"] = "Encuentra Nishabêt"; 
      ["LORE"] = "Nishabêt, 'nido de tejedoras' en lengua umbari, solía referirse a una pequeña cámara dentro de Khabârkhad. Al no haber suficientes guardias para contener la avalancha de arañas a medida que salían, el nido se ha expandido y ahora ocupa los pasadizos circundantes. A menos que se haga algo al respecto, Nishabêt podría llegar a ser algún día el nombre de todo Umbar-môkh."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "118.35S"; 
          ["LONG"] = "139.78W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Sektakhâb"; 
      ["PROGRESS"] = "Encuentra Sektakhâb"; 
      ["LORE"] = "Un techo abovedado y lejano, junto con amplias avenidas, caracterizan las tumbas donde antaño descansaban eternamente los nobles de Umbar Baharbêl; sin embargo, el silencioso sepulcro de Sektakhâb ya no es un lugar de paz. Ahora, los muertos inquietos acechan en estas criptas del suroeste de Khabârkhad, poniendo en peligro a cualquiera que se atreva a acercarse."; 
      ["POINTS"] = {
