      [7] = {
      ["NAME"] = "Tûl Ushu"; 
      ["PROGRESS"] = "Encuentra Tûl Ushu"; 
      ["LORE"] = "Las colinas de Tûl Ushu, en el noreste de Ambarûl, son el hogar de muchos usan-kûni, los escorpiones gigantes de Shagâna."; 
      ["POINTS"] = {
