      [8] = {
      ["NAME"] = "Shegdush"; 
      ["PROGRESS"] = "Encuentra Shegdush"; 
      ["LORE"] = "Shegdush, que significa 'hogar de cerdos' en shagâni, es el terreno de juego favorito de los jabalíes del este de Ambarûl."; 
      ["POINTS"] = {
