      [9] = {
      ["NAME"] = "Umûn Khab"; 
      ["PROGRESS"] = "Encuentra Umûn Khab"; 
      ["LORE"] = "En los pantanos de las orillas del sur del Ikorbân, los mosquitos se reúnen en Umûn Khab."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "25.78S"; 
          ["LONG"] = "81.65W"; 
