      [10] = {
      ["NAME"] = "Eshadûr"; 
      ["PROGRESS"] = "Encuentra Eshadûr"; 
      ["LORE"] = "Antiguamente el principal pueblo pesquero de Ambarûl, Eshadûr ha caído bajo la ocupación de los Ordâkhai. Tras ser derrotadas por Girhâzi y la revuelta Ambarûli, la mayoría de las fuerzas Ordâkhai huyeron al sur del Ikorbân, expulsaron a los antiguos habitantes de Eshadûr y establecieron allí su nueva base de operaciones. Desde aquí ponen a prueba las defensas Dumûri y esperan refuerzos del sur para recuperar el control de Iridír y el norte de Ambarûl."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "22.30S"; 
          ["LONG"] = "84.95W"; 
