  -- Ambarûl / Explorando Ambarûl
  [1879491585] = {
      [1] = {
      ["NAME"] = "Iridír"; 
      ["PROGRESS"] = "Encuentra a Iridír"; 
      ["LORE"] = "Construido sobre pilotes de madera sobre el pantano, Iridír es el principal pueblo de Ambarûl. Hogar de agricultores, pescadores y artesanos, ya no es el centro de comercio que solía ser. Después de liberarse del yugo de sus opresores Ordâkhai, Girhâzi y los demás habitantes de Iridír trabajan para restaurar el comercio en el pueblo mientras mantienen la independencia de Ambarûl."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "22.14S"; 
          ["LONG"] = "80.64W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Sûru"; 
      ["PROGRESS"] = "Encuentra a Sûru"; 
      ["LORE"] = "Situada en la orilla norte del Vado de Algas, Sûru es una fortificación Dumûri que les permite mantener el control del único paso de río en Ambarûl. Las torres de arqueros que se están construyendo en Sûru ayudarán a los Dumûri a defender el paso del río y les permitirán vigilar el camino, protegiendo así a los viajeros y a las caravanas comerciales."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "26.83S"; 
          ["LONG"] = "77.11W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Muro de Telperiën"; 
      ["PROGRESS"] = "Encuentra el Muro de Telperiën"; 
      ["LORE"] = "Construido por Númenor durante el reinado de Tar-Telperiën, el muro fue construido como una barrera para proteger su refugio de Vëalondë, ahora Umbar, de los pueblos nativos. El Muro de Telperiën fue destruido por terremotos en la Segunda Edad y más tarde por los Hamâti usando Narghâk cuando conquistaron Umbar."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "17.44S"; 
          ["LONG"] = "89.67W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Paso de Zibâla"; 
      ["PROGRESS"] = "Encuentra el Tramo de la Inundación"; 
      ["LORE"] = "Los restos de un alto puente arqueado construido en los primeros años de la Tercera Edad para que la Ruta de las Riquezas cruzara el Ikorbân. También conocido como el Tramo de Zibâla, fue destruido por los Ambarûli hace unos cien años en un esfuerzo por mantener a raya a los ejércitos de Ordâkh. Este acto de destrucción solo ralentizó el avance de los Ordâkhai y no los detuvo."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "22.55S"; 
          ["LONG"] = "82.40W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Vado de Algas"; 
      ["PROGRESS"] = "Encuentra el Vado de Algas"; 
      ["LORE"] = "Una serie de balsas unidas entre sí forman el Vado de Algas, el único paso de río actualmente en Ambarûl. El puente improvisado se construyó tras la destrucción del Puente de la Inundación hace unos cien años, y es actualmente el principal objeto de conflicto entre los Dumûri y los Ordâkhai restantes en Ambarûl."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "28.07S"; 
          ["LONG"] = "78.46W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Burukíri"; 
      ["PROGRESS"] = "Encuentra Burukíri"; 
      ["LORE"] = "Un huerto de naranjos aún en funcionamiento, este huerto proporciona frutas a Ambarûl, con suficiente excedente para comerciar con las comunidades vecinas."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.60S"; 
          ["LONG"] = "80.66W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Asha Mûn"; 
      ["PROGRESS"] = "Encuentra Asha Mûn"; 
      ["LORE"] = "Hace mucho tiempo se extraía sal de roca de estas minas cuando Ambarûl era un centro de comercio en Shâgana. Los túneles han sido abandonados durante mucho tiempo, ya que los trabajadores se han visto obligados a centrarse en la agricultura para proporcionar alimentos a las tierras menos fértiles controladas por el Imperio de Ordâkh. La mayoría de la gente no se atreve a entrar en las antiguas minas, ya que se sabe que están infestadas de usan-kûni."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "19.60S"; 
          ["LONG"] = "77.78W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Mehêtur"; 
      ["PROGRESS"] = "Encuentra Mehêtur"; 
      ["LORE"] = "Mehêtur es una granja de papiro en funcionamiento. El papiro, la planta, se cultiva aquí y luego se procesa en papiro, la superficie de escritura. Sin la presencia de los Ordâkhai, hay poca demanda de papiro en Ambarûl, ya que la población agraria es en gran parte analfabeta."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "20.75S"; 
          ["LONG"] = "82.23W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Ekagar"; 
      ["PROGRESS"] = "Encuentra Ekagar"; 
      ["LORE"] = "Ekagar es una granja de arroz en funcionamiento en la orilla norte del Ikorbân. El arroz es un cultivo ideal para los pantanos de Ambarûl y es un alimento básico de la dieta local. También es un excelente producto comercial, ya que puede secarse, lo que facilita su almacenamiento y transporte."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.77S"; 
          ["LONG"] = "85.55W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Gishtir"; 
      ["PROGRESS"] = "Encuentra Gishtir"; 
      ["LORE"] = "Un pequeño campamento de leñadores recién fundado, Gishtir se estableció con la esperanza de cosechar los árboles con madera de mayor calidad en un bosque cercano."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "15.04S"; 
          ["LONG"] = "78.92W"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "Arwáth"; 
      ["PROGRESS"] = "Encuentra a Arwáth"; 
      ["LORE"] = "Un bosquecillo de árboles antiguos difícil de encontrar cerca del borde norte de Ambarûl, Arwáth fue durante mucho tiempo rumoreado como embrujado. En realidad, es un oasis habitado por los Elfos Kinta, actualmente ocupado solo por un guardián y los espíritus de los Kintai que se desvanecieron allí."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "13.80S"; 
          ["LONG"] = "79.18W"; 
        }; 
      }; 
      };
      [12] = {
      ["NAME"] = "Dubarâkh"; 
      ["PROGRESS"] = "Encuentra al Dubarâkh"; 
      ["LORE"] = "Cuando el Imperio de Ordâkh prohibió la alfabetización para los nativos de Ambarûl, los seguidores de las Viejas Vías se apresuraron a recopilar todos los pergaminos y libros relacionados con la historia y la cultura de Ambarûl para salvarlos de la destrucción. Esta colección de documentos fue escondida para su preservación, y la ubicación de donde se almacena ha sido olvidada durante mucho tiempo."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "54.06N"; 
          ["LONG"] = "145.69W"; 
        }; 
      }; 
      };
      [13] = {
      ["NAME"] = "Esh Enûn"; 
      ["PROGRESS"] = "Encuentra a Esh Enûn"; 
      ["LORE"] = "Este templo de Barkhûsh, un templo de Sauron, el Omnividente, no es más que una cáscara quemada después de la revuelta de Ambarûl, liderada por Girhâzi, lo destruyó hace meses. Fue una vez el hogar de los sacerdotes de Sauron, quienes sometían a la población local a la voluntad de su Señor. Casi inmediatamente después de enterarse de la derrota tanto del Señor Oscuro como del Emperador de Ordâkh, los campesinos de Ambarûl quemaron y destruyeron el templo junto con sus malvados sacerdotes."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "22.49S"; 
          ["LONG"] = "79.26W"; 
        }; 
      }; 
      };
      [14] = {
      ["NAME"] = "Gha Nêkha"; 
      ["PROGRESS"] = "Encuentra a Gha Nêkha"; 
      ["LORE"] = "Un pequeño puesto al sur del Ikorbân, Gha Nêkha fue construido para proporcionar agua y refugio a los viajeros cansados que navegan por el desierto del sur de Ambarûl. Aunque está cerca de Eshadûr, los Ordâkhai no han mostrado interés en este pequeño asentamiento."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "25.44S"; 
          ["LONG"] = "84.66W"; 
        }; 
      }; 
      };
  };
