  -- Khûd Zagin / Descubriendo Khûd Zagin
  [1879491605] = {
      [1] = {
      ["NAME"] = "Jirush"; 
      ["PROGRESS"] = "Encuentra"; 
      ["LORE"] = "Jirush fue una vez la ciudad principal y la estación de reabastecimiento para las caravanas que se dirigían hacia el sur por el Camino de las Riquezas, pero hoy en día está prácticamente abandonada, con su población desplazada por la guerra y obligada a trasladarse a las minas. Algunos ancianos y ancianas permanecen en Jirush, con las manos ocupadas en las preocupaciones cotidianas, aunque sus mentes recuerdan tiempos mejores, de hace mucho tiempo. La arena está invadiendo lentamente Jirush, y los pocos que aún permanecen aquí creen que, en una docena de años o menos, la ciudad quedará completamente consumida por el desierto que se extiende."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "37.26S"; 
          ["LONG"] = "79.95W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Shonith"; 
      ["PROGRESS"] = "Encuentra Shonith"; 
      ["LORE"] = "En el idioma de los Avabár-kintai, el nombre Shonith significa 'claro de paz', y los Elfos que cuidan este oasis en los confines meridionales del Khûd trabajan incansablemente para que pueda conservar ese nombre. Los Veróthi del desvanecido Kintai crecen en islas dentro del estanque en el centro de Shonith, y otros están plantados alrededor del agua, un oasis de vida aislado de las arenas del desierto... por el momento."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "45.94S"; 
          ["LONG"] = "72.50W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Tumbas de Nirgambâr"; 
      ["PROGRESS"] = "Encuentra las Tumbas de Nirgambâr"; 
      ["LORE"] = "Las criptas y tumbas de Nirgambâr se encuentran en un valle protegido en los confines septentrionales del Khûd, ahora en gran parte sepultado por el desierto. Las tumbas fueron utilizadas por los Númenóreanos Negros en la Tercera Edad para dar descanso a sus muertos, y los khûdi dicen que, desde entonces, espíritus inquietos y seres peligrosos han acechado sus silenciosas salas. Se rumorea que estos sucesos son incluso anteriores a los Númenóreanos Negros y que podrían haber influido en su abandono del lugar, pero ya no queda nadie vivo que pueda afirmarlo con certeza."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "34.45S"; 
          ["LONG"] = "87.94W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Paso de Danagír"; 
      ["PROGRESS"] = "Encuentra el Cruce de Danagír"; 
      ["LORE"] = "En el idioma de los Shagâni, el nombre Danagír significa 'camino seguro', pero el gran puente que cruza el río Barûg entre Khûd Zagin e Imhûlar no da la sensación de ser tan seguro como promete su nombre."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "37.13S"; 
          ["LONG"] = "71.77W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Menundâri-en"; 
      ["PROGRESS"] = "Encuentra Menundâri-en"; 
      ["LORE"] = "La colosal estatua de Menundâri-en, el Eterno, fue esculpida durante la Segunda Era en memoria del poderoso rey hechicero Izighûz. La Iglesia de Barkhûsh la consideró herética e intentó destruirla, pero lo que queda del Eterno aún puede verse en Khûd Zagin."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "32.26S"; 
          ["LONG"] = "82.40W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Ghalbûru"; 
      ["PROGRESS"] = "Encuentra Ghalbûru"; 
      ["LORE"] = "Este complejo de valles y cavernas, situado entre los cañones rocosos al este del Khûd, era conocido como 'el Corte de los Ladrones' por los habitantes de Jirush y sus ocupantes ordâkhai. El nombre fue adoptado como un símbolo de honor por los diversos bandidos, salteadores de caminos y luchadores por la libertad que ahora han hecho de este lugar su hogar, y ellos lo llaman por su nombre en shagâni: Ghalbûru."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "37.08S"; 
          ["LONG"] = "73.83W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Khanâg occidental"; 
      ["PROGRESS"] = "Encuentra el Khanâg Occidental"; 
      ["LORE"] = "Un khanâg sirve como lugar de descanso para los comerciantes y sus animales en las principales rutas que atraviesan el desierto, y como punto de encuentro y mercado para los habitantes locales del Khûd.\n\nEste Khanâg, al oeste de Jirush, sigue teniendo una actividad moderada, a pesar de que los soldados de Ordâkh están apostados en las cercanías."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "36.01S"; 
          ["LONG"] = "82.41W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Khanâg en ruinas"; 
      ["PROGRESS"] = "Encuentra el Khanâg en ruinas"; 
      ["LORE"] = "Un khanâg sirve como lugar de descanso para los comerciantes y sus animales en las principales rutas que atraviesan el desierto, y como punto de encuentro y mercado para los habitantes locales del Khûd.\n\nEste khanâg, al este de Jirush, ya no está en funcionamiento y se ha convertido en un lugar en ruinas y desolado. Pocos viajan hasta aquí, y de los que lo hacen, la mayoría tiene motivos para arrepentirse."; 
      ["POINTS"] = {
