  -- Khûd Zagin / Peligros en Khûd Zagin
  [1879491607] = {
      [1] = {
      ["NAME"] = "Samârsug"; 
      ["PROGRESS"] = "Encuentra Samârsug"; 
      ["LORE"] = "Los cocodrilos se han apoderado de las llanuras anegadas al sur del río, y ahora Samârsug solo puede ser explorado por aquellos que no temen los afilados dientes de sus hostiles habitantes."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "23.96S"; 
          ["LONG"] = "91.20W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Nizukhûr"; 
      ["PROGRESS"] = "Encuentra Nizukhûr"; 
      ["LORE"] = "Las paredes resecas por el sol de esta ciudad desértica, que alguna vez fue muy poblada, marcan los límites de Nizukhûr, la 'sede de los bandidos'. Los antiguos residentes abandonaron sus hogares primero a manos de los Ordâkhai que servían a la Serpiente Negra, pero pocos de esos soldados regresaron de la guerra y ahora las viviendas están ocupadas por bandidos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "36.81S"; 
          ["LONG"] = "87.99W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Ar-jirush"; 
      ["PROGRESS"] = "Encuentra Ar-jirush"; 
      ["LORE"] = "Esta fortaleza, que domina el asentamiento de Jirush, aún alberga a muchos soldados de Ordâkh, tanto de la guarnición local como a aquellos que escaparon de la reciente liberación de Ambarûl. Los Ordâkhai vigilan el camino, tendiendo emboscadas a los viajeros que pasan con el fin de cobrarles peajes exorbitantes. El costo de estos peajes aumenta a medida que sube la temperatura, al igual que la amenaza de los Ordâkhai que los cobran."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "33.97S"; 
          ["LONG"] = "80.41W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Phûrakoth"; 
      ["PROGRESS"] = "Encuentra Phûrakoth"; 
      ["LORE"] = "La presencia de los Ordâkhai en Khûd Zagin sigue siendo un peligro para los residentes locales, a pesar de las fuertes pérdidas sufridas por los soldados del Gran Imperio del Sur durante la Guerra del Anillo. La Serpiente Negra no regresará de Gondor, pero muchos de los que lucharon a su lado huyeron de la batalla frente a los muros de Minas Tirith, y se vuelven aún más desesperados y peligrosos al regresar a las tierras que reclaman como suyas."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "40.22S"; 
          ["LONG"] = "73.24W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Nu-hashâr"; 
      ["PROGRESS"] = "Encuentra Nu-hashâr"; 
      ["LORE"] = "Los crebain y las aves carroñeras habitan entre las estructuras angulosas y los acantilados rocosos de Nu-hashâr, protegidos de miradas indeseadas por la empinada ladera desde la que la fortaleza de Ar-jirush domina el Khûd."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "32.99S"; 
          ["LONG"] = "82.23W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Anzusag"; 
      ["PROGRESS"] = "Encuentra Anzusag"; 
      ["LORE"] = "Las aves anidan entre la vegetación de Anzusag, en los acantilados que se elevan sobre el oasis de Shonith. Desde aquí, las arenas del desierto parecen estar muy lejos, como un espejismo lejano."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "42.12S"; 
          ["LONG"] = "71.77W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Er-atûr"; 
      ["PROGRESS"] = "Encuentra Er-atûr"; 
      ["LORE"] = "Er-atûr fue alguna vez un oasis fértil como los demás cuidados por los Kintai, pero ya no es un lugar de vegetación exuberante y verdor. Ahora los espíritus iracundos susurran con el viento y Er-atûr se ha convertido en un lugar de mal agüero."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "40.80S"; 
          ["LONG"] = "81.62W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Ish Dâra"; 
      ["PROGRESS"] = "Encuentra Ish Dâra"; 
      ["LORE"] = "Las orillas del río Usâl alguna vez fueron verdes y fértiles, pero la Gran Sequía secó los campos y dejó a Ish Dâra sumida en la ruina y la decadencia. Ahora solo los lagartos y los escorpiones habitan estas ruinas, y los Khûdi se han marchado en busca de un hogar más acogedor."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "42.47S"; 
          ["LONG"] = "87.92W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Sûr Zugub"; 
      ["PROGRESS"] = "Encuentra Sûr Zugub"; 
      ["LORE"] = "El viento silba a través de los cañones de Sûr Zugub, en los confines meridionales del Khûd, donde los lagartos y otras criaturas se asan sobre las piedras calientes. Se recomienda a los viajeros que se mantengan a la sombra que ofrecen las altas rocas, pues el calor agobiante amenaza con acabar con cualquier viaje imprudente."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "42.40S"; 
          ["LONG"] = "78.43W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Ul Sukûd"; 
      ["PROGRESS"] = "Encuentra Ul Sukûd"; 
      ["LORE"] = "Los espectros merodean entre las ruinas de Ul Sukûd, en lo alto de las criptas de Nirgambâr."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "32.59S"; 
          ["LONG"] = "88.62W"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "Shukabad"; 
      ["PROGRESS"] = "Encuentra Shukabad"; 
      ["LORE"] = "Los chacales de Shukabad nunca duermen. Se mantienen alertas y atentos en todo momento, caminando sigilosamente entre las pilas de huesos y cráneos que llenan su guarida, ansiosos por encontrar al próximo viajero desprevenido que podría convertirse en su próxima comida."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "35.54S"; 
          ["LONG"] = "85.04W"; 
        }; 
      }; 
      };
  };
