  -- Imhûlar / Descubriendo Imhûlar
  [1879491625] = {
      [1] = {
      ["NAME"] = "Kûr Anzar"; 
      ["PROGRESS"] = "Encuentra Kûr Anzar"; 
      ["LORE"] = "Kûr Anzar es una ciudad fortificada construida entre las ruinas de una ciudadela númenóreana que a su vez fue construida sobre los restos de un antiguo fuerte khandari. Originalmente, este era el asiento del Shâr de Hamât, pero siglos de guerras civiles e invasiones desde Gondor la han devastado. Ahora Kûr Anzar está principalmente en manos del remanente Ordâkhai y de los cultistas que sirven a la Iglesia del Omnividente."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "37.78S"; 
          ["LONG"] = "61.55W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Vartúlin"; 
      ["PROGRESS"] = "Encuentra Vartúlin"; 
      ["LORE"] = "Vartúlin es el último bosque de Kinta que sobrevive en los moribundos bosques de Imhûlar, un lugar de descanso para muchos ancianos honorables entre los Kintai. Incluso este refugio ha comenzado a sufrir a medida que la contagiosa devastación finalmente supera la magia élfica que lo protegía durante tanto tiempo."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "42.84S"; 
          ["LONG"] = "64.43W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Urmâkh"; 
      ["PROGRESS"] = "Encuentra Urmâkh"; 
      ["LORE"] = "La ciudad de Urmâkh, en el oeste de Imhûlar, se ha convertido en el hogar de muchos residentes shagâni desplazados de Kûr Anzar. Su ira hacia los soldados de Ordâkh es igualada, si no superada, por su odio hacia los déspotas de Gondor que aparecen prominentemente en los cuentos y leyendas de su tierra."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "37.61S"; 
          ["LONG"] = "66.90W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Tûl Zakana"; 
      ["PROGRESS"] = "Encuentra Tûl Zakana, el Pozo del Olvido"; 
      ["LORE"] = "Escondido en lo profundo del territorio desgarrado por la guerra de Imhûlar, un puesto comercial controlado por los Ordâkh trafica con frascos de un líquido con una reputación peligrosa: agua de Tûl Zakana, el Pozo del Olvido. Los lugareños le aconsejan que se mantenga alejado de Tûl Zakana, ya que muchos han desaparecido en sus cercanías. ¿Se enfrentaron a los Ordâkhai o bebieron demasiado del agua y perdieron todo sentido de sí mismos?"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "40.84S"; 
          ["LONG"] = "56.14W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Tumbas de Esh-kimâkhi"; 
      ["PROGRESS"] = "Encuentra las Tumbas de Esh-kimâkhi"; 
      ["LORE"] = "Las Tumbas de Esh-kimâkhi, los 'reliquias de los tres', fueron construidas por Aragín el Ejecutor, primer rey de Hamât. La cripta triple fue construida en memoria de los tres grandes enemigos que mató antes de romper su espada y dedicar el resto de su vida a la paz."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "40.53S"; 
          ["LONG"] = "61.76W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Atalaya de Urmâkh"; 
      ["PROGRESS"] = "Encuentra la Atalaya de Urmâkh"; 
      ["LORE"] = "Esta prominencia en la cima de la colina fue esculpida por los antiguos pueblos de Hamât para parecerse a la cabeza de un león que domina los bosques moribundos y las tierras aguas abajo."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "32.91S"; 
          ["LONG"] = "72.70W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Dag Usakâra"; 
      ["PROGRESS"] = "Encuentra Dag Usakâra"; 
      ["LORE"] = "Esta es la casa de Usakâr, un anciano ermitaño que vive en el bosque y sigue las antiguas costumbres de venerar a los guardianes del bosque. La extensión de su conocimiento secreto es desconocida incluso para los Kintai, que se cuentan entre sus amigos. Se desespera por la muerte de los árboles y espera que haya algún medio de revertir la plaga que los consume."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "43.03S"; 
          ["LONG"] = "62.77W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Kûgrun"; 
      ["PROGRESS"] = "Encuentra Kûgrun"; 
      ["LORE"] = "Algunos entre los Kintai susurran sobre Kûgrun, el Santuario Dorado, un lugar de paz ubicado en algún lugar del bosque moribundo. Cuando se les presiona, dudan en hablar de su verdadera ubicación por razones propias."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "43.87S"; 
          ["LONG"] = "65.73W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Paso de Nâmbadir"; 
      ["PROGRESS"] = "Encuentra Nâmbadir, el Puente de los Príncipes"; 
      ["LORE"] = "Este alto y desgastado puente de piedra que cruza el Ikorbân fue construido originalmente por los Númenóreanos como parte de su proyecto para canalizar el río. El nombre 'Puente de los Príncipes' se le dio al puente en honor a dos príncipes de Gondor que cayeron en batalla cerca de este lugar."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "32.89S"; 
          ["LONG"] = "59.87W"; 
        }; 
      }; 
      };
  };
