  [1879491627] = {
      [1] = {
      ["NAME"] = "Dûlagig"; 
      ["PROGRESS"] = "Encuentra Dûlagig"; 
      ["LORE"] = "Los escorpiones de Dûlagig habitan demasiado cerca del pueblo de Urmâkh para que los residentes se sientan completamente cómodos, pero algunos han ideado remedios curativos que utilizan partes de escorpión. Estos usos útiles ayudan a evitar que las criaturas se vuelvan demasiado numerosas."; 
      ["POINTS"] = {
