  -- Urash Dâr / Descubriendo Urash Dâr
  [1879491679] = {
      [1] = {
      ["NAME"] = "Ub Nishir"; 
      ["PROGRESS"] = "Encuentra Ub Nishir"; 
      ["LORE"] = "El asentamiento de Ub Nishir, enclavado en un estrecho cañón al norte de la fortaleza de piedra de Maurûsh, está poblado principalmente por bandidos y salteadores de caminos que no tienen a dónde más acudir. Por necesidad, se han convertido en los protectores de las pocas personas que quedan en Urash Dâr."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "23.14S"; 
          ["LONG"] = "62.54W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Nêruzig"; 
      ["PROGRESS"] = "Encuentra Nêruzig"; 
      ["LORE"] = "Desde este pequeño campamento, la gente que permanece en Urash Dâr vigila la grieta recién abierta en Utug-bûr, detrás de la cual acechan terribles males."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.24S"; 
          ["LONG"] = "56.42W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Ilzag Khûl"; 
      ["PROGRESS"] = "Encuentra Ilzag Khûl"; 
      ["LORE"] = "Pocos quedan ya en Ilzag Khûl, pues el mal se agita en la cercana Maurûsh. Ahora debe convertirse en un lugar seguro desde el cual tus aliados puedan atacar a los enemigos que ponen en peligro a todo Urash Dâr."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "26.60S"; 
          ["LONG"] = "61.44W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Shengarâsh"; 
      ["PROGRESS"] = "Encuentra Shengarâsh"; 
      ["LORE"] = "En el idioma shagâni, Shengarâsh significa 'campamento de la lluvia o la niebla'; es un nombre verdaderamente apropiado para este campamento junto a las Cascadas de Ilûritu, en el norte de Urash Dâr."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "16.61S"; 
          ["LONG"] = "62.54W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Canal de Bâdizal"; 
      ["PROGRESS"] = "Encuentra el Canal de Bâdizal"; 
      ["LORE"] = "Esta impresionante obra de mampostería fue construida por los númenóreanos cuando canalizaron el río Ikorbân cerca de Urash Dâr. El proceso llevó muchos años, pero el resultado final amplió la vía fluvial y la hizo más navegable para los barcos númenóreanos que se adentraban en el interior."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "28.34S"; 
          ["LONG"] = "62.18W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Cascadas de Ilûritu"; 
      ["PROGRESS"] = "Encuentra las Cascadas de Ilûritu"; 
      ["LORE"] = "Estas cascadas del norte de Urash Dâr son hermosas y peligrosas, y nadie sabe qué secretos pueden esconder."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "13.78S"; 
          ["LONG"] = "62.73W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Ashâgir"; 
      ["PROGRESS"] = "Encuentra Ashâgir"; 
      ["LORE"] = "Escondida en lo profundo de las tierras del desfiladero, la fortaleza de Ashâgir, situada en lo alto de un acantilado, fue construida en un afloramiento rocoso muy por encima del fondo del cañón. En otro tiempo, un ascensor subía hasta las alturas, pero ese mecanismo fue destruido hace mucho tiempo; ahora solo senderos escarpados serpentean lentamente hasta la elevada entrada. El último rey de Hamât se refugió allí cuando fue invadidido por el Gran Imperio del Sur de Ordâkh, pero ordenó la destrucción de la fortaleza antes que entregarla, y pereció en ella. Ahora Ashâgir yace vacía, despojada de su tesoro."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "19.63S"; 
          ["LONG"] = "70.38W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Sûr Akil"; 
      ["PROGRESS"] = "Encuentra Sûr Akil"; 
      ["LORE"] = "Sûr Akil, el cañón nororiental por el que discurre el río Mûshid, significa 'el desfiladero del dolor' en el idioma de los Shagâni. Nadie recuerda por qué le dieron ese nombre, pero la sensación de un gran mal que se ha apoderado de esta zona en los últimos días parece justificación suficiente."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "21.50S"; 
          ["LONG"] = "57.70W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Malgâma"; 
      ["PROGRESS"] = "Encuentra Malgâma"; 
      ["LORE"] = "La estación de paso de Malgâma atrae a gente de todo tipo, o al menos lo haría si aún quedara una gran población en los asentamientos de Urash Dâr. En cambio, las personas que llegan a este pequeño conjunto de edificios cerca de Zikrum-dûl comparten una cosa en común: su excentricidad."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "26.39S"; 
          ["LONG"] = "52.71W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Utug-bûr"; 
      ["PROGRESS"] = "Encuentra Utug-bûr"; 
      ["LORE"] = "Los recientes terremotos abrieron una fisura en un acantilado que antes era sólido, lo que alteró el curso del río y dejó al descubierto la entrada a Utug-bûr, una estructura de piedra que se mantuvo en secreto durante incontables años. Ya no queda nadie vivo que recuerde cómo se construyó este lugar, y ahora una sensación de gran maldad se apodera de los corazones de quienes se acercan."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "13.21S"; 
          ["LONG"] = "51.61W"; 
        }; 
      }; 
      };
  };
