  -- Imhûlar / Peligros en Shagâna
  [1879503578] = {
      [1] = {
      ["NAME"] = "Nisigurûm"; 
      ["PROGRESS"] = "Encuentra Nisigurûm"; 
      ["LORE"] = "Nisigurûm, o la 'guardia verde', fue una vez parte de una floreciente colección de campamentos humanos en Nisigím, 'el bosque esmeralda'. Ahora el nombre está teñido de tristeza, ya que los bosques que rodean Nisigurûm han sucumbido a la Plaga Pálida y a la influencia corruptora de los Ordâkhai, que ahora controlan Nisigurûm. Los Ordâkhai en Nisigurûm están a su vez comandados por el Shâr de Ekhamât, el cruel Bârshud II."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "46.06S"; 
          ["LONG"] = "60.13W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Garash Kâru"; 
      ["PROGRESS"] = "Encuentra Garash Kâru"; 
      ["LORE"] = "Proporcionando a los Ekhamâti un punto de apoyo en las fértiles tierras de Ambarûl, Garash Kâru se encuentra en la cima de una colina dominante fuera de los pantanos del sur de Ambarûl."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "28.00S"; 
          ["LONG"] = "82.00W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Garash Hûru"; 
      ["PROGRESS"] = "Encuentra Garash Hûru"; 
      ["LORE"] = "Los Ekhamâti han establecido fortificaciones rudimentarias y un campamento rudimentario fuera de un conjunto de fosas en el norte de Khûd Zagin. Pocos saben lo que buscan allí, y si deben temer lo que encuentran."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "34.40S"; 
          ["LONG"] = "76.00W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Az Shûdai"; 
      ["PROGRESS"] = "Encuentra Az Shûdai"; 
      ["LORE"] = "Las altas paredes del cañón forman barreras naturales e impedimentos para el asalto en Az Shûdai, proporcionando una ventaja adicional a los Ordâkhai y Ekhamâti que allí habitan."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "39.60S"; 
          ["LONG"] = "75.99W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Dun Shûma"; 
      ["PROGRESS"] = "Encuentra Dun Shûma"; 
      ["LORE"] = "Se rumorea desde hace mucho tiempo que Dun Shûma, la fortaleza del rey, contiene tesoros de los reyes de Nisaka, una antigua dinastía de los Khûd. Más recientemente, los rumores sugieren que los artefactos de Aragín el Aplacador, famoso antiguo unificador de Shagâna y rey de Hamât, se han difundido, lo que ha llevado a muchos a probar suerte en la búsqueda de estas reliquias del venerado Aragín."; 
