  -- Mûr Ghala / Recuperando An Shêru
  [1879513775] = {
      [1] = {
      ["NAME"] = "Gadim-ûn"; 
      ["PROGRESS"] = "Encuentra Gadim-ûn"; 
      ["LORE"] = "Gadim-ûn, o los Santuarios de Gadim, es una antigua necrópolis que domina el río Ira Blanca desde las alturas en los confines noreste de An Shêru. El antaño desolado osario ahora sirve como escondite de los Jatsakóri, esclavos shagâni fugitivos desesperados por salvar a sus amigos y familiares del yugo Ordâkhai. En meses recientes, los cadáveres de Gadim-ûn han sido despertados por alguna oscura artimaña."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "50.75S"; 
          ["LONG"] = "67.23W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Jiret-menêsh"; 
      ["PROGRESS"] = "Encuentra Jiret-menêsh"; 
      ["LORE"] = "Un antiguo salón de los enanos Temámir, Jiret-menêsh ha sido el hogar de los enanos desde la Primera Edad. En varios momentos de la historia, se han aliado con los Kintai, Nêshak, Zajâna, y los Temámir de la Piedra Costera en Umbar, entre otros. Tras el arrasamiento de Lâkindar y el subsiguiente Estruendo de Piedra, Châmelek Gêta, Señor de Jiret-menêsh, ordenó el cierre de las puertas, aislando a Jiret-menêsh del mundo exterior durante los siguientes cien años, para volver a abrirse solo cuando las amenazas de los Ordâkhai y los Barkhûshim hayan pasado."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "52.57S"; 
          ["LONG"] = "76.80W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Khanâg Gur"; 
      ["PROGRESS"] = "Encuentra Khanâg Gur"; 
      ["LORE"] = "Khanâg Gur es el último khanâg que aún funciona en An Shêru, aunque muchos mercaderes y viajeros todavía no lo consideran un lugar seguro para descansar. Una banda de forajidos llamada los Khanda-khêl, o 'los que Ríen', controla actualmente el khanâg. Su líder, o 'Mashár', es un hombre llamado Halshûm, quien da la bienvenida a los visitantes siempre que gasten dinero durante su estancia. Quienes no gastan lo suficiente suelen encontrarse robados en el camino tras su visita."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "56.87S"; 
          ["LONG"] = "71.88W"; 
        }; 
      }; 
      };
  };
  -- Mûr Ghala / Recuperando Idagâl
  [1879513776] = {
      [1] = {
      ["NAME"] = "Ahâba"; 
      ["PROGRESS"] = "Encuentra Ahâba"; 
      ["LORE"] = "Ahâba, o el 'pozo de las tierras baldías', es un exuberante oasis y hogar del pueblo Beltáni. Tras décadas de intentos de subyugación por parte del Imperio Ordâkh, este antiguo pueblo tarda en confiar en los forasteros, pero para quienes se ganan esa confianza, es un hermoso respiro de las duras condiciones de Idagâl."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "55.23S"; 
          ["LONG"] = "82.39W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "El Guardián del amanecer"; 
      ["PROGRESS"] = "Encuentra el Guardián del Alba"; 
      ["LORE"] = "El Guardián del Alba es una estatua gigante del antiguo rey-héroe de Nísaka, Izighûz Menûndari. A diferencia de su gemela en Khûd Zagin, esta estatua está en su mayor parte intacta. Las tropas de avanzada de Aradûn han hecho recientemente de ella su campamento en preparación para su invasión de Idagâl, para recuperar la región de los Ordâkhai. Desafortunadamente, han aprendido demasiado tarde que la estatua está poseída por una fuerza misteriosa, conocida por la gente local como Ishími, el Viento Atormentado."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "49.34S"; 
          ["LONG"] = "95.95W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Nashûbu"; 
      ["PROGRESS"] = "Encuentra Nashûbu"; 
      ["LORE"] = "Nashûbu es el campamento secreto de las fuerzas de Shâra Mizâdi en una hondonada oculta en la base de los acantilados bajo Emax Dûl. Se dice que aquí hay una manera secreta de romper las defensas de la ciudad enemiga."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "65.47S"; 
          ["LONG"] = "87.24W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Dur Nâgu"; 
      ["PROGRESS"] = "Encuentra Dur Nâgu"; 
      ["LORE"] = "Dur Nâgu, o la 'fortaleza de la isla', son las ruinas de una antigua fortaleza y astillero Nêshakari, donde antaño construían embarcaciones fluviales y las botaban en el río Agâl. En días recientes, se ha convertido en el refugio secreto de esclavos que huyen de la prisión de Esh Mêkag."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "57.35S"; 
          ["LONG"] = "88.64W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Campamento avanzado de Hamâti"; 
      ["PROGRESS"] = "Encuentra el Campamento Avanzado Hamâti"; 
      ["LORE"] = "El Campamento Avanzado Hamâti sirve como punto de apoyo de Mizâdi en Idagâl, desde donde eventualmente lanzará un ataque contra la fortaleza de Emax Dûl y expulsará a los Ordâkhai de Mûr Ghala."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "57.16S"; 
          ["LONG"] = "82.40W"; 
        }; 
      }; 
      };
  };
