  -- Mûr Ghala / Nuevas amenazas en Adagím
  [1879513778] = {
      [1] = {
      ["NAME"] = "Hordírid"; 
      ["PROGRESS"] = "Encuentra Hordírid"; 
      ["LORE"] = "Los árboles de Hordírid se han vuelto feroces y peligrosos con la podredumbre que se extiende por Adagím. La parcela de tierra que los lugareños conocen como el Bosque Despierto es ahora una advertencia para los viajeros que buscan aventurarse en las partes septentrionales del bosque."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "36.73S"; 
          ["LONG"] = "47.22W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Thor Lhîg"; 
      ["PROGRESS"] = "Encuentra Thor Lhîg"; 
      ["LORE"] = "Las raíces de la Colina de la Madre se hunden profundamente en la tierra de Thor Lhîg, propagando la podredumbre en lo más profundo de los árboles mientras sucumben a la Plaga Pálida. Los árboles, antaño hermosos, ahora están corrompidos bajo la sombra del árbol que una vez los alimentó."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "38.33S"; 
          ["LONG"] = "39.96W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Hadrudád"; 
      ["PROGRESS"] = "Encuentra Hadrudád"; 
      ["LORE"] = "Los árboles de Hadrudád no han sentido el dolor de la plaga tanto como otros lugares en Adagím, con el verde todavía visible en la tierra, pero no han sido inmunes. Los árboles de este lugar aún supuran podredumbre y se han vuelto mortales para los viajeros. Los exploradores de Sâr Marsag, al este, los mantienen a raya mientras protegen los caminos hacia Kighân."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "48.00S"; 
          ["LONG"] = "48.00W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Ogultáth"; 
      ["PROGRESS"] = "Encuentra Ogultáth"; 
      ["LORE"] = "Ogultáth es una densa parcela de bosque ahora conocida por los Kintai como 'hondonada de arañas'. La plaga en la tierra ha corrompido a las arañas de este lugar y ha aumentado su agresividad mientras expanden sus telarañas más allá por la región."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "35.90S"; 
          ["LONG"] = "43.63W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Dathrudúsh"; 
      ["PROGRESS"] = "Encuentra Dathrudúsh"; 
      ["LORE"] = "Los Kintai llaman a este lugar la casa de la tejedora, ya que Dathrudúsh ha sido el hogar de las arañas que habitan en lo profundo del pantano durante muchos años. Las raíces del árbol madre ahora empujan la plaga desde la tierra y corrompen a las criaturas de este lugar."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "42.25S"; 
          ["LONG"] = "42.12W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Narchásh"; 
      ["PROGRESS"] = "Encuentra Narchásh"; 
      ["LORE"] = "Las arañas de Narchásh se han ganado el nombre que les dieron los Kintai. Se lo conoce como el agujero del desgarramiento, debido a su naturaleza feroz de acechar a los viajeros que tienen la desgracia de pisar sus telarañas. Las arañas, ahora podridas por la plaga, esparcen el veneno por la tierra para debilitar a sus posibles víctimas."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "44.95S"; 
          ["LONG"] = "49.58W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Thalat Tîr"; 
      ["PROGRESS"] = "Encuentra Thalat Tîr"; 
      ["LORE"] = "Conocido como el valle de los devoradores, las arañas de Thalat Tîr supuran podredumbre que brota de la propia Colina de la Madre, corrompiendo tanto la tierra como a las criaturas por igual. Aquí las arañas son bien conocidas por el pueblo de Adagím y se vuelven monstruosas mientras aguardan al acecho de quien pase por allí."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "39.16S"; 
          ["LONG"] = "38.28W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Fosos de Chortáth"; 
      ["PROGRESS"] = "Encuentra las Fosas de Chortáth"; 
      ["LORE"] = "Las fosas rocosas de Chortáth están sembradas de huesos y cadáveres pertenecientes a quienes se aventuraron demasiado profundo. Es el hogar de una gran manada de chacales que se han adueñado del lugar, usando las rocas laberínticas para acechar a sus presas. Los exploradores kintai de Sâr Marsag luchan regularmente contra las bestias en un intento de tomar la ventaja y proteger los caminos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "51.22S"; 
          ["LONG"] = "49.66W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Mauthark"; 
      ["PROGRESS"] = "Encuentra Mauthark"; 
      ["LORE"] = "Ahora conocido como Mauthark, el bosque cercano a las fronteras de Adagím e Imhular se ha convertido en el hogar de orcos que vagan por el pantano como los únicos aliados de los Ordâkhi dispuestos a tolerar las viles condiciones, mientras amenazan las fronteras de los pocos bosquecillos que quedan de los Kintai."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "45.19S"; 
          ["LONG"] = "52.31W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Mokh Grazádh"; 
      ["PROGRESS"] = "Encuentra Mokh Grazádh"; 
      ["LORE"] = "Mokh Grazádh se ha convertido en una fortaleza para los orcos en el pantano enfermo de Adagím. Con su ubicación central en el bosque, los orcos de este lugar aterrorizan a los Kintai junto con cualquier viajero que se atreva a pisar estos caminos. La amenaza que representan para los elfos crece día a día mientras su atención se vuelca hacia la Plaga Pálida."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "42.68S"; 
          ["LONG"] = "45.98W"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "Lhámuth"; 
      ["PROGRESS"] = "Encuentra Lhámuth"; 
      ["LORE"] = "Lhámuth es el hogar de muchos acechadores de pantano. Antaño un sereno conjunto de estanques, ahora envenenado y mortal por la podredumbre de la tierra. En años recientes, las monstruosidades corrompidas surgidas de los trolls silvanos han comenzado a vagar por estas tierras, perturbando a los acechadores de pantano mientras la plaga los consume."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "40.85S"; 
          ["LONG"] = "44.00W"; 
        }; 
      }; 
      };
      [12] = {
      ["NAME"] = "Antro de los Shadlúgai"; 
      ["PROGRESS"] = "Encuentra la Guarida de los Shadlúgai"; 
      ["LORE"] = "Llamado la Guarida de los Shadlúgai, el pantano de este lugar todavía conserva algo de verde en sus aguas, ya que están lejos del bosque denso y de las raíces del árbol madre. Los Kintai hablan de los gusanos de piedra que viven aquí, acechando en el agua a cualquier presa que se acerque demasiado a sus fauces."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "47.2S"; 
          ["LONG"] = "42.40W"; 
        }; 
      }; 
      };
      [13] = {
      ["NAME"] = "Saig Hathíl"; 
      ["PROGRESS"] = "Encuentra Saig Hathíl"; 
      ["LORE"] = "Ubicado a lo largo del camino hacia Sul Madásh se encuentra Saig Hathíl, las colmenas de la hoja en la lengua común. Hogar de moscas hoz que buscan cualquier lugar para evitar la podredumbre. La pequeña parcela de verde dentro del pantano que sobrevive por la voluntad de los Kintai se ha convertido en su lugar de anidación hasta que la Plaga Pálida se cierne sobre ella."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "42.27S"; 
          ["LONG"] = "39.83W"; 
        }; 
      }; 
      };
      [14] = {
      ["NAME"] = "Fushaum Sûlm"; 
      ["PROGRESS"] = "Encuentra Fushaum Sûlm"; 
      ["LORE"] = "El primer campamento construido por los orcos cuando llegaron a Adagím. Fushaum Sûlm es una fortaleza lo bastante adentrada en los pantanos como para no recibir muchos atacantes, pero fortificada para resistirlos de todos modos. Los orcos la usan para vigilar a los Kintai que custodian el camino hacia Kighân, así como para atacar a cualquier viajero que intente pasar desapercibido."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "50.01S"; 
          ["LONG"] = "40.25W"; 
        }; 
      }; 
      };
  };
