  -- Mûr Ghala / Peligros en Kighân
  [1879513781] = {
      [1] = {
      ["NAME"] = "Shádhag"; 
      ["PROGRESS"] = "Encuentra Shádhag"; 
      ["LORE"] = "La plaga que aflige a Adagím ha echado raíces en Shádhag, justo cruzando la frontera en Kighân. Los lugareños la llaman 'el Bosque Podrido' ya que las plantas comienzan a pudrirse y descomponerse en lo que fue un fértil bosquecillo. Árboles extraños y violentos han tomado control de Shádhag y lo han hecho suyo, atacando a los aldeanos cercanos de Sormedân en días recientes."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "52.96S"; 
          ["LONG"] = "53.92W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Bâdrasag, el Cuerno de la Hoja"; 
      ["PROGRESS"] = "Encuentra Bâdrasag, el Cuerno de la Hoja"; 
      ["LORE"] = "Un manto sombrío pende sobre el aire de Bâdrasag, también conocido como el Cuerno de la Hoja. Antaño una fortaleza de males de la Segunda Edad, el Cuerno de la Hoja ahora está vacío. Los lugareños se mantienen bien alejados, susurrando sobre espíritus extraños y sonidos inquietantes que penetran el aire nocturno en sus alrededores. ¿Qué secretos podrían esconderse en su interior, y qué otros males podría estar refugiando el Cuerno de la Hoja?"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.27S"; 
          ["LONG"] = "8.40W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Medân Makhai"; 
      ["PROGRESS"] = "Encuentra Medân Makhai"; 
      ["LORE"] = "Las abejas de Medân Makhai antes trabajaban junto a los agricultores de Sormedán. Los agricultores les construían refugios y las protegían de depredadores y del frío, y a cambio tomaban una parte de su miel. Sin embargo, recientemente una nueva reina ha causado que las abejas se vuelvan agresivas, algo inusual en ellas, y han atacado y picado salvajemente a los agricultores que intentaban cuidarlas."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "53.57S"; 
          ["LONG"] = "55.91W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Dân Shatagan"; 
      ["PROGRESS"] = "Encuentra Dân Shatagan"; 
      ["LORE"] = "Los salvajes jázgai establecen su campamento cerca del abrevadero de Dân Shatagan. Los lugareños susurran sobre su salvajismo, y especialmente el de su matriarca y líder, a quien han llamado Diente de Sangre."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "60.00S"; 
          ["LONG"] = "54.00W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Khatzâla"; 
      ["PROGRESS"] = "Encuentra Khatzâla"; 
      ["LORE"] = "Khatzâla es el nido de las excéntricas aves conocidas como kalorkhûn. Los kalorkhûn pueden ser bastante agresivos cuando se les molesta. Algunos han sido domesticados y usados como animales de exhibición, aunque solo por los más valientes y aventureros de los zajâni."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "61.60S"; 
          ["LONG"] = "51.00W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Jag Golód"; 
      ["PROGRESS"] = "Encuentra Jag Golód"; 
      ["LORE"] = "Un gran campamento de Ordâkhai en las afueras de Zajâna, aquí es donde permanece gran parte del poderío militar del Consejo Enjoyado. Tras la Mutinería Azul, los Ordâkhai dentro de la ciudad fueron obligados a refugiarse en los Salones de Lajór dentro de Zajâna, o fuera de ella, en Jag Golód. Aquí los Ordâkhai traman su próximo movimiento, e intentan recuperar Zajâna de su odiado enemigo, los Guardianes de la Puerta de Zajâna."; 
      ["POINTS"] = {
        [1] = {
