      [7] = {
      ["NAME"] = "Palacio de Lajór"; 
      ["PROGRESS"] = "Encuentra el Salón de Lajór"; 
      ["LORE"] = "El antiguo palacio imperial de Zajâna, aquí es donde permanece Khastakhól del Consejo Enjoyado y tiene su corte. El Consejo Enjoyado, un gobierno en la sombra del imperio de Ordâkh, alguna vez dominó Zajâna, pero fue derrocado recientemente por el pueblo de Zajâna en la Mutinería Azul. Ahora el Consejo Enjoyado solo controla el Salón y sus alrededores inmediatos. Aunque herido, sigue siendo un peligro que ataque para recuperar toda Zajâna para Ordâkh."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "61.30S"; 
          ["LONG"] = "57.96W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Sâkhazai"; 
      ["PROGRESS"] = "Encuentra Sâkhazai"; 
      ["LORE"] = "Los exuberantes pastizales de Kighân son el entorno perfecto para los gráciles y veloces órices, que hacen de los campos de Sâkhazai su hogar."; 
      ["POINTS"] = {
        [1] = {
