  -- Mûr Ghala / Explorando Kighân
  [1879513782] = {
      [1] = {
      ["NAME"] = "Sormedân"; 
      ["PROGRESS"] = "Encuentra Sormedân"; 
      ["LORE"] = "Sormedân significa 'tierra roja' en el idioma nativo zajâni, así llamado por el suelo rojo y arcilloso del pueblo. Este suelo ha resultado ser bastante fértil, lo que hace que Sormedân y sus alrededores nutran gran parte de Kighân con sus ricos huertos y campos de grano. Los lugareños también crían ganado y abejas, aunque ambos han sufrido disturbios recientemente. Los ancianos de Sormedân también vigilan de cerca el cercano Adagím. La enfermedad que aflige a Adagím se ha extendido recientemente, y amenaza con corromper la abundancia natural de Sormedân."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "56.80S"; 
          ["LONG"] = "52.80W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Ingar-garâsh"; 
      ["PROGRESS"] = "Encuentra Ingar-garâsh"; 
      ["LORE"] = "Un pueblo de tamaño modesto, Ingar-garâsh ha sido abandonado en la batalla entre los Guardianes de la Puerta y el Consejo Enjoyado por el control de Zajâna. Una gran fuerza de Ordâkhai leales al Consejo Enjoyado se encuentra cerca de Ingar-garâsh. Recientemente Shâra Mizâdi ha establecido un campamento en Ingar-garâsh, y ataca a las fuerzas ordâkhai cercanas en su persecución del infame Bârshud II."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "61.60S"; 
          ["LONG"] = "56.80W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Zajâna"; 
      ["PROGRESS"] = "Encuentra la ciudad de Zajâna"; 
      ["LORE"] = "El Joyero de Mûr Ghala, Zajâna es una ciudad de comercio y conocimiento. Ubicada en un cruce afortunado a lo largo del Gran Camino, Zajâna sirve tanto a Umbar como a puntos más al sur, actuando como un gran nexo. Zajâna fue liberada recientemente del control del imperio de Ordâkh, aunque el Consejo Enjoyado leal a Ordâkh aún controla una parte de Zajâna. Los Guardianes de la Puerta han restablecido el gobierno de Zajâna por el pueblo zajâni tras el Motín Azul, y gobiernan la mayor parte de la ciudad como un consejo de iguales.\n\nEl comercio está en el aire y en la cultura de Zajâna, y mercaderes de todas partes acuden a la gran ciudad para vender sus mercancías y hacer fortuna. En otro lugar, los eruditos pohâni trabajan e investigan en la Kalmakhíla, la gran biblioteca de Zajâna donde se guarda gran parte del conocimiento de Mûr Ghala."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "62.40S"; 
          ["LONG"] = "62.40W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Sen Chatâk"; 
      ["PROGRESS"] = "Encuentra Sen Chatâk"; 
      ["LORE"] = "Un fértil pueblo pesquero, Sen Chatâk está ubicado a lo largo del río Ira Blanca. Un pueblo antes pacífico, Sen Chatâk ha visto recientemente amplificados sus problemas con ataques tanto de bandidos como de trasgos, quebrando su antaño tranquilo y amistoso aspecto."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "56.00S"; 
          ["LONG"] = "63.20W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Bosques de Gatúr"; 
      ["PROGRESS"] = "Encuentra los huertos de Gatúr"; 
      ["LORE"] = "Huertos de naranjos que los lugareños de Sormedân mantienen y vigilan. Los huertos prosperan en el suelo arcilloso de Sormedân, produciendo suficiente fruta como para que los agricultores de Sormedân vendan el excedente tanto a Zajâna como a otros pueblos cercanos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "56.20S"; 
          ["LONG"] = "52.72W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Khamósh-engar"; 
      ["PROGRESS"] = "Encuentra Khamósh-engar"; 
      ["LORE"] = "Khamósh-engar es donde los lugareños de Sormedân entierran a sus muertos. Los enterrados aquí tienen sus momentos de muerte plasmados en estelas, piedras talladas que representan el momento y la forma de su muerte."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "55.97S"; 
          ["LONG"] = "53.69W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Cuevas del Tesoro de Hurum Kâna"; 
      ["PROGRESS"] = "Encuentra las cuevas del tesoro de Hurum Kâna"; 
      ["LORE"] = "Un legendario conjunto de cuevas ubicado en las afueras de Zajâna, se rumorea que existe una fabulosa riqueza dentro de las cuevas. Sin embargo, los lugareños dicen que una poderosa maldición recae sobre quienes entran en ellas, por lo que pocos se aventuran adentro. Recientemente, un infame bandido llamado Bârlat el Audaz ha convertido las cuevas en su hogar, desde donde ataca a mercaderes y viajeros en el cercano Gran Camino."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "46.43N"; 
          ["LONG"] = "53.15E"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "El Patio de Larinâsta"; 
      ["PROGRESS"] = "Encuentra la Corte de Larinâsta"; 
      ["LORE"] = "Uno de los muchos mercados dentro de Zajâna, el Larinâsta es donde acuden muchos personajes, tanto honestos como turbios, para hacer sus negocios. Se compra y vende mucho en el Larinâsta. Algunas cosas incluso son legales."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "63.23S"; 
          ["LONG"] = "64.02W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "La Kalmakhíla"; 
      ["PROGRESS"] = "Encuentra la Kalmakhíla"; 
      ["LORE"] = "La gran biblioteca de Zajâna, la Kalmakhíla es un vasto repositorio que contiene gran parte del conocimiento reunido dentro de Mûr Ghala."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "62.31S"; 
          ["LONG"] = "63.56W"; 
        }; 
      }; 
      };
  };
