  -- Mûr Ghala / Nuevas amenazas en An Shêru
  [1879513789] = {
      [1] = {
      ["NAME"] = "Damudûr"; 
      ["PROGRESS"] = "Encuentra Damudûr"; 
      ["LORE"] = "Cerca del nacimiento del río Usâl, una fisura en la ladera de la montaña revela la entrada a Damudûr, una fortaleza de la Primera Edad de los Thardúth. Estas cavernas que antaño albergaron los pozos de cría de los Utúgi han estado ocultas por hechicería desde la época de la derrota de Morgoth, y ahora se revelan de nuevo. ¿Qué peligros yacen en su interior, y qué amenazas ya han surgido?"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "60.60S"; 
          ["LONG"] = "71.09W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Naxar Dâl"; 
      ["PROGRESS"] = "Encuentra Naxar Dâl"; 
      ["LORE"] = "Parte de una antigua necrópolis de Gadim-ûn, que domina el río Ira Blanca. Muchos de los muertos de este lugar han despertado de sus tumbas en meses recientes, su descanso perturbado por alguna oscura hechicería."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "48.70S"; 
          ["LONG"] = "67.13W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Criptas de Khâb Daku"; 
      ["PROGRESS"] = "Encuentra las Criptas de Khâb Daku"; 
      ["LORE"] = "Una cripta a poca distancia al sur de la antigua necrópolis de Gadim-ûn; algo ha perturbado a los muertos, haciendo que sus cuerpos descompuestos abandonen las tumbas y vaguen por la tierra."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "53.43S"; 
          ["LONG"] = "68.69W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Risco del Rapiñador"; 
      ["PROGRESS"] = "Encuentra el Risco del Profanador"; 
      ["LORE"] = "Una colina en el este de An Shêru llamada Sang Luzûkh en shagâni. Sirve como guarida para una gran manada de jázgai, criaturas conocidas por hurgar carroña, pero que atacarán si se sienten amenazadas o si la comida escasea."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "54.16S"; 
          ["LONG"] = "66.60W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Zakhûr"; 
      ["PROGRESS"] = "Encuentra Zakhûr"; 
      ["LORE"] = "Antaño un bosquecillo exuberante y verde de los Kintai, esta colina es ahora un refugio para bandidos y otros forajidos en medio de un desierto seco y rocoso. Los elfos ya se han ido, pero aún permanecen varios Veróthi, los árboles que quedan cuando un elfo ha alcanzado el Trothúl."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "56.06S"; 
          ["LONG"] = "66.22W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Erakúndo, Las Vetas agotadas"; 
      ["PROGRESS"] = "Encuentra las Vetas Agotadas"; 
      ["LORE"] = "Una mina abandonada llamada Erakúndo por los Ordâkhi. Se usó por última vez en tiempos de Shurash Hûl, el emperador de Ordâkh, quien condujo a sus ejércitos al norte hacia Shagâna, destruyendo el río Usâl y gran parte del Mûr. Este lugar ahora es hogar de mûmakil salvajes, bestias de carga que han sobrevivido o escapado de las guerras de los Hombres."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "58.90S"; 
          ["LONG"] = "68.74W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Abníshu"; 
      ["PROGRESS"] = "Encuentra Abníshu"; 
      ["LORE"] = "El lugar de anidación de los Kalorkhûn, aterradoras aves de tamaño inusual, que hicieron su hogar en las alturas del cielo. Algunos dicen que saben a pollo."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "54.50S"; 
          ["LONG"] = "71.90W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Los Pozos Hirvientes"; 
      ["PROGRESS"] = "Encuentra los Pozos Hirvientes"; 
      ["LORE"] = "Aguas termales ácidas en el norte de An Shêru, llamadas Shêgarim por los lugareños, han hervido hasta la superficie desde el Estruendo de Piedra. Aunque el agua de este lugar puede quemar o matar a la mayoría de los animales, los gusanos de roca han descubierto que el agua sobrecalentada y acre es de su agrado."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "53.85S"; 
          ["LONG"] = "73.94W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Estanques de Taridím"; 
      ["PROGRESS"] = "Encuentra los Estanques de Taridím"; 
      ["LORE"] = "Aguas termales ácidas en el sur de An Shêru que han hervido hasta la superficie desde el Estruendo de Piedra. Aunque el agua de este lugar puede quemar o matar a la mayoría de los animales, los gusanos de roca han descubierto que el agua sobrecalentada y acre es de su agrado."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "58.36S"; 
          ["LONG"] = "74.37W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Nido de los Anzûri"; 
      ["PROGRESS"] = "Encuentra el Perchero de los Anzûri"; 
      ["LORE"] = "Esta cima de montaña en las alturas del cielo es hogar de una colonia de rocs, llamados anzûri en shagâna, aves gigantes tan hostiles como enormes."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "50.13S"; 
          ["LONG"] = "72.95W"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "Onabóha"; 
      ["PROGRESS"] = "Encuentra Onabóha"; 
      ["LORE"] = "Un puesto avanzado de los Ordâkhai de Shêru, desde aquí despachan patrullas e intentan mantener el control del lado occidental de la región."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "55.98S"; 
          ["LONG"] = "76.95W"; 
        }; 
      }; 
      };
      [12] = {
      ["NAME"] = "Los Campos de la bestia"; 
      ["PROGRESS"] = "Encuentra los Campos de las Bestias"; 
      ["LORE"] = "Llamados Modan Rôkh en ordâkhai, los Campos de las Bestias reciben su nombre por los sûlokil que se suelen encontrar allí."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "59.22S"; 
          ["LONG"] = "77.63W"; 
        }; 
      }; 
      };
      [13] = {
      ["NAME"] = "Uruthúsh"; 
      ["PROGRESS"] = "Encuentra Uruthúsh"; 
      ["LORE"] = "Uno debe ser muy valiente o muy necio para entrar en Uruthúsh, ya que es el hogar de una temible banda de Utûgi, orcos a los que Morgoth dio vida en los Días Antiguos mediante su oscura artimaña."; 
      ["POINTS"] = {
