  -- Mûr Ghala / Explorando Adagím
  [1879513790] = {
      [1] = {
      ["NAME"] = "Sul Madásh"; 
      ["PROGRESS"] = "Encuentra Sul Madásh"; 
      ["LORE"] = "El valle de la belleza, como se le conoce en el kintár nativo. Sul Madásh es el principal asentamiento-bosquecillo de Adagím. Un santuario verde que domina la devastación, escondido entre arroyos en cascada dentro de un pliegue del Mûr oriental, pero la infección solo puede contenerse por un tiempo mientras el número de elfos sigue disminuyendo.\n\nLos caciques de Sul Madásh, una pareja casada – Ildimár el esposo, Dáthlil la esposa – han mantenido a raya la Plaga Pálida hasta ahora, pero saben que la batalla pronto se perderá. Desafiantes hasta el final, tienen la intención de caer luchando."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "46.31S"; 
          ["LONG"] = "35.72W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Laivárth"; 
      ["PROGRESS"] = "Encuentra Laivárth"; 
      ["LORE"] = "Un bosquecillo Kinta, hasta ahora intacto, que ha comenzado a sucumbir a la Plaga Pálida. El cuidador del bosquecillo, un ermitaño llamado Tálbiral, ha arrasado el bosque alrededor del bosquecillo en un intento de formar una barrera contra la podredumbre."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "39.30S"; 
          ["LONG"] = "46.34W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Sâr Marsag"; 
      ["PROGRESS"] = "Encuentra Sâr Marsag"; 
      ["LORE"] = "Sâr Marsag, el último campamento en el camino hacia Kighân, es mantenido por los exploradores de Adagím como un bastión dentro del bosque en descomposición. Mantienen su hoguera encendida para servir de faro a los viajeros, indicándoles que estarán seguros aquí mientras la batalla contra la Plaga Pálida continúa."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "48.13S"; 
          ["LONG"] = "45.08W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "La Locura de Nagakhêdi"; 
      ["PROGRESS"] = "Encuentra el Legado del Necio de Nagakhêdi"; 
      ["LORE"] = "Una antigua maravilla anterior al Estruendo de Piedra, tallada en la ladera de la montaña en Adagím. La estructura estaba siendo construida por un gobernante que quería dejar su huella en este mundo, conocido como Nagakhêdi. La maravilla quedó inconclusa y sellada hace mucho tiempo.\n\nLos Kintai del bosque han dejado la estructura intacta durante años, ya que la vieron como un esfuerzo fútil desde el principio, incluso llamándola ahora el 'Descenso del Necio', y su atención se ha centrado en proteger sus bosquecillos contra la plaga que arrasa sus tierras. La puerta sellada tiene grietas en su piedra y un aire fétido se filtra desde su interior."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "52.73S"; 
          ["LONG"] = "33.59W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Tûl Ama"; 
      ["PROGRESS"] = "Encuentra Tûl Ama"; 
      ["LORE"] = "Tûl Ama, conocida como la Colina de la Madre, es un afloramiento donde antaño creció una encina gigante, una de las más antiguas de Shagâna, llamada la Vieja Madre en cuentos y canciones. Ahora está muriendo, la podredumbre fúngica ascendiendo por su enorme tronco y haciéndola llorar savia ensangrentada mientras sus hojas se ennegrecen y marchitan.\n\nLa guardiana de la colina, Irsinith, ha comulgado con el árbol durante siglos y habla en su nombre, aunque la aflicción del árbol la ha dejado enferma y consumida por el dolor."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "40.70S"; 
          ["LONG"] = "41.31W"; 
        }; 
      }; 
      };
  };
