  -- Mûr Ghala / Nuevas amenazas en Idagâl
  [1879513793] = {
      [1] = {
      ["NAME"] = "El Refugio de Kidu-bâla"; 
      ["PROGRESS"] = "Encuentra el Refugio de Kidu-bâla"; 
      ["LORE"] = "Kidu-bâla, o 'refugio rebelde', es un campamento al borde de un acantilado de bandidos y desertores Ordâkhai que han declarado su independencia tanto de las leyes del imperio como de cualquier reino advenedizo que reclame dominio sobre Idagâl. Acechan a viajeros desesperados y roban los escasos recursos que tiene el pueblo Beltáni local."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "10.48S"; 
          ["LONG"] = "39.25W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Duríga"; 
      ["PROGRESS"] = "Encuentra Duríga"; 
      ["LORE"] = "Los bandidos de Duríga, o 'la hendidura de los espigadores', sobreviven asaltando patrullas Ordâkhai y robando las raciones de los esclavos fugitivos que se esconden en las ruinas de Dur Nâgu."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "60.89S"; 
          ["LONG"] = "88.19W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Templo de Shahûru"; 
      ["PROGRESS"] = "Encuentra el Santuario de Shahûru"; 
      ["LORE"] = "Shahûru, o 'santuario en una cima', es todo lo que queda de un antiguo templo Nêshak donde la gente local dejaba ofrendas, orando por cosechas abundantes y las bendiciones de la lluvia. La identidad del ser al que rezaba el pueblo del Mûr se ha perdido con el tiempo, pero los indicios sugieren que era femenino."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "51.99S"; 
          ["LONG"] = "82.42W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "La Carrera Chirriante"; 
      ["PROGRESS"] = "Encuentra la Cantera del Rechinador"; 
      ["LORE"] = "La Cantera del Rechinador, o 'Haraz Hûr', es solo la parte superior de una gran colmena de grodbog. Prosperan en los acantilados debido a las profundas grietas en la roca que conducen al agua subterránea, abiertas por el Estruendo de Piedra hace más de cien años."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "44.10S"; 
          ["LONG"] = "94.17W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Nax Shalâl"; 
      ["PROGRESS"] = "Encuentra Nax Shalâl"; 
      ["LORE"] = "Nax Shalâl, o 'el Foso Serpenteante', es un oasis oculto entre los acantilados. Lo que sería un refugio para el pueblo de Idagâl se ha vuelto demasiado peligroso para acercarse, ya que la población local de cobras ha crecido enormemente."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "53.63S"; 
          ["LONG"] = "95.38W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Ushumût"; 
      ["PROGRESS"] = "Encuentra Ushumût"; 
      ["LORE"] = "Ushumût, o la Tumba de las Serpientes, son los restos de tres enormes dragones y hogar de los dragonzuelos salvajes de Idagâl. Los Beltáni han transmitido la leyenda de la caída de estos dragones, llamados Ahûshu, Nuzêru y Rabûg. Cuentan que Shurug-nîn, el héroe mítico de la Primera Edad, los abatió, y sus cuerpos cayeron en el lago donde descansaron durante miles de años. Fue solo relativamente recientemente que el Estruendo de Piedra drenó el lago y reveló al mundo la tumba de los dragones."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "53.59S"; 
          ["LONG"] = "88.81W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "La Atalaya Marchita"; 
      ["PROGRESS"] = "Encuentra la Atalaya Marchita"; 
      ["LORE"] = "La Atalaya Marchita, u Okhatohól, fue en su día una próspera ciudad shagâni que dominaba el río Agâl. El Estruendo de Piedra, la desecación del lago y la invasión de los Ordâkhai fueron dejando la ciudad casi abandonada, ya que la gente huía en busca de una vida mejor. En años recientes, los Ordâkhai han tomado por completo la ciudad, para usarla como base norteña desde donde lanzar incursiones. Los pocos residentes que quedaban fueron capturados y nunca más se les volvió a ver."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "50.51S"; 
          ["LONG"] = "86.17W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Jolakhúro"; 
      ["PROGRESS"] = "Encuentra Jolakhúro"; 
      ["LORE"] = "Jolakhúro, o 'muesca del túnel', es el campamento avanzado Ordâkhai que vigila el camino hacia su fortaleza principal en Emax Dûl. Los soldados allí vigilan la aproximación de enemigos, y son los primeros enviados en respuesta a problemas en otros lugares de Idagâl."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "62.97S"; 
          ["LONG"] = "83.26W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Emax Dûl"; 
      ["PROGRESS"] = "Encuentra Emax Dûl"; 
      ["LORE"] = "Emax Dûl, 'alto salón de la hendidura', o la Fortaleza Alta, es una antigua fortaleza que ha resistido el ascenso y la caída de las muchas dinastías tanto de Nêshak como de Nísaka. Ahora es el asiento del poder de los Ordâkhai en Mûr Ghala, y hogar de la familia real del príncipe heredero del imperio."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "65.41S"; 
          ["LONG"] = "88.70W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Karmu Râx"; 
      ["PROGRESS"] = "Encuentra Karmu Râx"; 
      ["LORE"] = "Karmu Râx, o 'el montículo de las tortugas', es el lugar de reunión de muchas tortugas del pavor a lo largo del hilo de agua que queda del río Agâl. Las aguas poco profundas y el refugio que ofrecen los viejos restos de embarcaciones varadas por el Estruendo de Piedra resultan un entorno adecuado para los reptiles."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "56.81S"; 
          ["LONG"] = "85.56W"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "La Cicatriz Profunda"; 
      ["PROGRESS"] = "Encuentra la Mina Marcada"; 
      ["LORE"] = "La Mina Marcada, o 'Góbor-noti', es lo que queda de una antigua mina a cielo abierto tallada en el acantilado por los Ordâkhai. Una vez que el mineral se agotó, se convirtió en un corral de contención para mûmakil. Cuando los Ordâkhai comenzaron a perder el control de la región tras su derrota en la Batalla de los Campos de Pelennor, también perdieron el control de los mûmakil que albergaba la mina. Las grandes bestias ahora corren en libertad por todo Idagâl."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "58.78S"; 
          ["LONG"] = "82.61W"; 
        }; 
      }; 
      };
      [12] = {
      ["NAME"] = "Tumbas de Khâb Ishil"; 
      ["PROGRESS"] = "Encuentra las Tumbas de Khâb Ishil"; 
      ["LORE"] = "Khâb Ishil, o 'la tumba de fragmentos', es la antigua casa funeraria de los héroes de los reinos de Nêshak y Nísaka. Fue sellada hace mucho tiempo y quedó intacta durante cientos de años. El Estruendo de Piedra sacudió la tierra y abrió la tumba, permitiendo que los kergrim entraran, la profanaran y la convirtieran en su nido."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "49.89S"; 
          ["LONG"] = "91.13W"; 
        }; 
      }; 
      };
      [13] = {
      ["NAME"] = "Mina a cielo abierto de Esh Mêkag"; 
      ["PROGRESS"] = "Encuentra Esh Mêkag"; 
      ["LORE"] = "Esh Mêkag, la 'Boca Silenciosa', es una antigua fortaleza Nêshakari construida en los acantilados de piedra del Mûr. En años recientes, los Ordâkhai han convertido la fortaleza en una horrible prisión y campo de trabajo. Los sacerdotes de Barkhûsh supervisan la subyugación de gente de toda Shagâna, quienes se convierten en esclavos del imperio."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "60.01S"; 
          ["LONG"] = "90.90W"; 
        }; 
      }; 
      };
  };
